#[cfg(test)]
mod the_shortcut_table_is_honest {
    use super::*;

    /// A help page that lists a key the code does not bind is worse than no help page. These are
    /// the ones this session added, checked against the handler that binds them.
    #[test]
    fn the_3d_keys_listed_are_the_3d_keys_bound() {
        let src = include_str!("app.rs");
        let a = src.find("// ---- 3D VIEWPORT HOTKEYS").expect("the handler");
        let b = src[a..].find("\n                if (self.active_view").map(|e| a + e).unwrap();
        let body = &src[a..b];
        let group = SHORTCUTS.iter().find(|g| g.title == "3D Factory").expect("the group");
        for (listed, key) in [
            ("M", "Key::M"), ("R", "Key::R"), ("Tab", "Key::Tab"), ("F", "Key::F"),
            ("G", "Key::G"), ("H", "Key::H"), ("S", "Key::S"), ("A", "Key::A"),
        ] {
            assert!(
                group.rows.iter().any(|r| r.keys == listed || r.keys.starts_with(listed)),
                "{listed} is bound but not listed",
            );
            assert!(body.contains(key), "{listed} is listed but {key} is not bound");
        }
    }

    /// No blanks, and no duplicated key within one group — two rows claiming the same key is the
    /// shape of a shortcut that was moved and half-updated.
    #[test]
    fn every_row_is_filled_in_and_unique_within_its_group() {
        for g in SHORTCUTS {
            assert!(!g.title.is_empty() && !g.scope.is_empty(), "a group needs a title and a scope");
            assert!(!g.rows.is_empty(), "{} lists nothing", g.title);
            let mut seen: Vec<&str> = Vec::new();
            for row in g.rows {
                assert!(!row.keys.is_empty() && !row.what.is_empty(), "{}: a blank row", g.title);
                assert!(!seen.contains(&row.keys), "{}: '{}' listed twice", g.title, row.keys);
                seen.push(row.keys);
            }
        }
    }

    /// The 3D group must say it needs the viewport to be active. A key that silently does nothing
    /// because you have not clicked into the view yet reads as a broken key.
    #[test]
    fn the_3d_group_states_its_gate() {
        let g = SHORTCUTS.iter().find(|g| g.title == "3D Factory").unwrap();
        assert!(g.scope.contains("ACTIVE"), "the gate has to be stated: {}", g.scope);
    }
}

/// A WRAPPED MENU BAR MUST NOT SWITCH MENUS ON HOVER.
///
/// Reported as: "while selecting something from the drop down menu, when i move the cursor it
/// opens the menu of whatever is below it." egui opens a menu on
/// `button.clicked() || (button.hovered() && another menu is open)` — right for a single-row menu
/// bar, wrong for one that WRAPS, because the next row sits directly beneath the one you opened
/// and `menu_spacing` leaves a strip of it exposed above the panel.
///
/// The first attempt made the bar a single scrolling row. That removed the second row, and with it
/// the symptom, by changing the layout — which is not what was asked for, and the user said so:
/// "i asked to fix the hover selecting problem not change the layout."
#[cfg(test)]
mod the_toolbars_wrap_and_do_not_hover_switch {
    use super::*;

    fn source_between(anchor: &'static str, src: &'static str) -> String {
        let a = src.find(anchor).unwrap_or_else(|| panic!("anchor not found: {anchor}"));
        let w = src[a..].find("horizontal_wrapped").map(|e| a + e).expect("the bar wraps");
        let bytes = src.as_bytes();
        let (mut depth, mut seen, mut end) = (0i32, false, src.len());
        for (i, &c) in bytes.iter().enumerate().skip(w) {
            if c == b'{' {
                depth += 1;
                seen = true;
            } else if c == b'}' {
                depth -= 1;
            }
            if seen && depth == 0 {
                end = i;
                break;
            }
        }
        src[w..end].to_string()
    }

    /// THE LAYOUT STAYS WRAPPED. Both bars stack when the panel is narrow, as they always did.
    #[test]
    fn both_bars_still_wrap() {
        let app = include_str!("app.rs");
        let light = include_str!("light.rs");
        assert!(
            source_between("plus Frame and Clear. Both dropdowns drive the SAME code", app)
                .starts_with("horizontal_wrapped"),
            "the 3D Factory toolbar must wrap, not scroll",
        );
        assert!(
            source_between("pub fn toolbar_ui", light).starts_with("horizontal_wrapped"),
            "the SIMLUX toolbar must wrap, not scroll",
        );
        // Checked on the EXTRACTED bodies, never on the whole file: a test that greps a file for
        // the thing it forbids finds its own assertion and fails on itself. The first version of
        // this did exactly that.
        for (name, body) in [
            ("3D Factory", source_between("plus Frame and Clear. Both dropdowns drive the SAME code", app)),
            ("SIMLUX", source_between("pub fn toolbar_ui", light)),
        ] {
            assert!(
                !body.contains("ScrollArea::horizontal"),
                "{name} toolbar scrolls instead of wrapping",
            );
        }
    }

    /// …and every menu on them opens on CLICK ONLY. A single `ui.menu_button` left on either bar
    /// is one button that still swaps under the cursor.
    #[test]
    fn no_hover_switching_menu_survives_on_either_bar() {
        for (name, body) in [
            (
                "3D Factory",
                source_between("plus Frame and Clear. Both dropdowns drive the SAME code", include_str!("app.rs")),
            ),
            ("SIMLUX", source_between("pub fn toolbar_ui", include_str!("light.rs"))),
        ] {
            assert!(
                !body.contains("ui.menu_button("),
                "{name} toolbar still has a hover-switching menu_button",
            );
            assert!(body.contains("click_menu_button("), "{name} toolbar uses the click-only menu");
        }
    }

    /// The fix is clearing the BUTTON's hover, and it must be the response handed to egui — not
    /// the one handed back to the caller, which still needs its hover for tooltips.
    #[test]
    fn the_gate_is_on_the_response_egui_reads() {
        let src = include_str!("app.rs");
        let a = src.find("pub(crate) fn click_menu_button").expect("the helper");
        let b = src[a..].find("\n}").map(|e| a + e).unwrap();
        let f = &src[a..b];
        assert!(f.contains("gated.hovered = false"), "the gated copy is what egui must see");
        assert!(f.contains("bar_menu(&gated"), "…and it is what is passed to bar_menu");
        assert!(f.contains("InnerResponse::new(inner, resp)"), "the caller gets the real response");
    }
}

/// WHERE DOES THE 3D FACTORY VIEWPORT ACTUALLY GO?
///
/// Reported twice: "the simlux window ... only extends to a length and when extend it beyond that
/// it goes behind the 3d factory window." The screenshots are cropped, so the geometry cannot be
/// read off them. This measures it instead: run real headless egui frames with the SIMLUX panel
/// widened step by step, and record what rect each panel ends up with.
#[cfg(test)]
mod panel_geometry_measurement {
    use super::*;

    const W: f32 = 2763.0;
    const H: f32 = 1298.0;

    /// Drive one frame with the SIMLUX panel forced to `simlux_w`, and report
    /// `(simlux_rect, factory_rect, central_rect)`.
    fn frame(app: &mut CadApp, ctx: &egui::Context, simlux_w: f32) -> (egui::Rect, egui::Rect, egui::Rect) {
        // Force the stored panel width the way a drag would.
        ctx.data_mut(|d| {
            d.insert_persisted(
                egui::Id::new("simlux_3d_panel"),
                egui::containers::panel::PanelState {
                    rect: egui::Rect::from_min_size(
                        egui::pos2(W - simlux_w, 0.0),
                        egui::vec2(simlux_w, H),
                    ),
                },
            );
        });
        let input = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(W, H))),
            ..Default::default()
        };
        let mut central = egui::Rect::NOTHING;
        let _ = ctx.run(input, |ctx| {
            app.render_light_3d_panel(ctx);
            app.render_factory_panel(ctx);
            egui::CentralPanel::default().show(ctx, |ui| {
                central = ui.max_rect();
            });
        });
        let get = |id: &str| {
            egui::containers::panel::PanelState::load(ctx, egui::Id::new(id))
                .map(|s| s.rect)
                .unwrap_or(egui::Rect::NOTHING)
        };
        (get("simlux_3d_panel"), get("factory_3d_panel"), central)
    }

    /// THE MEASUREMENT. Prints the geometry at a range of SIMLUX widths so the failure mode is
    /// visible as numbers rather than inferred from a cropped screenshot.
    #[test]
    fn the_panels_never_overlap_at_any_simlux_width() {
        let mut app = CadApp::default();
        app.two_d_open = true;
        app.factory.open = true;
        app.light.view3d_open = true;
        app.factory.add_box();
        app.factory.recompute();
        let ctx = egui::Context::default();

        // A warm-up frame: egui needs one pass to settle panel state and widget sizes.
        let _ = frame(&mut app, &ctx, 600.0);

        let mut bad = Vec::new();
        for w in [400.0_f32, 800.0, 1200.0, 1600.0, 2000.0, 2200.0, 2400.0, 2500.0, 2600.0, 2700.0] {
            let (s, f, c) = frame(&mut app, &ctx, w);
            println!(
                "asked {w:>6.0}  simlux {:>7.1}..{:<7.1} ({:>6.1})   factory {:>7.1}..{:<7.1} ({:>6.1})   central {:>7.1}..{:<7.1} ({:>6.1})",
                s.left(), s.right(), s.width(),
                f.left(), f.right(), f.width(),
                c.left(), c.right(), c.width(),
            );
            // The factory panel must sit entirely LEFT of the SIMLUX panel.
            if f.right() > s.left() + 0.5 {
                bad.push(format!(
                    "at simlux width {w:.0}: factory panel reaches {:.1} but SIMLUX starts at {:.1} \
                     — they overlap by {:.1} px",
                    f.right(), s.left(), f.right() - s.left(),
                ));
            }
            // …and the 2D canvas must keep something usable.
            if c.width() < 1.0 {
                bad.push(format!("at simlux width {w:.0}: the 2D canvas is {:.1} px wide", c.width()));
            }
        }
        assert!(bad.is_empty(), "panel geometry breaks down:\n  {}", bad.join("\n  "));
    }

    /// EACH VIEW ALONE CAN FILL THE WINDOW. "make sure the windows of 2d cad 3d factory and simlux
    /// can be extended to which ever length the user prefers and they can close any of them to
    /// have any of the single window open."
    #[test]
    fn one_view_alone_gets_the_whole_window() {
        // SIMLUX alone.
        let mut app = CadApp::default();
        app.two_d_open = false;
        app.factory.open = false;
        app.light.view3d_open = true;
        let ctx = egui::Context::default();
        let _ = frame(&mut app, &ctx, 600.0);
        let (s, _f, _c) = frame(&mut app, &ctx, W);
        println!("simlux alone: {:.1}..{:.1} ({:.1}) of {W}", s.left(), s.right(), s.width());
        assert!(
            s.width() > W - MIN_VIEW_W - 1.0,
            "with the others closed SIMLUX must take the window, got {:.1} of {W}",
            s.width(),
        );

        // The 3D Factory alone. A panel keeps whatever width it was dragged to — it does not grow
        // on its own — so what is under test is that its LIMIT allows the whole window. Drag it
        // there, the way the user would.
        let mut app = CadApp::default();
        app.two_d_open = false;
        app.factory.open = true;
        app.light.view3d_open = false;
        let ctx = egui::Context::default();
        let _ = frame(&mut app, &ctx, 600.0);
        ctx.data_mut(|d| {
            d.insert_persisted(
                egui::Id::new("factory_3d_panel"),
                egui::containers::panel::PanelState {
                    rect: egui::Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(W, H)),
                },
            );
        });
        let (_s, f, _c) = frame(&mut app, &ctx, 600.0);
        println!("factory alone: {:.1}..{:.1} ({:.1}) of {W}", f.left(), f.right(), f.width());
        assert!(
            f.width() > W - MIN_VIEW_W - 1.0,
            "with the others closed the 3D Factory must be allowed the window, got {:.1} of {W}",
            f.width(),
        );

        // The 2D canvas alone.
        let mut app = CadApp::default();
        app.two_d_open = true;
        app.factory.open = false;
        app.light.view3d_open = false;
        let ctx = egui::Context::default();
        let _ = frame(&mut app, &ctx, 600.0);
        let (_s, _f, c) = frame(&mut app, &ctx, 600.0);
        println!("2D alone: {:.1}..{:.1} ({:.1}) of {W}", c.left(), c.right(), c.width());
        assert!(c.width() > W - 40.0, "the 2D canvas alone must take the window, got {:.1}", c.width());
    }

    /// Closing the last view must not leave an empty window.
    #[test]
    fn the_last_view_cannot_be_closed() {
        let mut app = CadApp::default();
        app.two_d_open = false;
        app.factory.open = false;
        app.light.view3d_open = false;
        app.light.simlux_mode = false;
        app.keep_one_view_open();
        assert!(app.two_d_open, "closing the last view must bring one back");
    }
}

/// THE QUIT DIALOG MUST STAY REACHABLE.
///
/// Reported as: "when i close the app and the save or not windows shows, if i click accidentally
/// outside the window the app stops responding."
///
/// The dimmed backdrop and the dialog were both `Order::Foreground`. Within one order egui raises
/// an area to the top when you interact with it, so clicking the backdrop put a full-screen,
/// click-swallowing overlay ON TOP of the dialog: the buttons became unreachable, `close_confirm`
/// stayed true and the close stayed vetoed. The app was running and repainting the whole time —
/// it just could not be answered or quit.
#[cfg(test)]
mod the_quit_dialog_cannot_trap_the_app {
    use super::*;

    fn body() -> &'static str {
        let src = include_str!("app.rs");
        let a = src.find("fn render_close_confirm").expect("the dialog");
        let b = src[a..].find("\n    /// ").map(|e| a + e).unwrap_or(src.len());
        &src[a..b]
    }

    /// The backdrop must be strictly BELOW the dialog, so no click can raise it over the buttons.
    #[test]
    fn the_backdrop_is_below_the_dialog() {
        let b = body();
        let backdrop = b.find("close_confirm_backdrop").expect("the backdrop");
        let win = b.find("Window::new(\"close_confirm\")").expect("the dialog window");
        assert!(backdrop < win, "the backdrop must be declared before the dialog");

        // The order each one is given, taken from its own section of the function.
        let backdrop_order = b[backdrop..win].contains("Order::Middle");
        let dialog_order = b[win..].contains("Order::Foreground");
        assert!(
            backdrop_order,
            "the backdrop must be Order::Middle — at Foreground a click raises it over the dialog",
        );
        assert!(dialog_order, "the dialog must be Order::Foreground, above the backdrop");
        assert!(
            !b[backdrop..win].contains("Order::Foreground"),
            "the backdrop must NOT share the dialog's order — that is the reported hang",
        );
    }

    /// And there must be a keyboard way out regardless.
    #[test]
    fn escape_dismisses_it() {
        let b = body();
        let esc = b.find("Key::Escape").expect("Esc must dismiss the dialog");
        let backdrop = b.find("close_confirm_backdrop").unwrap();
        assert!(esc < backdrop, "the Esc check must run before anything can swallow input");
        assert!(
            b[esc..backdrop].contains("self.close_confirm = false"),
            "Esc must actually clear the flag that vetoes the close",
        );
    }

    /// Answering it must not leave the app permanently unable to quit: every button clears
    /// `close_confirm`, and exactly one of them authorises the close.
    #[test]
    fn every_button_clears_the_veto() {
        let b = body();
        assert_eq!(
            b.matches("self.close_confirm = false").count(),
            4,
            "Esc + Save + Don't Save + Cancel must each clear the veto",
        );
        assert!(b.contains("self.pending_close = true"), "Close without saving authorises the close");
        assert!(b.contains("self.close_after_save = true"), "Save and close authorises it after the save");
    }
}

/// A SKETCH BELONGS TO ITS OWN PLANE.
///
/// Reported as: "i drew a sketch on a wall … see how the same drawing is getting drawn in the
/// ground plane too."
///
/// `factory_enter_sketch` REPLACES `self.doc` with the sketch and parks the real drawing in
/// `session.saved_doc`. Every site that means THE PLAN must therefore say so — the swap makes the
/// wrong document the default, and reading `self.doc` at a plan site lays the sketch's u/v out as
/// world x/y on the ground.
/// A `debug_assert!` MUST NOT BE THE THING THAT DOES THE WORK.
///
/// It expands to `if cfg!(debug_assertions) { assert!(…) }`, and `cfg!` is a compile-time
/// constant — so in a RELEASE build the expression inside is never evaluated at all.
///
/// THIS SHIPPED. `factory_restore_stashed_cutters` wrapped its restore call in one, so the
/// installed binary put NOTHING back when a cutout edit was escaped: the openings stayed deleted,
/// which is precisely the data loss the stash exists to prevent. Every test runs in a debug build,
/// so no amount of testing the behaviour could have found it — only reading the code, or the user.


/// A CUT SAYS WHAT IT WAS FOR, INSTEAD OF BEING GUESSED AT AFTERWARDS.
///
/// "Does the cutter span the wall?" is the only question geometry alone can answer, and a blind
/// recess fails it BY CONSTRUCTION — stopping inside the wall is the whole point of a recess. So
/// the ⚠ DOES-NOT-REACH warning fired on every pocket in the model. Measured on the real
/// 172-feature project: 18 openings flagged, of which 6 were recesses working exactly as drawn.
/// A warning that cries wolf on a third of its cases is one people learn to scroll past, which is
/// worse than no warning — the genuinely stopped cuts were in the same list.
#[cfg(test)]
mod a_cut_records_what_it_was_for {
    use super::*;

    /// A 4 m x 0.3 m wall, 3 m high, with a face sketch open on its outside face — the state the
    /// Cut command runs from.
    fn a_wall_ready_to_cut() -> CadApp {
        let mut app = CadApp::default();
        app.factory
            .add_wall(vec![glam::Vec2::new(0.0, 0.0), glam::Vec2::new(4.0, 0.0)], 0.3, 3.0)
            .expect("a wall");
        app.factory.recompute();
        // Draw on the wall's +Y face, looking at it from outside.
        let frame = cad_solid::Frame::from_point_normal(
            glam::Vec3::new(2.0, 0.15, 1.5),
            glam::Vec3::Y,
        );
        app.factory_enter_sketch(frame);
        // A 1 m square opening, centred where the frame's origin landed.
        let c = cad_kernel::Circle { center: Vec2::new(0.0, 0.0), radius: 0.5 };
        app.doc.push(cad_kernel::DObject::new(cad_kernel::Geom::Circle(c)));
        app
    }

    fn last_cut(app: &CadApp) -> &cad_solid::Feature {
        app.factory
            .model
            .features
            .iter()
            .rev()
            .find(|f| f.op == cad_solid::BoolOp::Difference)
            .expect("a cut was made")
    }

    /// THE RECORD IS MADE. Both ways round, because a field that is always `Some(true)` would
    /// satisfy the through case and quietly reinstate the whole defect for recesses.
    #[test]
    fn a_through_cut_and_a_recess_are_told_apart_at_the_moment_they_are_cut() {
        let mut app = a_wall_ready_to_cut();
        assert!(app.factory_cut_sketch(true) > 0, "the through cut must be made");
        assert_eq!(
            last_cut(&app).through, Some(true),
            "a through cut did not record that it was meant to go through",
        );

        let mut app = a_wall_ready_to_cut();
        app.factory.element_height = 0.1;
        assert!(app.factory_cut_sketch(false) > 0, "the recess must be made");
        assert_eq!(
            last_cut(&app).through, Some(false),
            "a recess did not record that it was meant to stop",
        );
    }

    /// AND A RECESS IS NOT REPORTED AS A FAILURE. The diagnostic counts it as a recess rather
    /// than flagging it, which is the whole point of recording the intent.
    #[test]
    fn a_recess_is_not_flagged_as_an_opening_that_does_not_reach() {
        let mut app = a_wall_ready_to_cut();
        app.factory.element_height = 0.1;
        assert!(app.factory_cut_sketch(false) > 0, "the recess must be made");
        app.factory_exit_sketch();
        app.factory.recompute();

        let report = app.factory_geometry_report().join("\n");
        let line = report
            .lines()
            .find(|l| l.contains("openings:"))
            .unwrap_or_else(|| panic!("no openings line in:\n{report}"));
        assert!(
            line.contains("1 are recesses"),
            "the recess was not counted as one: {line}",
        );
        assert!(
            !report.contains("does not reach") && !report.contains("short by"),
            "a recess working exactly as drawn was reported as a failure:\n{report}",
        );
    }

    /// AN OPENING CUT BEFORE THE FIELD EXISTED STILL GETS AN ANSWER. `None` means nobody said, and
    /// the reader falls back to measuring — which is what the app did everywhere, and is still
    /// right for every project already on disk.
    #[test]
    fn an_opening_with_no_recorded_intent_falls_back_to_measuring() {
        let mut app = a_wall_ready_to_cut();
        assert!(app.factory_cut_sketch(true) > 0);
        app.factory_exit_sketch();
        // Erase the record, exactly as a project saved before the field carries it.
        let id = last_cut(&app).id;
        if let Some(f) = app.factory.model.get_mut(id) {
            f.through = None;
        }
        app.factory.recompute();

        let report = app.factory_geometry_report().join("\n");
        let line = report
            .lines()
            .find(|l| l.contains("openings:"))
            .unwrap_or_else(|| panic!("the diagnostic gave up on it:\n{report}"));
        // MEASURED, not assumed. Reading `None` as "recess" would silence the warning for every
        // opening in every project already on disk — the reverse of the defect, and just as quiet.
        assert!(
            line.contains("0 are recesses"),
            "an opening with no recorded intent was counted as a recess instead of being \
             measured: {line}",
        );
        assert!(
            line.contains("1 go fully through"),
            "an opening with no recorded intent was not measured at all: {line}",
        );
    }
}
/// A PLANE'S DRAWING IS PART OF THE DRAWING, AND SHARES ITS TABLES.
///
/// A face sketch is a whole `Document` of its own, built from `Document::default()` — so it
/// starts with DEFAULT tables while the drawing it belongs to has the user's. Every dobject names
/// its layer, linetype, colour slot, text style, dimension style, wall style and block BY INDEX,
/// so an object drawn on a plane against default tables means something ELSE the moment it is
/// read against the drawing's: index 3 was "Dashed" and is now "Center", index 2 was a 5 mm
/// annotation style and is now a 200 mm title.
///
/// Layers were carried across when somebody noticed the colours were wrong. Blocks were carried
/// across when somebody noticed the Insert list was empty. The other six were still default, and
/// would have been found the same way, one complaint at a time.
#[cfg(test)]
mod a_plane_shares_the_drawings_tables {
    use super::*;

    /// A plan carrying one non-default entry in EVERY shared table, so a table that fails to
    /// cross is visible as a missing name rather than as a subtly different number.
    fn a_plan_with_its_own_tables() -> CadApp {
        let mut app = CadApp::default();
        app.doc.layers.add(cad_kernel::Layer { name: "SETTING OUT".into(), ..cad_kernel::Layer::layer_zero() });
        app.doc.linetypes.add(cad_kernel::Linetype::new("Site boundary", &[9.0, 3.0]));
        app.doc.text_styles.add(cad_kernel::TextStyle {
            name: "Annotation".into(),
            ..cad_kernel::TextStyle::standard()
        });
        app.doc.dim_styles.add(cad_kernel::DimStyle {
            name: "Setting out".into(),
            ..cad_kernel::DimStyle::standard()
        });
        app.doc.wall_styles.add(cad_kernel::WallStyle {
            name: "Blockwork".into(),
            ..cad_kernel::WallStyle::standard()
        });
        app.doc.blocks.add(cad_kernel::Block {
            name: "DOOR".into(),
            base: Vec2::new(0.0, 0.0),
            dobjects: Vec::new(),
            smart: false,
            params: Vec::new(),
            cut_edges: Vec::new(),
        });
        app
    }

    /// What every table in a document is called, as one set — so a test can say "the plane can
    /// see all of this" without naming eight accessors.
    fn table_names(d: &cad_kernel::Document) -> Vec<String> {
        let mut v: Vec<String> = Vec::new();
        v.extend(d.layers.layers.iter().map(|x| format!("layer:{}", x.name)));
        v.extend(d.linetypes.linetypes.iter().map(|x| format!("ltype:{}", x.name)));
        v.extend(d.text_styles.styles.iter().map(|x| format!("text:{}", x.name)));
        v.extend(d.dim_styles.styles.iter().map(|x| format!("dim:{}", x.name)));
        v.extend(d.wall_styles.styles.iter().map(|x| format!("wall:{}", x.name)));
        v.extend(d.blocks.blocks.iter().map(|x| format!("block:{}", x.name)));
        v
    }

    /// THE WAY IN. Everything the drawing knows about, the plane knows about.
    #[test]
    fn a_plane_opens_with_the_drawings_tables() {
        let mut app = a_plan_with_its_own_tables();
        let want = table_names(&app.doc);
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        let got = table_names(&app.doc); // `self.doc` IS the sketch while a session is open
        assert_eq!(
            want, got,
            "the plane opened with different tables from the drawing it belongs to",
        );
    }

    /// THE WAY OUT. A style added while drawing on a face belongs to the drawing — the same rule
    /// layers and blocks already followed, and for the same reason: it is the drawing's.
    #[test]
    fn a_style_created_on_a_plane_comes_back_to_the_drawing() {
        let mut app = a_plan_with_its_own_tables();
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        app.doc.text_styles.add(cad_kernel::TextStyle {
            name: "Drawn on a face".into(),
            ..cad_kernel::TextStyle::standard()
        });
        app.doc.linetypes.add(cad_kernel::Linetype::new("Drawn on a face", &[1.0, 1.0]));
        app.factory_exit_sketch();

        assert!(
            app.doc.text_styles.find("Drawn on a face").is_some(),
            "a text style made while sketching was lost when the sketch closed",
        );
        assert!(
            app.doc.linetypes.find("Drawn on a face").is_some(),
            "a linetype made while sketching was lost when the sketch closed",
        );
    }

    /// AND THE IDS STILL MEAN THE SAME THING. This is the point of sharing rather than merging:
    /// an object drawn on the plane keeps its index, and that index answers to the same entry in
    /// the drawing's table as it did in the sketch's.
    #[test]
    fn an_id_used_on_a_plane_resolves_to_the_same_entry_in_the_plan() {
        let mut app = a_plan_with_its_own_tables();
        let id = app.doc.linetypes.find("Site boundary").expect("the fixture linetype");
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        let in_sketch = app.doc.linetypes.get(id).map(|l| l.name.clone());
        app.factory_exit_sketch();
        let in_plan = app.doc.linetypes.get(id).map(|l| l.name.clone());
        assert_eq!(
            in_sketch.as_deref(), Some("Site boundary"),
            "linetype {id} means something else on a plane: {in_sketch:?}",
        );
        assert_eq!(in_sketch, in_plan, "the same id names two different linetypes");
    }

    /// THE PLANE KEEPS A COPY TOO. It is drawn in the plan and in 3D long after the session
    /// closed, and a `BlockRef` or a styled Text left on it has to resolve then as well.
    #[test]
    fn the_plane_keeps_the_tables_after_the_session_closes() {
        let mut app = a_plan_with_its_own_tables();
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        app.factory_exit_sketch();
        let sk = &app.factory.model.sketches[0];
        assert!(
            sk.doc.blocks.find("DOOR").is_some(),
            "the plane's own document lost the block table, so a BlockRef on it resolves to \
             nothing when the plane is drawn",
        );
    }

    /// UNITS ARE NOT A TABLE AND DO NOT CROSS. What one drawing unit means is a fact about a
    /// FILE. A sketch that adopted the plan's unit would rescale everything already drawn on it,
    /// which is a silent rescale of the user's work arriving as a side effect of a style fix.
    /// The unit mismatch between a plan and its planes is a real defect with a fix of its own.
    #[test]
    fn the_unit_is_not_carried_across_by_the_table_merge() {
        let mut app = a_plan_with_its_own_tables();
        app.doc.units = cad_kernel::DocUnits::new(0.001, cad_kernel::UnitSource::Declared);
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        assert!(
            (app.doc.units.metres_per_unit - 1.0).abs() < 1e-12,
            "the table merge silently rescaled the plane to {} m/unit",
            app.doc.units.metres_per_unit,
        );
    }
}

/// A LOOP INSIDE ANOTHER LOOP IS A HOLE IN IT.
///
/// Every closed loop on a face sketch used to extrude as its own solid, so a plate drawn with four
/// bolt circles came out as five posts and the drafter had to cut the holes back out by hand —
/// four more features, each of which then had to be kept beside the plate for ever.
#[cfg(test)]
mod a_loop_inside_a_loop_is_a_hole {
    use super::*;

    fn square(cx: f32, cy: f32, half: f32) -> Vec<glam::Vec2> {
        vec![
            glam::Vec2::new(cx - half, cy - half),
            glam::Vec2::new(cx + half, cy - half),
            glam::Vec2::new(cx + half, cy + half),
            glam::Vec2::new(cx - half, cy + half),
        ]
    }

    /// Two loops side by side are two objects, and must stay two — the case that would break if
    /// nesting were decided by size alone.
    #[test]
    fn two_separate_shapes_stay_two_shapes() {
        let out = CadApp::nest_loops(vec![square(0.0, 0.0, 4.0), square(20.0, 0.0, 1.0)]);
        assert_eq!(out.len(), 2, "two disjoint loops became {} object(s)", out.len());
        assert!(out.iter().all(|(_, h)| h.is_empty()), "a disjoint loop was taken as a hole");
    }

    /// The headline. One plate, four bolt holes, ONE object.
    #[test]
    fn a_plate_with_four_bolt_circles_is_one_object_with_four_holes() {
        let mut loops = vec![square(0.0, 0.0, 8.0)];
        for &(x, y) in &[(-4.0_f32, -4.0_f32), (4.0, -4.0), (4.0, 4.0), (-4.0, 4.0)] {
            loops.push(square(x, y, 1.0));
        }
        let out = CadApp::nest_loops(loops);
        assert_eq!(out.len(), 1, "the plate and its bolt holes became {} objects", out.len());
        assert_eq!(out[0].1.len(), 4, "the plate came out with {} holes", out[0].1.len());
    }

    /// ORDER MUST NOT MATTER. The loops arrive in whatever order the drafter drew them, and a
    /// version that assumed the outline came first would work for everybody who drew the plate
    /// before the holes and silently invert for everybody who did not.
    #[test]
    fn the_holes_are_found_whichever_order_they_were_drawn_in() {
        let inner = square(0.0, 0.0, 1.0);
        let outer = square(0.0, 0.0, 8.0);
        for (a, b) in [(outer.clone(), inner.clone()), (inner.clone(), outer.clone())] {
            let out = CadApp::nest_loops(vec![a, b]);
            assert_eq!(out.len(), 1, "drawn in this order it made {} objects", out.len());
            assert_eq!(out[0].1.len(), 1, "the hole was lost");
            // And the OUTLINE is the big one, not the small one.
            let span = out[0].0.iter().fold(0.0_f32, |m, p| m.max(p.x));
            assert!((span - 8.0).abs() < 1e-4, "the hole was taken as the outline");
        }
    }

    /// AN ISLAND IN A HOLE IS SOLID AGAIN. Even-odd nesting is the only rule that gets this
    /// right: a washer with a pin standing in its bore is a washer with a hole AND a pin, not a
    /// washer with two holes one of which is filled in.
    #[test]
    fn an_island_inside_a_hole_becomes_its_own_object() {
        let out = CadApp::nest_loops(vec![
            square(0.0, 0.0, 8.0),  // the plate
            square(0.0, 0.0, 4.0),  // a hole in it
            square(0.0, 0.0, 1.0),  // a pin standing in the hole
        ]);
        assert_eq!(out.len(), 2, "expected the plate and the pin, got {} objects", out.len());
        let plate = out.iter().find(|(o, _)| o.iter().any(|p| p.x > 7.0)).expect("the plate");
        assert_eq!(plate.1.len(), 1, "the plate must have exactly one hole");
        let pin = out.iter().find(|(o, _)| o.iter().all(|p| p.x.abs() < 2.0)).expect("the pin");
        assert!(pin.1.is_empty(), "the pin picked up a hole of its own");
    }

    /// A HOLE BELONGS TO THE LOOP THAT ACTUALLY CONTAINS IT, not to the biggest one on the sheet.
    /// Two plates side by side, one hole in each: sorting by area and attaching every hole to the
    /// largest outline would put both holes in one plate and leave the other solid.
    #[test]
    fn each_plate_keeps_its_own_hole() {
        let out = CadApp::nest_loops(vec![
            square(0.0, 0.0, 8.0),
            square(0.0, 0.0, 1.0),
            square(30.0, 0.0, 6.0),
            square(30.0, 0.0, 1.0),
        ]);
        assert_eq!(out.len(), 2, "expected two plates, got {}", out.len());
        for (outline, holes) in &out {
            assert_eq!(holes.len(), 1, "a plate ended up with {} holes", holes.len());
            let cx = outline.iter().map(|p| p.x).sum::<f32>() / outline.len() as f32;
            let hx = holes[0].iter().map(|p| p.x).sum::<f32>() / holes[0].len() as f32;
            assert!(
                (cx - hx).abs() < 1.0,
                "a hole at x = {hx} was attached to the plate at x = {cx}",
            );
        }
    }


    /// One loop on its own is one object with no holes — the ordinary case, and the early return.
    #[test]
    fn a_single_loop_is_one_object() {
        let out = CadApp::nest_loops(vec![square(0.0, 0.0, 4.0)]);
        assert_eq!(out.len(), 1);
        assert!(out[0].1.is_empty());
    }
}

/// THE FOLDER BROWSER SHOWS YOU WHAT IS IN THE FOLDER.
///

/// TWO UNIT SPACES, ONE APP.
///
/// The 2D plan is measured in whatever the drawing declares — millimetres, for an architectural
/// DXF. A face sketch is a `Document` of its OWN and its coordinates are METRES. `self.doc`
/// alternates between the two as a sketch is opened and closed, and anything carried across
/// without conversion changes meaning by a factor of a thousand with nothing to report it.
///
/// A metre-declared plan and a face sketch are byte-identical `{1.0, Declared}`, so NOTHING ABOUT
/// THE NUMBER can tell them apart — every fix here works from the RATIO between the plan document
/// and the active one, which is exactly 1 when no sketch is open.
#[cfg(test)]
mod two_unit_spaces {
    use super::*;

    /// A plan in millimetres with a wall on it, and nothing else.
    fn mm_plan() -> CadApp {
        let mut app = CadApp::default();
        app.doc.units = cad_kernel::DocUnits::new(0.001, cad_kernel::UnitSource::Declared);
        app.doc.push(cad_kernel::DObject::new(cad_kernel::Geom::Line(cad_kernel::Line {
            a: Vec2::new(0.0, 0.0),
            b: Vec2::new(3000.0, 0.0), // a 3 m wall, in millimetres
        })));
        app
    }

    // ── THE GRID ───────────────────────────────────────────────────────────────────────────

    /// `GrdSpc` IS THE SAME PHYSICAL SPACING IN BOTH SPACES. 10 on a millimetre plan is 10 mm; on
    /// a face sketch measured in metres the same stored 10 was a TEN METRE grid — three orders of
    /// magnitude coarser than the wall being drawn on, and a snap rounding every click to the
    /// nearest ten metres.
    #[test]
    fn the_grid_is_the_same_size_on_a_plane_as_on_the_plan() {
        let mut app = mm_plan();
        app.env.GrdSpc = 10.0; // 10 mm
        let on_plan = app.grid_spacing();
        assert!((on_plan - 10.0).abs() < 1e-9, "the plan's own grid changed: {on_plan}");

        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        let in_sketch = app.grid_spacing();
        // The sketch is in metres, so the same 10 mm is 0.01 of a unit there.
        assert!(
            (in_sketch - 0.01).abs() < 1e-9,
            "a 10 mm grid became {in_sketch} units in a face sketch — {}x out",
            in_sketch / 0.01,
        );
    }

    /// AND NOTHING CHANGES WHEN THERE IS NO SKETCH. The ratio is exactly 1, so every existing
    /// drawing snaps and draws its grid precisely as before — the property that makes this safe
    /// to add at all.
    #[test]
    fn the_grid_is_untouched_with_no_sketch_open() {
        for unit in [1.0_f64, 0.001, 0.01, 25.4 / 1000.0] {
            let mut app = CadApp::default();
            app.doc.units = cad_kernel::DocUnits::new(unit, cad_kernel::UnitSource::Declared);
            app.env.GrdSpc = 7.5;
            assert_eq!(
                app.grid_spacing(), 7.5,
                "at {unit} m/unit the grid moved without a sketch being open",
            );
        }
    }

    // ── THE CLIPBOARD ──────────────────────────────────────────────────────────────────────

    /// A 3 m WALL STAYS 3 m ACROSS THE SPACES. Copied off a millimetre plan it is 3000 units;
    /// pasted into a metre-measured sketch unconverted it became a THREE KILOMETRE wall — no
    /// error, the view simply jumps and the drawing is somewhere past the horizon.
    #[test]
    fn a_wall_copied_from_the_plan_keeps_its_size_on_a_plane() {
        let mut app = mm_plan();
        // The LAST index, not 0 — a default `CadApp` is not an empty drawing.
        app.selection = vec![app.doc.dobjects.len() - 1];
        app.copy_selection();
        assert_eq!(app.clipboard_dobjects.len(), 1, "the fixture must copy something");

        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        let before = app.doc.dobjects.len();
        app.start_paste();
        app.commit_paste(Vec2::new(0.0, 0.0), Vec2::new(0.0, 0.0));
        assert_eq!(app.doc.dobjects.len(), before + 1, "nothing was pasted");

        let g = &app.doc.dobjects[before].geom;
        let (mn, mx) = g.bbox();
        let len = mx.x - mn.x;
        assert!(
            (len - 3.0).abs() < 1e-6,
            "a 3 m wall pasted into a metre sketch as {len} units — {:.0}x out",
            len / 3.0,
        );
    }

    /// AND A PASTE INSIDE ONE DOCUMENT IS UNTOUCHED — the identity, which is every copy and paste
    /// anybody has ever done in this app.
    #[test]
    fn pasting_within_one_drawing_is_unchanged() {
        let mut app = mm_plan();
        app.selection = vec![app.doc.dobjects.len() - 1];
        app.copy_selection();
        let before = app.doc.dobjects.len();
        app.start_paste();
        app.commit_paste(Vec2::new(0.0, 0.0), Vec2::new(500.0, 0.0));

        let g = &app.doc.dobjects[before].geom;
        let (mn, mx) = g.bbox();
        assert!(
            ((mx.x - mn.x) - 3000.0).abs() < 1e-6,
            "a same-document paste rescaled the geometry to {}",
            mx.x - mn.x,
        );
        assert!((mn.x - 500.0).abs() < 1e-6, "…and it landed at {}, not the destination", mn.x);
    }

    /// THE OTHER DIRECTION TOO. Drawn on a plane in metres, pasted onto a millimetre plan — the
    /// conversion is a ratio, and a ratio that only works one way round is a coincidence.
    #[test]
    fn geometry_drawn_on_a_plane_keeps_its_size_back_on_the_plan() {
        let mut app = mm_plan();
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        // A 2 m line, drawn in the sketch's metres.
        app.doc.push(cad_kernel::DObject::new(cad_kernel::Geom::Line(cad_kernel::Line {
            a: Vec2::new(0.0, 0.0),
            b: Vec2::new(2.0, 0.0),
        })));
        let i = app.doc.dobjects.len() - 1;
        app.selection = vec![i];
        app.copy_selection();
        app.factory_exit_sketch();

        let before = app.doc.dobjects.len();
        app.start_paste();
        app.commit_paste(Vec2::new(0.0, 0.0), Vec2::new(0.0, 0.0));
        let (mn, mx) = app.doc.dobjects[before].geom.bbox();
        assert!(
            ((mx.x - mn.x) - 2000.0).abs() < 1e-3,
            "a 2 m line pasted onto a millimetre plan as {} units, not 2000",
            mx.x - mn.x,
        );
    }
}
/// Reported as: "when i try to import an ies/ldt file in the block to fitting tab its not
/// detecting the ies/ldt files in the folder. instead its opening this" — with a screenshot of a
/// window titled "Choose output folder · Radiance render", listing "(no folders or * files here)",
/// pointed at a directory full of .ldt files.
///
/// Three separate things, one dialog:
///   * `PickFolder` listed NO files at all, "folders only". Right for choosing where to WRITE,
///     wrong for choosing a folder because of what is IN it.
///   * the title was the Radiance one whichever of the three callers had opened it;
///   * and the empty-list line printed the filter raw, so an empty filter read "* files".
#[cfg(test)]
mod the_folder_browser_shows_what_is_in_the_folder {
    use super::*;

    /// THE REPORTED CASE. A photometry folder pick must list photometry.
    #[test]
    fn a_photometry_folder_pick_lists_ies_and_ldt() {
        for name in ["FONDO.ldt", "FONDO.LDT", "downlight.ies", "TRACK.IES"] {
            assert!(
                CadApp::dialog_lists(FileDialogMode::PickFolder, ".ies|.ldt", name),
                "{name} was not listed, so the folder looks empty",
            );
        }
    }

    /// …AND NOTHING ELSE, or the list becomes every file on disk and says nothing.
    #[test]
    fn a_photometry_folder_pick_lists_only_photometry() {
        for name in ["plan.dxf", "notes.txt", "render.hdr", "ldt", "ies.txt"] {
            assert!(
                !CadApp::dialog_lists(FileDialogMode::PickFolder, ".ies|.ldt", name),
                "{name} has no business in a photometry list",
            );
        }
    }

    /// AN OUTPUT FOLDER STILL SHOWS FOLDERS ONLY. You are choosing where to WRITE, and what
    /// happens to be there already is none of the caller's business — so an empty filter keeps the
    /// old behaviour exactly, and the Radiance picker is unchanged.
    #[test]
    fn an_output_folder_pick_lists_no_files() {
        for name in ["anything.ldt", "old_render.hdr", "plan.dxf"] {
            assert!(
                !CadApp::dialog_lists(FileDialogMode::PickFolder, "", name),
                "{name} appeared in an output-folder pick",
            );
        }
    }

    /// EVERY OTHER MODE IS UNTOUCHED. The filter was moved out of the directory walk to make it
    /// testable, and a refactor that quietly changed one of these would be worse than the defect.
    #[test]
    fn the_other_modes_filter_exactly_as_before() {
        let cases: &[(FileDialogMode, &str, &[&str], &[&str])] = &[
            (FileDialogMode::Open, "", &["a.dxf", "a.rsm", "a.DWG"], &["a.ies", "a.png"]),
            (FileDialogMode::ImportIes, "", &["a.ies", "a.LDT"], &["a.dxf", "a.png"]),
            (FileDialogMode::ImportHdri, "", &["sky.hdr", "sky.EXR"], &["sky.png", "sky.dxf"]),
            (FileDialogMode::ImportObj, "", &["c.obj", "c.3ds", "c.fbx", "c.glb", "c.gltf"], &["c.dxf"]),
            (FileDialogMode::ImportTexture, "", &["t.png", "t.JPG", "t.tiff"], &["t.dxf", "t.hdr"]),
            (FileDialogMode::Save, ".rsm", &["out.rsm"], &["out.dxf"]),
        ];
        for (mode, ext, yes, no) in cases {
            for n in *yes {
                assert!(CadApp::dialog_lists(*mode, ext, n), "{mode:?} must list {n}");
            }
            for n in *no {
                assert!(!CadApp::dialog_lists(*mode, ext, n), "{mode:?} must not list {n}");
            }
        }
    }

    /// A SAVE WITH NO EXTENSION LISTS NOTHING rather than everything. `ends_with("")` is true for
    /// every string, so the empty-filter guard is load-bearing here as well as on the folder pick.
    #[test]
    fn an_empty_filter_never_matches_everything() {
        assert!(!CadApp::dialog_lists(FileDialogMode::Save, "", "anything.at.all"));
    }

    /// THE TITLE NAMES THE FOLDER YOU ARE ACTUALLY CHOOSING. Three callers share one dialog mode,
    /// and it announced a Radiance render to all three.
    #[test]
    fn the_folder_dialog_is_titled_for_whoever_asked() {
        let mut app = CadApp::default();
        assert!(
            app.folder_dialog_title().contains("Radiance"),
            "the default caller is the render output folder",
        );

        app.photometry_wants_folder = true;
        let t = app.folder_dialog_title();
        assert!(
            !t.contains("Radiance") && (t.contains(".ldt") || t.contains(".ies")),
            "the photometry pick is titled {t:?}",
        );

        app.photometry_wants_folder = false;
        app.texset_target = Some(0);
        let t = app.folder_dialog_title();
        assert!(!t.contains("Radiance"), "the texture-set pick is titled {t:?}");
    }

    /// CLICKING A FILE IN A FOLDER PICK MUST NOT GO THROUGH `filename`.
    ///
    /// Reported as "why cant i select it", looking at a browser listing FONDO.ldt. The files were
    /// deliberately inert, because a folder pick reads `filename` as the NEW SUBFOLDER TO CREATE —
    /// so selecting FONDO.ldt would have offered to make a directory called FONDO.ldt inside the
    /// folder the user was trying to choose.
    ///
    /// Clicking one now confirms the FOLDER directly, and the `clear()` before it is the whole of
    /// what keeps the old hazard shut. Asserted on the source because the click needs a live egui
    /// context, and because the thing worth protecting is the ORDER of two statements — which no
    /// behavioural test of the finished dialog would notice until somebody had already lost a
    /// folder to it.
    #[test]
    fn a_folder_pick_never_confirms_with_a_file_name_in_the_subfolder_field() {
        let src = include_str!("app.rs");
        let anchor = "IN A FOLDER PICK, CLICKING A FILE TAKES ITS FOLDER.";
        let a = src.find(anchor).expect("the folder-pick file row");
        // The row ends where the ordinary (non-folder) rows resume.
        let b = src[a..]
            .find("let selected = dlg.filename.eq_ignore_ascii_case(f);")
            .map(|e| a + e)
            .expect("the ordinary file row follows it");
        let body = &src[a..b];

        assert!(
            body.contains("do_confirm = true;"),
            "clicking a file in a folder pick does nothing — which is what was reported",
        );
        let clear = body.find("dlg.filename.clear();").expect(
            "the file name must be cleared, or the folder pick treats it as a subfolder to create",
        );
        let confirm = body.find("do_confirm = true;").expect("checked above");
        assert!(
            clear < confirm,
            "the clear must come BEFORE the confirm, or FONDO.ldt is read as a new subfolder",
        );
    }

    /// AND THE PREVIEW PANE STOPS ASKING FOR SOMETHING THIS MODE CANNOT DO. "(select a file)" is
    /// right for an Open and, in a folder pick, invites the one action that used to do nothing.
    #[test]
    fn a_folder_pick_does_not_ask_you_to_select_a_file() {
        let src = include_str!("app.rs");
        let a = src.find("SAY WHAT THIS MODE ACTUALLY WANTS").expect("the preview hint");
        let b = src[a..].find("crate::theme::typ::data_code()").map(|e| a + e).unwrap();
        let body = &src[a..b];
        assert!(
            body.contains("FileDialogMode::PickFolder"),
            "the preview hint no longer distinguishes a folder pick",
        );
    }
}

#[cfg(test)]
mod a_debug_assert_never_does_the_work {
    /// The rule is narrow on purpose. A `debug_assert!` over a pure predicate is fine and there
    /// are plenty of those; what is banned is a MUTATION inside one.
    #[test]
    fn nothing_is_mutated_inside_a_debug_assert() {
        // Verbs that change the model rather than ask it a question. Spelled without their
        // opening bracket so this list does not trip its own check.
        const MUTATORS: [&str; 6] =
            ["insert_after", "insert_at", ".push", ".remove", ".pop", ".take"];
        for (name, src) in
            [("app.rs", include_str!("app.rs")), ("factory.rs", include_str!("factory.rs"))]
        {
            let mut from = 0usize;
            while let Some(rel) = src[from..].find("debug_assert!(") {
                let open = from + rel + "debug_assert!".len();
                // Balanced scan to the closing bracket, so a call spread over several lines is
                // covered as well as a one-liner.
                let mut depth = 0i32;
                let mut end = open;
                for (i, c) in src[open..].char_indices() {
                    match c {
                        '(' => depth += 1,
                        ')' => {
                            depth -= 1;
                            if depth == 0 {
                                end = open + i;
                                break;
                            }
                        }
                        _ => {}
                    }
                }
                let inside = &src[open..end];
                let line = src[..open].lines().count();
                for verb in MUTATORS {
                    assert!(
                        !inside.contains(&format!("{verb}(")),
                        "{name}:{line}: `{verb}` is called inside a debug_assert!, so it does not \
                         happen in a release build:\n    {}",
                        inside.trim(),
                    );
                }
                from = end.max(open + 1);
            }
        }
    }
}

#[cfg(test)]
mod a_sketch_is_not_the_plan {
    use super::*;

    /// Both plan underlays — the depth-tested one and the x-ray one — must read `plan_doc`.
    /// Asserted on the source because the drawing needs a live GL context a unit test has not got.
    ///
    /// THE DEPTH-TESTED ANCHOR MOVED, and the move is worth recording. The plan used to be
    /// resolved inline in the frame; it is now resolved in `refresh_cached_lines`, because that
    /// builder is cached. This test caught that as a failure — correctly, by its own terms — and
    /// the fix is to follow the code rather than to relax the rule. The hazard it names has not
    /// changed: read the sketch instead of the plan, or take the scale from the sketch's units,
    /// and a millimetre plan draws at 1000x with everything else still green.
    #[test]
    fn both_plan_underlays_read_the_plan() {
        let src = include_str!("app.rs");
        for (what, anchor, end) in [
            ("depth-tested", "fn refresh_cached_lines", "\n    /// THE DRAWING CHANGED"),
            ("x-ray", "fn paint_plan_underlay", "\n    fn "),
        ] {
            let a = src.find(anchor).unwrap_or_else(|| panic!("{what}: anchor gone"));
            let b = src[a + anchor.len()..].find(end).map(|e| a + anchor.len() + e).unwrap_or(src.len());
            let body = &src[a..b];
            assert!(
                body.contains("plan_doc_of(self.factory.session.as_ref()"),
                "{what} underlay must resolve the PLAN, not use self.doc",
            );
            for line in body.lines() {
                let l = line.trim();
                if l.starts_with("//") {
                    continue;
                }
                assert!(
                    !l.contains("&self.doc.dobjects") && !l.contains("plan_lines(&self.doc"),
                    "{what} underlay still reads self.doc: {l}",
                );
                // …AND THE SCALE MUST COME FROM THE PLAN TOO. The first version of this test
                // checked only which DOCUMENT was iterated, and passed over `self.outlines_m`,
                // which scales by `doc_k()` = `self.doc.units` — the SKETCH's. A millimetre plan
                // drew at 1000× with the test green. A guard that lists the two spellings someone
                // already found is whack-a-mole; this names the hazard itself.
                assert!(
                    !l.contains("self.outlines_m(") && !l.contains("self.doc_k()"),
                    "{what} underlay takes its SCALE from self.doc, which is the sketch: {l}",
                );
            }
        }
    }

    /// The helper itself: with a session open it must hand back the SAVED plan, not the sketch.
    /// This is the property both call sites depend on.
    #[test]
    fn plan_doc_returns_the_saved_drawing_while_sketching() {
        let mut plan = cad_kernel::Document::default();
        plan.push(cad_kernel::DObject::new(cad_kernel::Geom::Point(cad_kernel::Point { location: Vec2::new(1.0, 2.0), style: 0, size: 0.0 })));
        let mut sketch = cad_kernel::Document::default();
        for _ in 0..3 {
            sketch.push(cad_kernel::DObject::new(cad_kernel::Geom::Point(cad_kernel::Point { location: Vec2::new(9.0, 9.0), style: 0, size: 0.0 })));
        }
        let session = crate::factory::SketchSession {
            plane: 1,
            saved_doc: plan,
            saved_undo: Vec::new(),
            saved_redo: Vec::new(),
            saved_constraints: Vec::new(),
            saved_pending: None,
        };
        // `self.doc` is the sketch during a session — that is the swap.
        let got = CadApp::plan_doc_of(Some(&session), &sketch);
        assert_eq!(got.dobjects.len(), 1, "the PLAN has one object; the sketch has three");

        // …and with no session it is simply the document.
        let got = CadApp::plan_doc_of(None, &sketch);
        assert_eq!(got.dobjects.len(), 3);
    }
}

/// LAYERS BELONG TO THE DRAWING, AND A PLANE SHOWS ONLY ITSELF.
///
/// Reported together: "i need a toggle to turn it off so i can only see the what ever is on the
/// plane i am drawing" and "i drew some of these arrays in different colors but they showed up in
/// the same color … are the layers tool no integrated into this?"
///
/// The colours were the swap again: `Sketch::new` builds a `Document::default()`, whose LayerTable
/// is empty, so nothing drawn on a face could be on one of the project's layers.
#[cfg(test)]
mod a_plane_shares_the_drawings_layers {
    use super::*;

    fn app_with_layers() -> CadApp {
        let mut app = CadApp::default();
        let mut l = cad_kernel::Layer::layer_zero();
        l.name = "Lighting".into();
        app.doc.layers.add(l);
        let mut l = cad_kernel::Layer::layer_zero();
        l.name = "Power".into();
        app.doc.layers.add(l);
        app
    }

    /// THE BUG: a sketch used to start with the default table, so the project's layers were not
    /// there to draw on and everything came out one colour.
    #[test]
    fn a_sketch_gets_the_projects_layers() {
        let mut app = app_with_layers();
        let before = app.doc.layers.layers.len();
        assert!(before >= 3, "precondition: base plus two named layers");

        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        assert_eq!(
            app.doc.layers.layers.len(),
            before,
            "the sketch must have the drawing's layers, not an empty table",
        );
        assert!(app.doc.layers.layers.iter().any(|l| l.name == "Lighting"));
        assert!(app.doc.layers.layers.iter().any(|l| l.name == "Power"));
    }

    /// …and a layer made while drawing on a face is not lost when the sketch closes.
    #[test]
    fn a_layer_created_in_a_sketch_survives_the_exit() {
        let mut app = app_with_layers();
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        let mut l = cad_kernel::Layer::layer_zero();
        l.name = "Sprinklers".into();
        app.doc.layers.add(l);
        app.factory_exit_sketch();
        assert!(
            app.doc.layers.layers.iter().any(|l| l.name == "Sprinklers"),
            "a layer is a property of the drawing, so it must come back out with it",
        );
    }

    /// The ACTIVE layer travels too — otherwise the first thing drawn on a face silently lands on
    /// the base layer however carefully the layer was chosen beforehand.
    #[test]
    fn the_active_layer_travels_into_the_sketch() {
        let mut app = app_with_layers();
        app.doc.layers.active = 2;
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        assert_eq!(app.doc.layers.active, 2, "the chosen layer must still be the one in force");
    }

    /// The other-planes projection is OFF by default and gated on the toggle.
    #[test]
    fn other_planes_are_hidden_by_default() {
        let f = crate::factory::FactoryState::default();
        assert!(!f.show_other_planes, "a plane shows its own work unless asked otherwise");

        let src = include_str!("app.rs");
        let a = src.find("fn draw_factory_sketches_2d").expect("the projector");
        let b = src[a..].find("\n    fn ").map(|e| a + e).unwrap_or(src.len());
        let body = &src[a..b];
        assert!(
            body.contains("!self.factory.show_other_planes"),
            "the projection must be gated on the toggle",
        );
        // …and the GROUND PLAN rule must survive: it is a separate case, not covered by the toggle.
        assert!(body.contains("ground_only"), "the plan's own rule must still apply");
    }
}

/// 3D WORK DONE INSIDE A SKETCH IS STILL UNDOABLE, AND PLAN TOOLS DECLINE TO RUN THERE.
///
/// Both from the `self.doc`-swap audit. `factory_exit_sketch` used to discard the whole session
/// undo stack, so `draw on a face → Extrude` destroyed its own undo step; and the ▼ Building rows
/// were clickable while a sketch was open, building ground geometry out of a wall sketch's (u, v).
#[cfg(test)]
mod a_sketch_does_not_eat_history_or_build_the_wrong_thing {
    use super::*;

    fn app_with_a_box() -> CadApp {
        let mut app = CadApp::default();
        app.factory.open = true;
        app.factory.add_box();
        app.factory.recompute();
        app
    }

    /// THE FLAGSHIP FLOW. A 3D snapshot taken inside a sketch must survive the sketch closing.
    #[test]
    fn a_model_change_made_in_a_sketch_survives_the_exit() {
        let mut app = app_with_a_box();
        app.undo_stack.clear();
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());

        app.snapshot_factory(); // what Extrude / Cut / a gizmo move each do
        app.factory.add_box(); // …then change the model
        app.factory_exit_sketch();

        assert!(
            app.undo_stack.iter().any(|u| matches!(u, UndoStep::Factory(_))),
            "the 3D step was thrown away with the sketch's own history — Ctrl+Z would walk past it",
        );
    }

    /// The sketch's OWN 2D history does not come out. It belongs to the sketch, which has closed.
    #[test]
    fn the_sketches_2d_history_stays_behind() {
        let mut app = app_with_a_box();
        app.undo_stack.clear();
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        app.snapshot_doc(); // a 2D edit inside the sketch
        app.factory_exit_sketch();
        assert!(
            !app.undo_stack.iter().any(|u| matches!(u, UndoStep::Doc(_))),
            "a sketch's 2D history must end with the sketch",
        );
    }

    /// THE COROLLARY, and the trap: a snapshot taken mid-session must record the face's drawing,
    /// not the empty hole `mem::take` left in the model. Otherwise undoing a 3D step after the
    /// sketch closed would erase everything drawn on that face.
    #[test]
    fn a_snapshot_taken_in_a_sketch_keeps_that_faces_drawing() {
        let mut app = app_with_a_box();
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        let idx = app.factory.session.as_ref().expect("a session").plane;
        // Draw something on the face.
        app.doc.push(cad_kernel::DObject::new(cad_kernel::Geom::Point(cad_kernel::Point {
            location: Vec2::new(1.0, 1.0),
            style: 0,
            size: 0.0,
        })));
        app.snapshot_factory();

        let snap = app
            .undo_stack
            .iter()
            .rev()
            .find_map(|u| match u {
                UndoStep::Factory(f) => Some(f),
                _ => None,
            })
            .expect("a factory snapshot");
        assert_eq!(
            snap.model.sketch_by_id(idx).expect("the plane is in the snapshot").doc.dobjects.len(),
            1,
            "the snapshot recorded the open plane as EMPTY — undoing to it would wipe the face",
        );
    }

    /// …AND SO DOES THE COUNTERPART, which is the one that actually runs.
    ///
    /// `snapshot_factory` patched this and asserted in its own comment that every snapshot was
    /// therefore self-consistent "whoever takes one". That was false. `counterpart_of` builds the
    /// opposite-stack entry on EVERY undo and EVERY redo — the most-travelled path there is — and
    /// cloned the model bare, recording the open plane as empty. Redo after an undo inside a
    /// sketch would then restore that hole and wipe the face.
    ///
    /// The patch now lives in one function both call, so they cannot drift again.
    #[test]
    fn the_undo_counterpart_also_keeps_the_open_faces_drawing() {
        let mut app = app_with_a_box();
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        let idx = app.factory.session.as_ref().expect("a session").plane;
        app.doc.push(cad_kernel::DObject::new(cad_kernel::Geom::Point(cad_kernel::Point {
            location: Vec2::new(1.0, 1.0),
            style: 0,
            size: 0.0,
        })));

        // Exactly what `do_undo` / `do_redo` build for the opposite stack.
        let counterpart = app.counterpart_of(&UndoStep::Factory(FactorySnap {
            model: app.factory.model.clone(),
            walls: app.factory.walls.clone(),
            storeys: app.factory.storeys.clone(),
            active_storey: app.factory.active_storey,
            ceilings: app.factory.ceilings.clone(),
            furniture: app.factory.furniture.clone(),
            feature_color: app.factory.feature_color.clone(),
            surface_color: app.factory.surface_color.clone(),
            feature_texture: app.factory.feature_texture.clone(),
            surface_texture: app.factory.surface_texture.clone(),
            feature_group: app.factory.feature_group.clone(),
            rooms: app.factory.rooms.clone(),
            next_room_id: app.factory.next_room_id,
            texture_xforms: Vec::new(),
        }));

        let UndoStep::Factory(snap) = counterpart else { panic!("a factory counterpart") };
        assert_eq!(
            snap.model.sketch_by_id(idx).expect("the plane is in the counterpart").doc.dobjects.len(),
            1,
            "the counterpart recorded the open plane as EMPTY — a redo would wipe the face",
        );
    }

    /// PLAN TOOLS DECLINE while a sketch is open, rather than building from its (u, v).
    #[test]
    fn the_building_tools_refuse_inside_a_sketch() {
        let mut app = app_with_a_box();
        let before = app.factory.model.features.len();
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        // A closed outline on the FACE, which is exactly the gesture that used to build a slab.
        app.doc.push(cad_kernel::DObject::new(cad_kernel::Geom::Polyline(cad_kernel::Polyline {
            vertices: [(0.0, 0.0), (2.0, 0.0), (2.0, 2.0), (0.0, 2.0)]
                .into_iter()
                .map(|(x, y)| cad_kernel::PolyVertex { pos: Vec2::new(x, y), bulge: 0.0 })
                .collect(),
            closed: true,
            widths: Vec::new(),
        })));
        app.selection = vec![0];

        app.do_make_slab(true);
        app.do_make_building();
        app.do_make_room();
        app.do_make_3d_wall();

        assert_eq!(
            app.factory.model.features.len(),
            before,
            "a plan tool built geometry from a face sketch's local coordinates",
        );
        assert!(
            app.factory.status.contains("face sketch is open"),
            "and it must SAY why rather than silently doing nothing: {}",
            app.factory.status,
        );
    }

    /// …and they still work normally with no sketch open.
    #[test]
    fn the_building_tools_still_work_on_the_plan() {
        let mut app = app_with_a_box();
        assert!(!app.refuse_plan_action_in_sketch("Make floor"), "no session, no refusal");
    }
}

/// The rest of the sketch-swap audit: everything else that read the installed canvas while
/// meaning the drawing. Each of these was written against the UNFIXED code first and seen to
/// fail — a guard that has never failed is not known to guard anything.
#[cfg(test)]
mod a_sketch_does_not_reach_into_the_drawing {
    use super::*;
    use crate::param_editor::CRef;

    fn app_with_a_box() -> CadApp {
        let mut app = CadApp::default();
        app.factory.open = true;
        app.factory.add_box();
        app.factory.recompute();
        app
    }

    fn line(ax: f64, ay: f64, bx: f64, by: f64) -> cad_kernel::DObject {
        cad_kernel::DObject::new(cad_kernel::Geom::Line(cad_kernel::Line {
            a: Vec2::new(ax, ay),
            b: Vec2::new(bx, by),
        }))
    }

    fn square(half: f64) -> cad_kernel::DObject {
        cad_kernel::DObject::new(cad_kernel::Geom::Polyline(cad_kernel::Polyline {
            vertices: [(-half, -half), (half, -half), (half, half), (-half, half)]
                .into_iter()
                .map(|(x, y)| cad_kernel::PolyVertex { pos: Vec2::new(x, y), bulge: 0.0 })
                .collect(),
            closed: true,
            widths: Vec::new(),
        }))
    }

    /// A drawing with two lines and one constraint on them, parametric mode on.
    fn app_with_a_constraint() -> CadApp {
        let mut app = app_with_a_box();
        app.doc.push(line(0.0, 0.0, 1.0, 0.0));
        app.doc.push(line(0.0, 1.0, 1.0, 1.0));
        let (h0, h1) = (app.doc.dobjects[0].handle, app.doc.dobjects[1].handle);
        app.parametric.active = true;
        app.parametric.constraints.push(CRef::Parallel(h0, h1));
        app
    }

    /// What the parametric panel does on EVERY frame it is open.
    fn one_panel_frame(app: &mut CadApp) {
        crate::param_editor::prune_constraints(&app.doc, &mut app.parametric.constraints);
    }

    // ── #2 — the constraint wipe ────────────────────────────────────────────────────────────

    /// Handles come from a process-global counter, so a sketch document shares NONE with the
    /// plan: `prune_constraints` matched nothing and emptied the list on the sketch's first
    /// frame. Nothing recovers it — no `UndoStep` carries constraints and nothing writes them
    /// to disk.
    #[test]
    fn the_drawings_constraints_survive_a_sketch() {
        let mut app = app_with_a_constraint();
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        one_panel_frame(&mut app);
        one_panel_frame(&mut app); // and it is not a first-frame-only effect
        app.factory_exit_sketch();

        assert_eq!(
            app.parametric.constraints.len(),
            1,
            "the drawing's constraints were deleted by a sketch it had nothing to do with",
        );
    }

    /// The mechanism, stated as its own test: while the sketch is open the drawing's constraints
    /// are PARKED, not merely spared the prune. Left installed they would also be solved against,
    /// and drawn over, geometry that is not theirs.
    #[test]
    fn the_drawings_constraints_are_not_live_inside_the_sketch() {
        let mut app = app_with_a_constraint();
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        assert!(
            app.parametric.constraints.is_empty(),
            "a sketch is its own constraint space — its handles are its own",
        );
        assert!(app.parametric.pending.is_none(), "a half-picked pair must not span two documents");
    }

    /// …and a constraint made INSIDE the sketch does not follow the drawing back out, where its
    /// handles name nothing.
    #[test]
    fn a_sketch_constraint_does_not_leak_into_the_drawing() {
        let mut app = app_with_a_constraint();
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        app.doc.push(line(0.0, 0.0, 2.0, 0.0));
        let h = app.doc.dobjects[0].handle;
        app.parametric.constraints.push(CRef::Horizontal(h));
        app.factory_exit_sketch();

        assert_eq!(app.parametric.constraints.len(), 1, "exactly the drawing's own constraint");
        let present: std::collections::HashSet<_> =
            app.doc.dobjects.iter().map(|d| d.handle).collect();
        assert!(
            app.parametric.constraints[0].handles().iter().all(|h| present.contains(h)),
            "every restored constraint must name geometry that is actually in the drawing",
        );
    }

    /// The prune still does its real job — dropping constraints whose geometry was deleted.
    #[test]
    fn the_prune_still_drops_deleted_geometry() {
        let mut app = app_with_a_constraint();
        app.doc.dobjects.remove(1);
        one_panel_frame(&mut app);
        assert!(app.parametric.constraints.is_empty(), "the prune must still prune");
    }

    // ── #5 — picking bare ground from the 3D view ───────────────────────────────────────────

    fn view(app: &CadApp, rect: egui::Rect) -> [f32; 16] {
        let f = &app.factory;
        crate::light3d::mvp(
            f.cam_yaw, f.cam_pitch, f.cam_dist, f.cam_target,
            rect.width() / rect.height(), f.ortho,
        )
    }

    /// PROVES THE MACHINERY WORKS, so the refusal test below cannot pass by accident — the
    /// mistake that has bitten this codebase three times.
    #[test]
    fn the_ground_pick_finds_plan_geometry_with_no_sketch_open() {
        let mut app = app_with_a_box();
        app.doc.push(square(0.5)); // smallest containing shape wins the pick
        let want = app.doc.dobjects.len() - 1;
        let rect = egui::Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(800.0, 600.0));
        let mvp = view(&app, rect);
        assert_eq!(
            app.factory_pick_ground_dobject(rect.center(), rect, &mvp),
            Some(want),
            "the pick must actually hit a plan shape under the cursor",
        );
    }

    /// It ray-cast to world z = 0 and then point-in-polygoned against the SKETCH, reading a
    /// plane's (u, v) as world (x, y). A click on bare floor cleared the 3D selection and put
    /// grips on a shape the user never clicked.
    #[test]
    fn the_ground_pick_ignores_a_face_sketch() {
        let mut app = app_with_a_box();
        app.doc.push(square(5.0));
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        app.doc.push(square(5.0)); // the same shape, now drawn ON THE FACE

        let rect = egui::Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(800.0, 600.0));
        let mvp = view(&app, rect);
        assert_eq!(
            app.factory_pick_ground_dobject(rect.center(), rect, &mvp),
            None,
            "a sketch's local coordinates were picked as if they were the ground plan",
        );
    }

    // ── #7 — the SIMLUX layer on the 2D canvas ──────────────────────────────────────────────

    /// `paint_lux_overlay` already refused during a sketch; the fixtures and the pointer that
    /// places them did not. So the heatmap vanished while the fittings it was computed from kept
    /// drawing at world metres on a wall's (u, v) — and a click wrote that wall coordinate
    /// straight into a luminaire's world position.
    #[test]
    fn the_simlux_2d_layer_is_off_during_a_sketch() {
        let mut app = app_with_a_box();
        app.light.window_open = true;
        assert!(app.simlux_2d_layer_live(), "SIMLUX is on screen and the canvas is the plan");

        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        assert!(
            !app.simlux_2d_layer_live(),
            "fixtures are world metres; a face sketch's canvas is that plane's (u, v)",
        );

        app.factory_exit_sketch();
        assert!(app.simlux_2d_layer_live(), "and it comes back when the sketch closes");
    }

    /// The other half of the predicate is unchanged: with SIMLUX off screen, nothing is live.
    #[test]
    fn the_simlux_2d_layer_is_off_when_simlux_is_closed() {
        let app = app_with_a_box();
        assert!(!app.simlux_2d_layer_live());
    }

    /// Moving objects onto the SIMLUX layer REFUSES in a sketch rather than reaching for the
    /// plan: it needs `&mut` on the document and `self.selection`, which indexes whichever
    /// document is installed, so there is no correct answer.
    #[test]
    fn the_simlux_layer_move_refuses_inside_a_sketch() {
        let mut app = app_with_a_box();
        app.doc.push(square(5.0));
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        app.doc.push(square(5.0));
        app.selection = vec![0];
        let layers_before = app.factory.session.as_ref().unwrap().saved_doc.layers.layers.len();

        app.shift_selection_to_simlux_layer();

        assert_eq!(
            app.factory.session.as_ref().unwrap().saved_doc.layers.layers.len(),
            layers_before,
            "it created a SIMLUX layer in the drawing on behalf of a click inside a sketch",
        );
        assert!(
            app.factory.status.contains("finish the sketch"),
            "and it must say why: {}",
            app.factory.status,
        );
    }

    // ── #8 — the `scene` diagnostic ─────────────────────────────────────────────────────────

    /// `scene` exists to give measured truth instead of a guess, and mm-vs-m is what it is most
    /// often pointed at. With a face open it reported the SKETCH's 1.0 m/unit as the drawing's
    /// plan↔3D scale — misleading exactly when it was being trusted.
    #[test]
    fn the_scene_report_states_the_drawings_unit_not_the_sketchs() {
        let mut app = app_with_a_box();
        app.doc.units.metres_per_unit = 0.001; // a millimetre drawing
        app.doc.units.source = cad_kernel::UnitSource::Declared;
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());

        let ev = app.factory_scene_capture("test");
        let crate::dbg_recorder::DbgEvent::FactoryScene { sections, .. } = ev else {
            panic!("factory_scene_capture must return a FactoryScene event");
        };
        let units_line = sections
            .iter()
            .flat_map(|(_, lines)| lines.iter())
            .find(|l| l.starts_with("doc units:"))
            .expect("the report states the document's units")
            .clone();

        assert!(
            units_line.contains("0.001000"),
            "the drawing is millimetres and the report must say so: {units_line}",
        );
        assert!(
            units_line.contains("sketch open"),
            "and it must say the canvas is a plane, not silently report the plan: {units_line}",
        );
    }

    /// With no sketch open it is unchanged.
    #[test]
    fn the_scene_report_is_unchanged_with_no_sketch() {
        let mut app = app_with_a_box();
        app.doc.units.metres_per_unit = 0.001;
        let ev = app.factory_scene_capture("test");
        let crate::dbg_recorder::DbgEvent::FactoryScene { sections, .. } = ev else {
            panic!("FactoryScene");
        };
        let units_line = sections
            .iter()
            .flat_map(|(_, lines)| lines.iter())
            .find(|l| l.starts_with("doc units:"))
            .expect("units line")
            .clone();
        assert!(units_line.contains("0.001000"), "{units_line}");
        assert!(!units_line.contains("sketch open"), "{units_line}");
    }
}

/// LOCKING A LAYER LOCKS IT.
///
/// `LayerTable::selectable` — "not locked, and it renders" — was written, unit-tested in
/// `cad_kernel`, and then called from nowhere in the app. Every route into the selection basket
/// ignored it, so the padlock in the layer panel changed a bool and nothing else: locked geometry
/// picked, window-selected, Select-All'd and edited exactly as before.
///
/// The rule these pin down is AutoCAD's, which is narrower than "locked means untouchable":
/// a locked object still DRAWS and can still be SNAPPED to. It just cannot be selected, and
/// therefore cannot be edited by anything that works through the selection.
#[cfg(test)]
mod a_locked_layer_is_locked {
    use super::*;

    /// A drawing with one line on a normal layer and one on a locked layer, far apart.
    /// Returns `(app, free_index, locked_index)`.
    fn two_layers() -> (CadApp, usize, usize) {
        let mut app = CadApp::default();
        app.doc.dobjects.clear();
        let free = app.doc.push(DObject::new(Geom::Line(Line {
            a: Vec2::new(0.0, 0.0), b: Vec2::new(10.0, 0.0),
        })));
        let locked_layer = app.doc.layers.add(Layer {
            name: "LOCKED".into(), locked: true, ..Layer::layer_zero()
        });
        app.doc.layers.active = locked_layer;
        let locked = app.doc.push(DObject::new(Geom::Line(Line {
            a: Vec2::new(0.0, 50.0), b: Vec2::new(10.0, 50.0),
        })));
        assert_eq!(app.doc.dobjects[locked].style.layer, locked_layer, "the fixture is wired up");
        (app, free, locked)
    }

    /// A CLICK PASSES STRAIGHT THROUGH a locked object. `nearest_entity_under` is the one
    /// function all eighteen click sites go through, so this is every pick in the app.
    #[test]
    fn a_click_does_not_pick_a_locked_object() {
        let (app, free, _locked) = two_layers();
        // Dead on the locked line.
        assert_eq!(
            app.nearest_entity_under(Vec2::new(5.0, 50.0), 1.0), None,
            "clicking a locked object picked it",
        );
        // …and the unlocked one is still perfectly pickable, so this is not a blanket refusal.
        assert_eq!(
            app.nearest_entity_under(Vec2::new(5.0, 0.0), 1.0), Some(free),
            "the fix stopped picking anything at all",
        );
    }

    /// A WINDOW DRAG over both takes only the one it is allowed to take.
    #[test]
    fn a_window_drag_leaves_a_locked_object_behind() {
        let (mut app, free, locked) = two_layers();
        // A crossing window (R→L) spanning both lines.
        app.add_window_selection(Vec2::new(20.0, 60.0), Vec2::new(-5.0, -5.0), false, false, true);
        assert!(app.selection.contains(&free), "the unlocked line should have been caught");
        assert!(!app.selection.contains(&locked), "a window drag selected a locked object");
    }

    /// SELECT ALL means all the objects you are allowed to have.
    #[test]
    fn select_all_leaves_a_locked_object_behind() {
        let (mut app, free, locked) = two_layers();
        app.add_all_to_selection();
        assert!(app.selection.contains(&free), "Select All missed the unlocked line");
        assert!(!app.selection.contains(&locked), "Select All selected a locked object");
    }

    /// LOCKING A LAYER TAKES ITS OBJECTS OUT OF THE BASKET. Guarding only the entry points
    /// leaves the obvious hole open: select it, then lock the layer, then move — the edit runs
    /// off a selection made when the lock was not there.
    #[test]
    fn locking_a_layer_drops_its_objects_from_the_current_selection() {
        let (mut app, free, locked) = two_layers();
        // Select both while nothing is locked yet.
        let layer = app.doc.dobjects[locked].style.layer;
        if let Some(l) = app.doc.layers.get_mut(layer) { l.locked = false; }
        app.add_all_to_selection();
        assert!(app.selection.contains(&locked), "both are selected before the lock");

        app.set_layer_locked(layer, true);

        assert!(app.selection.contains(&free), "the unlocked object was dropped too");
        assert!(
            !app.selection.contains(&locked),
            "an object stayed selected after its layer was locked — the next edit still moves it",
        );
    }

    /// A LOCKED OBJECT IS NOT A HIDDEN ONE. The cheapest way to pass every test above is to stop
    /// drawing locked geometry, which would be a far worse product than the bug.
    #[test]
    fn a_locked_object_still_draws() {
        let (app, _free, locked) = two_layers();
        let layer = app.doc.dobjects[locked].style.layer;
        assert!(app.doc.layers.renders(layer), "a locked layer must still render");
        assert!(app.doc.dobjects[locked].style.visible, "and its object is still visible");
    }

    /// …AND IT CAN STILL BE SNAPPED TO, which is why the lock belongs at selection rather than
    /// in the geometry. Tracing a new wall along a locked grid line is the reason to lock it.
    #[test]
    fn a_locked_object_can_still_be_snapped_to() {
        let (app, _free, _locked) = two_layers();
        let mut snaps = SnapSet::default();
        snaps.end = true;
        let hit = find_snap(
            Vec2::new(0.1, 50.1), 1.0, snaps, None, None, &app.doc.dobjects, None,
        );
        let hit = hit.expect("the locked line's endpoint must still snap");
        assert_eq!(hit.point, Vec2::new(0.0, 50.0), "snapped to the wrong point");
    }
}

/// WHAT YOU SEE IS NOT WHAT FEEDS EXTRUDE — and both halves of that matter.
///
/// The 3D viewport flattened 2D geometry through `cad_solid::geom_outlines_scaled`, which knows
/// Line, Circle, Arc, Ellipse, EllipseArc, Polyline and Point and returns nothing for anything
/// else. A spline, a wall and an imported block therefore existed in the drawing and were simply
/// absent from the 3D view — an imported plan made of blocks showed as very nearly nothing.
///
/// The fix is a SECOND flattener rather than a wider one. `geom_outlines_scaled` also answers
/// "what may Extrude and Make-3D-wall consume?", and a block's contents are full of closed loops:
/// widening it would make Make-building start extruding the furniture. The guard test below is
/// the one that would catch that, and it is the reason this is two functions.
#[cfg(test)]
mod the_viewport_sees_what_the_drawing_has {
    use super::*;

    fn app_with(geoms: Vec<Geom>) -> CadApp {
        let mut app = CadApp::default();
        app.doc.dobjects.clear();
        for g in geoms {
            app.doc.push(DObject::new(g));
        }
        app
    }

    /// An unrotated, unscaled instance of `id` at `insert`.
    fn block_ref(id: u32, insert: Vec2) -> cad_kernel::BlockRef {
        cad_kernel::BlockRef {
            block: id, insert, scale: 1.0, scale_y: 1.0, rotation: 0.0, mirror_x: false,
            param_values: [0.0; cad_kernel::MAX_BLOCK_PARAMS],
        }
    }

    /// A closed 2 x 2 square as a block definition, plus one reference to it at `at`.
    fn block_with_a_square(app: &mut CadApp, at: Vec2) -> usize {
        let mut blk = cad_kernel::Block { name: "FURNITURE".into(), base: Vec2::ZERO, dobjects: Vec::new(), smart: false, params: Vec::new(), cut_edges: Vec::new() };
        blk.dobjects.push(DObject::new(Geom::Polyline(Polyline {
            vertices: vec![
                PolyVertex { pos: Vec2::new(0.0, 0.0), bulge: 0.0 },
                PolyVertex { pos: Vec2::new(2.0, 0.0), bulge: 0.0 },
                PolyVertex { pos: Vec2::new(2.0, 2.0), bulge: 0.0 },
                PolyVertex { pos: Vec2::new(0.0, 2.0), bulge: 0.0 },
            ],
            closed: true,
            widths: Vec::new(),
        })));
        let id = app.doc.blocks.add(blk);
        app.doc.push(DObject::new(Geom::BlockRef(block_ref(id, at))))
    }

    /// A SPLINE IS DRAWN IN 3D. Traced curves are how a real plan describes anything organic,
    /// and the viewport showed nothing at all where one was.
    #[test]
    fn a_spline_appears_in_the_3d_view() {
        let app = app_with(vec![Geom::Spline(Spline::new_bspline(
            3,
            vec![
                Vec2::new(0.0, 0.0), Vec2::new(1.0, 4.0),
                Vec2::new(5.0, -2.0), Vec2::new(8.0, 1.0),
            ],
        ))]);
        assert!(
            !app.factory.plan_lines(&app.doc, 0.0).is_empty(),
            "a spline in the drawing produced no 3D geometry",
        );
    }

    /// A WALL IS DRAWN AS A WALL — both faces, not a bare centreline.
    #[test]
    fn a_wall_appears_in_the_3d_view_with_both_faces() {
        let app = app_with(vec![Geom::Wall(Wall {
            start: Vec2::new(0.0, 0.0),
            end: Vec2::new(10.0, 0.0),
            thickness: 0.2,
            style: 0,
            bulge: 0.0,
        })]);
        let lines = app.factory.plan_lines(&app.doc, 0.0);
        assert!(!lines.is_empty(), "a wall in the drawing produced no 3D geometry");
        // Two faces, either side of y = 0 — a centreline-only fallback would put every
        // vertex on it.
        let (lo, hi) = lines
            .iter()
            .fold((f32::MAX, f32::MIN), |(lo, hi), v| (lo.min(v.y), hi.max(v.y)));
        assert!(hi - lo > 1e-4, "the wall was drawn as a single centreline, not as two faces");
    }

    /// AN IMPORTED BLOCK IS DRAWN. A DXF floor plan arrives as block references; without this
    /// the 3D view of an imported drawing is very nearly empty.
    #[test]
    fn an_imported_block_appears_in_the_3d_view() {
        let mut app = app_with(vec![]);
        block_with_a_square(&mut app, Vec2::new(20.0, 5.0));
        let lines = app.factory.plan_lines(&app.doc, 0.0);
        assert!(!lines.is_empty(), "a block reference produced no 3D geometry");
        // Drawn WHERE IT WAS INSERTED, not at the block's own origin.
        let k = app.doc.units.metres_per_unit as f32;
        assert!(
            lines.iter().any(|v| v.x > 19.0 * k),
            "the block was drawn at the origin instead of at its insertion point",
        );
    }

    /// THE GUARD. Everything above is display; none of it may reach the construction path.
    ///
    /// A block's contents are closed loops, and Extrude / Make-building take every closed loop
    /// they are handed. If the two flatteners were ever merged, dropping a furniture block on a
    /// plan and pressing Make-building would extrude the furniture into the building.
    #[test]
    fn a_block_is_visible_but_not_buildable() {
        let mut app = app_with(vec![]);
        block_with_a_square(&mut app, Vec2::new(20.0, 5.0));

        assert!(
            !app.factory.plan_lines(&app.doc, 0.0).is_empty(),
            "the fixture must be VISIBLE, or the assertion below proves nothing",
        );
        assert!(
            CadApp::closed_loops_of(&app.doc).is_empty(),
            "a block reference reached the construction path — Make-building would extrude it",
        );
        let br = &app.doc.dobjects[0].geom;
        assert!(!is_promotable_to_wall(br), "a block reference must not promote to a wall");
    }

    /// ...and the buildable types are still buildable, so the guard above is not simply "nothing
    /// can be built any more".
    #[test]
    fn a_drawn_square_is_still_buildable() {
        let app = app_with(vec![Geom::Polyline(Polyline {
            vertices: vec![
                PolyVertex { pos: Vec2::new(0.0, 0.0), bulge: 0.0 },
                PolyVertex { pos: Vec2::new(4.0, 0.0), bulge: 0.0 },
                PolyVertex { pos: Vec2::new(4.0, 4.0), bulge: 0.0 },
                PolyVertex { pos: Vec2::new(0.0, 4.0), bulge: 0.0 },
            ],
            closed: true,
            widths: Vec::new(),
        })]);
        assert_eq!(
            CadApp::closed_loops_of(&app.doc).len(), 1,
            "an ordinary closed polyline stopped being buildable",
        );
    }

    /// A BLOCK CAN BE INSERTED ONTO A PLANE. The block TABLE lives in the drawing, and a sketch
    /// document was built from `Document::default()` — so on a plane there were no blocks to
    /// insert, and a reference pushed there pointed at a definition that did not exist.
    ///
    /// The same reasoning, and the same fix, as the layer table before it: a block definition is
    /// a property of the DRAWING, not of one plane of it.
    #[test]
    fn a_block_can_be_inserted_onto_a_plane_and_is_drawn_there() {
        let mut app = app_with(vec![]);
        let mut blk = cad_kernel::Block { name: "CHAIR".into(), base: Vec2::ZERO, dobjects: Vec::new(), smart: false, params: Vec::new(), cut_edges: Vec::new() };
        blk.dobjects.push(DObject::new(Geom::Line(Line {
            a: Vec2::new(0.0, 0.0),
            b: Vec2::new(1.0, 1.0),
        })));
        let id = app.doc.blocks.add(blk);
        let blocks_before = app.doc.blocks.len();

        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        assert_eq!(
            app.doc.blocks.len(), blocks_before,
            "the drawing's blocks did not come with us onto the plane — nothing to insert",
        );
        app.add_dobject(
            Geom::BlockRef(block_ref(id, Vec2::new(3.0, 3.0))),
            "test",
        );
        assert!(
            !app.factory.live_sketch_lines(&app.doc).is_empty(),
            "a block inserted on a plane is not drawn in 3D",
        );
    }

    /// ...AND A BLOCK DEFINED ON A PLANE COMES BACK OUT, exactly as a layer created there does.
    /// Otherwise the plane is a place where block work quietly disappears on Finish.
    #[test]
    fn a_block_defined_on_a_plane_returns_to_the_drawing() {
        let mut app = app_with(vec![]);
        let before = app.doc.blocks.len();
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        let mut blk = cad_kernel::Block { name: "MADE-ON-A-PLANE".into(), base: Vec2::ZERO, dobjects: Vec::new(), smart: false, params: Vec::new(), cut_edges: Vec::new() };
        blk.dobjects.push(DObject::new(Geom::Line(Line {
            a: Vec2::ZERO,
            b: Vec2::new(1.0, 0.0),
        })));
        app.doc.blocks.add(blk);
        app.factory_exit_sketch();
        assert_eq!(
            app.doc.blocks.len(), before + 1,
            "a block defined while drawing on a plane was lost when the sketch closed",
        );
    }
}

/// WHAT ONE FRAME OF 3D LINE WORK COSTS, on a real drawing.
///
///   SIMLUX_PLAN="D:\...\1 Mashrabiya.dxf" cargo test -p cad_app --bin simlux \
///       frame_cost_of_real_drawing -- --ignored --nocapture
///
/// The 3D view rebuilds its whole line buffer every frame from FIVE separate builders and then
/// concatenates them. None of it is cached and none of it depends on the camera, so panning a
/// drawing re-flattens every entity in it, sixty times a second.
///
/// The plan's estimate for this was "drawing one object costs 30 ms" and "panning allocates
/// megabytes per frame". M6 is the reason this is measured rather than trusted: the last two
/// estimates in this plan were both wrong, one of them by having been taken against a BSP that
/// was collapsing.
#[test]
#[ignore = "needs SIMLUX_PLAN=<drawing path>"]
fn frame_cost_of_real_drawing() {
    let Ok(path) = std::env::var("SIMLUX_PLAN") else {
        println!("set SIMLUX_PLAN to a .dxf path");
        return;
    };
    let text = std::fs::read_to_string(&path)
        .or_else(|_| std::fs::read(&path).map(|b| String::from_utf8_lossy(&b).into_owned()))
        .expect("read the drawing");
    let t = std::time::Instant::now();
    let doc = cad_io::dxf::read_dxf(&text).expect("parse dxf");
    let parse_ms = t.elapsed().as_secs_f64() * 1000.0;

    let mut app = CadApp::default();
    app.doc = doc;
    println!(
        "\n{}\n  {} dobjects, {} layers, {} blocks — parsed in {:.0} ms",
        path,
        app.doc.dobjects.len(),
        app.doc.layers.len(),
        app.doc.blocks.len(),
        parse_ms,
    );

    // Each builder, timed on its own, then the concatenation the frame actually performs.
    let bench = |label: &str, f: &dyn Fn() -> usize| {
        // A few passes, because one is dominated by first-touch page faults on the allocator.
        const N: u32 = 5;
        let t = std::time::Instant::now();
        let mut verts = 0;
        for _ in 0..N {
            verts = f();
        }
        let ms = t.elapsed().as_secs_f64() * 1000.0 / N as f64;
        println!("  {label:<26} {ms:>9.2} ms   {verts:>9} verts   {:>7} KB", verts * 40 / 1024);
        ms
    };

    println!("\n  per-frame line builders (mean of 5)");
    let mut total = 0.0;
    total += bench("overlay_lines", &|| app.factory.overlay_lines().len());
    total += bench("sketch_lines", &|| app.factory.sketch_lines(&app.doc).len());
    total += bench("picked_face_lines", &|| app.factory.picked_face_lines().len());
    total += bench("live_sketch_lines", &|| app.factory.live_sketch_lines(&app.doc).len());
    total += bench("plan_lines", &|| app.factory.plan_lines(&app.doc, 0.0).len());

    // THE CONCATENATION, which is the part a partial cache would leave behind. This is the exact
    // sequence the frame runs.
    let concat = bench("→ concatenated frame", &|| {
        let mut lines = app.factory.overlay_lines();
        lines.extend(app.factory.sketch_lines(&app.doc));
        lines.extend(app.factory.picked_face_lines());
        lines.extend(app.factory.live_sketch_lines(&app.doc));
        lines.extend(app.factory.plan_lines(&app.doc, 0.0));
        lines.len()
    });

    // WHAT THE DISPLAY FLATTENER ADDED. Block references used to flatten to nothing, which is
    // why an imported plan was very nearly invisible in 3D; expanding them is the fix, and this
    // is its price. Worth knowing separately from the cost of the drawing itself, because it is
    // the difference between "this was always slow" and "we have just made it slow".
    let k = app.doc.units.metres_per_unit;
    let count = |f: &dyn Fn(&Geom) -> Vec<Vec<glam::Vec2>>| -> usize {
        app.doc.dobjects.iter().map(|d| f(&d.geom).iter().map(|p| p.len()).sum::<usize>()).sum()
    };
    let buildable = count(&|g| cad_solid::geom_outlines_scaled(g, k));
    let displayed = count(&|g| cad_solid::geom_display_outlines_scaled(g, &app.doc, k));
    println!(
        "\n  flattened points: {buildable} buildable-only vs {displayed} with blocks/splines/walls \
         expanded ({}x)",
        displayed / buildable.max(1),
    );

    // THE CACHED FRAME — what the app actually runs now. The first call builds; the rest are the
    // steady state, which is what panning and orbiting a still drawing cost.
    let cached = {
        const N: u32 = 20;
        app.refresh_cached_lines();
        let t = std::time::Instant::now();
        let mut n = 0;
        for _ in 0..N {
            app.refresh_cached_lines(); // settled → a signature compare, not a rebuild
            let mut lines = app.factory.overlay_lines();
            lines.extend_from_slice(&app.cached_sketch_lines);
            lines.extend(app.factory.picked_face_lines());
            lines.extend(app.factory.live_sketch_lines(&app.doc));
            lines.extend_from_slice(&app.cached_plan_lines);
            n = lines.len();
        }
        let ms = t.elapsed().as_secs_f64() * 1000.0 / N as f64;
        println!("  → cached frame (settled)   {ms:>9.2} ms   {n:>9} verts");
        ms
    };

    println!("\n  builders summed        {total:>9.2} ms");
    println!("  whole frame            {concat:>9.2} ms");
    println!("  cached frame           {cached:>9.2} ms  ({:.0}x)", concat / cached.max(1e-9));
    println!(
        "  of a 16.7 ms budget:   {:>8.1}% uncached  ->  {:.1}% cached",
        100.0 * concat / 16.7,
        100.0 * cached / 16.7,
    );
    // WHAT IS LEFT IS THE CONCATENATION, which is the thing the plan warned about by name. The
    // cached buffers are copied into one Vec every frame because the renderer takes a single line
    // list; removing that means giving the static lines their own persistent GPU buffer and a
    // second draw call, rather than rebuilding the combined one. Named here so the next person
    // measuring this knows the remaining cost is understood rather than mysterious.
    println!(
        "  remaining {cached:.2} ms is the per-frame memcpy of {} KB of cached lines\n",
        (app.cached_plan_lines.len() + app.cached_sketch_lines.len()) * 40 / 1024,
    );
}

/// THE 3D LINE CACHE MUST NEVER SHOW YOU GEOMETRY THAT IS NO LONGER THERE.
///
/// A stale render cache is the worst shape of bug in this file: the picture is wrong, nothing
/// errors, and the user's own drawing is the thing lying to them. So every input to `lines_sig`
/// gets a test that changes it and asserts the cache notices — and the general test at the end
/// asserts the cached buffers equal what the uncached builders would have produced, which is the
/// property all of it exists to preserve.
#[cfg(test)]
mod the_line_cache_cannot_go_stale {
    use super::*;

    fn app_with_a_plan() -> CadApp {
        let mut app = CadApp::default();
        app.doc.dobjects.clear();
        for i in 0..8 {
            let x = i as f64 * 3.0;
            app.doc.push(DObject::new(Geom::Line(Line {
                a: Vec2::new(x, 0.0), b: Vec2::new(x + 2.0, 4.0),
            })));
        }
        app.factory.show_plan = true;
        app.factory.plan_xray = false;
        app
    }

    /// Build the cache, run `change`, and report whether the cache rebuilt.
    fn rebuilds_after(app: &mut CadApp, change: impl FnOnce(&mut CadApp)) -> bool {
        app.refresh_cached_lines();
        assert!(!app.refresh_cached_lines(), "the cache is not settled — it rebuilds every call");
        change(app);
        app.refresh_cached_lines()
    }

    /// THE POINT OF THE WHOLE THING: a settled cache does not rebuild. Without this the rest of
    /// the tests could all pass on a cache that never caches anything.
    #[test]
    fn a_settled_cache_does_not_rebuild() {
        let mut app = app_with_a_plan();
        assert!(app.refresh_cached_lines(), "the first call must build");
        assert!(!app.refresh_cached_lines(), "nothing changed, so nothing should rebuild");
        assert!(!app.refresh_cached_lines(), "…still nothing");
        assert!(!app.cached_plan_lines.is_empty(), "the fixture must produce plan lines");
    }

    /// THE CACHED BUFFERS ARE WHAT THE BUILDERS WOULD HAVE RETURNED. Equality on the actual
    /// vertices, because "it rebuilt at the right times" is worthless if what it rebuilt is wrong.
    #[test]
    fn the_cache_holds_exactly_what_the_builders_produce() {
        let mut app = app_with_a_plan();
        app.refresh_cached_lines();

        let plan = CadApp::plan_doc_of(app.factory.session.as_ref(), &app.doc);
        let z = app.factory.active_base_z();
        let fresh_plan = app.factory.plan_lines(plan, z);
        let fresh_sketch = app.factory.sketch_lines(&app.doc);

        assert_eq!(app.cached_plan_lines.len(), fresh_plan.len(), "plan line count differs");
        assert_eq!(app.cached_sketch_lines.len(), fresh_sketch.len(), "sketch line count differs");

        // COMPARED AS A SET, NOT IN ORDER, and the change is deliberate. The cached plan is sorted
        // into world-space cells for view culling, so a cell is one contiguous run — which
        // reorders the buffer. Order carries no meaning within the plan: every line is the same
        // colour at the same height. (It DOES carry meaning between builders — the picked-face
        // outline has to be emitted after the sketches — and that ordering is still exact.)
        //
        // This assertion used to be positional and kept passing after the bucketing landed,
        // because a fixture small enough to fall in one cell sorts stably. It was asserting a
        // property the code no longer promises, and would have failed later for a reason that had
        // nothing to do with whatever change tripped it.
        let key = |v: &crate::light3d::V3| (v.x.to_bits(), v.y.to_bits(), v.z.to_bits());
        let cached: std::collections::BTreeSet<_> = app.cached_plan_lines.iter().map(key).collect();
        let built: std::collections::BTreeSet<_> = fresh_plan.iter().map(key).collect();
        assert_eq!(cached, built, "the cached plan is not the geometry the builder produces");
    }

    // ---- one per input to `lines_sig` -------------------------------------------------------

    /// Drawing something. This is the one that goes through `touch_view`, i.e. the sixty-odd
    /// ordinary edit sites.
    #[test]
    fn drawing_an_object_invalidates_it() {
        let mut app = app_with_a_plan();
        assert!(rebuilds_after(&mut app, |a| {
            a.add_dobject(Geom::Line(Line { a: Vec2::new(0.0, 9.0), b: Vec2::new(5.0, 9.0) }), "test");
        }), "a new object did not invalidate the cached plan");
    }

    /// Moving one. The count is unchanged, so a cache keyed on `dobjects.len()` alone would
    /// happily serve the old position — which is the classic way this bug appears.
    #[test]
    fn moving_an_object_invalidates_it() {
        let mut app = app_with_a_plan();
        assert!(rebuilds_after(&mut app, |a| {
            a.snapshot_doc();
            a.doc.dobjects[0] = a.doc.dobjects[0].translated(Vec2::new(50.0, 50.0));
            a.touch_view();
        }), "a moved object did not invalidate the cache — the plan would draw where it WAS");
    }

    /// Hiding the plan.
    #[test]
    fn toggling_the_plan_off_invalidates_it() {
        let mut app = app_with_a_plan();
        assert!(rebuilds_after(&mut app, |a| a.factory.show_plan = false),
                "hiding the plan did not invalidate the cache");
        assert!(app.cached_plan_lines.is_empty(), "a hidden plan must cache as nothing");
    }

    /// Switching to x-ray, which moves the plan to a different renderer entirely.
    #[test]
    fn switching_to_xray_invalidates_it() {
        let mut app = app_with_a_plan();
        assert!(rebuilds_after(&mut app, |a| a.factory.plan_xray = true),
                "x-ray did not invalidate the depth-tested copy");
        assert!(app.cached_plan_lines.is_empty(), "in x-ray the depth-tested plan must be empty");
    }

    /// Changing storey, which is the height the plan is drawn AT.
    #[test]
    fn changing_the_active_storey_invalidates_it() {
        let mut app = app_with_a_plan();
        let before = app.factory.active_base_z();
        assert!(rebuilds_after(&mut app, |a| {
            a.factory.storeys.push(crate::factory::Storey { name: "First".into(), height: 3.0 });
            a.factory.active_storey = a.factory.storeys.len() - 1;
        }), "the plan did not move to the new storey's height");
        assert!(
            app.factory.active_base_z() > before + 1e-4,
            "the fixture must actually raise the plan, or this proves nothing",
        );
    }

    /// Redeclaring the drawing's unit. Not one coordinate changes; every line moves.
    #[test]
    fn redeclaring_the_unit_invalidates_it() {
        let mut app = app_with_a_plan();
        assert!(rebuilds_after(&mut app, |a| {
            a.doc.units = cad_kernel::DocUnits::new(
                cad_kernel::DocUnits::MM, cad_kernel::UnitSource::User);
        }), "a unit change did not invalidate the cache — every line is at the wrong scale");
    }

    /// Opening a plane. Its drawing moves from `sketch_lines` to `live_sketch_lines`, so a stale
    /// cache draws it twice: once dimmed where it was, once live.
    #[test]
    fn entering_a_sketch_invalidates_it() {
        let mut app = app_with_a_plan();
        assert!(rebuilds_after(&mut app, |a| {
            a.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        }), "entering a plane did not invalidate the finished-plane lines");
    }

    /// …and closing it moves the drawing back the other way.
    #[test]
    fn leaving_a_sketch_invalidates_it() {
        let mut app = app_with_a_plan();
        app.factory_enter_sketch(crate::factory::FactoryState::ground_frame());
        assert!(rebuilds_after(&mut app, |a| a.factory_exit_sketch()),
                "leaving a plane did not invalidate the cache");
    }

    /// A 3D model edit, which reaches the cache through the factory's own version counter —
    /// `sketch_lines` resolves colour through the layer table and the plan sits on the storey.
    #[test]
    fn a_model_rebuild_invalidates_it() {
        let mut app = app_with_a_plan();
        assert!(rebuilds_after(&mut app, |a| {
            a.factory.add_box();
            a.factory.recompute();
        }), "a 3D model change did not invalidate the cache");
    }

    /// A PLANE'S DRAWING CAN CHANGE WHILE IT IS NOT THE OPEN ONE, and that is the case nothing
    /// else notices. `factory_clear_sketch_on` wipes a finished plane after a sweep consumes it:
    /// no session index changes, no 2D edit happens, and `view_seq` would not move — so the 3D
    /// view would go on drawing a sketch that has been deleted.
    #[test]
    fn clearing_a_finished_plane_invalidates_it() {
        let mut app = app_with_a_plan();
        // A plane with something on it, closed again so it is drawn by `sketch_lines`.
        let frame = crate::factory::FactoryState::ground_frame();
        app.factory_enter_sketch(frame);
        app.add_dobject(Geom::Circle(Circle { center: Vec2::new(1.0, 1.0), radius: 2.0 }), "test");
        app.factory_exit_sketch();
        app.refresh_cached_lines();
        assert!(
            !app.cached_sketch_lines.is_empty(),
            "the fixture must leave a drawing on a finished plane, or this proves nothing",
        );

        assert!(rebuilds_after(&mut app, |a| a.factory_clear_sketch_on(frame)),
                "clearing a finished plane did not invalidate the cached sketch lines");
        assert!(
            app.cached_sketch_lines.is_empty(),
            "the cleared plane is still being drawn — the cache is showing deleted geometry",
        );
    }
}

/// THE UNDO HISTORY IS BOUNDED BY MEMORY, NOT BY A COUNT OF STEPS.
///
/// A step is a whole document. Measured before this existed: 15.7 MB per step at 100k dobjects —
/// a gigabyte of history — and 240.2 MB at 1.5M, i.e. **15.4 GB** at the old 64-step cap. A count
/// is simply the wrong unit for something whose steps vary by four orders of magnitude.
#[cfg(test)]
mod the_undo_history_is_bounded_by_memory {
    use super::*;

    /// A document with `n` polylines of `pts` points each — the cheap way to make a snapshot big.
    fn doc_of(n: usize, pts: usize) -> Document {
        let mut d = Document::default();
        d.dobjects.clear();
        for i in 0..n {
            let vertices: Vec<cad_kernel::PolyVertex> = (0..pts)
                .map(|k| cad_kernel::PolyVertex {
                    pos: Vec2::new(i as f64 + k as f64, k as f64),
                    bulge: 0.0,
                })
                .collect();
            d.push(DObject::new(Geom::Polyline(cad_kernel::Polyline {
                vertices, closed: false, widths: Vec::new(),
            })));
        }
        d
    }

    fn stack_bytes(app: &CadApp) -> usize {
        app.undo_stack.iter().map(|s| s.approx_bytes()).sum()
    }

    /// A SMALL DOCUMENT STILL GETS THE FULL COUNT. The budget must not quietly shorten history
    /// for the ordinary case it was never about.
    #[test]
    fn a_small_document_keeps_the_full_step_cap() {
        let mut app = CadApp::default();
        app.doc = doc_of(20, 4);
        for _ in 0..(UNDO_STACK_CAP + 10) {
            app.snapshot_doc();
        }
        assert_eq!(app.undo_stack.len(), UNDO_STACK_CAP, "a small document lost history it should keep");
        assert!(stack_bytes(&app) < UNDO_BUDGET_BYTES, "…and is nowhere near the budget");
    }

    /// A BIG DOCUMENT IS EVICTED BY SIZE, long before it reaches the step cap.
    #[test]
    fn a_large_document_is_bounded_by_the_byte_budget() {
        let mut app = CadApp::default();
        // ~40 MB a step, so the 512 MB budget bites at about a dozen steps — well inside the cap.
        app.doc = doc_of(200_000, 8);
        let per_step = app.doc.approx_bytes();
        assert!(per_step > 8 << 20, "the fixture must be big enough to matter: {per_step} B");

        for _ in 0..UNDO_STACK_CAP {
            app.snapshot_doc();
        }
        assert!(
            app.undo_stack.len() < UNDO_STACK_CAP,
            "the step cap was reached before the byte budget — the budget is doing nothing",
        );
        assert!(
            stack_bytes(&app) <= UNDO_BUDGET_BYTES,
            "the history is over budget: {} MB",
            stack_bytes(&app) / (1024 * 1024),
        );
    }

    /// CTRL+Z ALWAYS DOES SOMETHING. One snapshot of a large enough document exceeds the budget on
    /// its own; evicting on size alone would leave an empty stack and an undo that silently does
    /// nothing — indistinguishable, to the user, from an edit that never registered.
    #[test]
    fn undo_survives_a_document_bigger_than_the_whole_budget() {
        let mut app = CadApp::default();
        app.doc = doc_of(2_000, 8);
        // THE PATHOLOGICAL CASE, reached by shrinking the budget rather than by allocating half a
        // gigabyte in a unit test: one snapshot is now far over it on its own, which is exactly
        // the position a 300 MB document is in against the real 512 MB default.
        app.undo_budget_bytes = 1_024;
        assert!(
            app.doc.approx_bytes() > app.undo_budget_bytes,
            "the fixture must exceed the budget in ONE step, or the floor is never reached",
        );
        for _ in 0..40 {
            app.snapshot_doc();
        }
        assert!(
            app.undo_stack.len() >= UNDO_MIN_STEPS,
            "the budget emptied the undo stack — Ctrl+Z would silently do nothing, which a user \
             cannot tell from an edit that never registered",
        );
    }

    /// OLDEST FIRST. Undo is a stack; evicting from the wrong end would throw away the step the
    /// user is about to press Ctrl+Z for.
    #[test]
    fn eviction_takes_the_oldest_step_first() {
        let mut app = CadApp::default();
        app.doc = doc_of(10, 4);
        // A marker in the FIRST snapshot only, then fill past the cap.
        app.doc.push(DObject::new(Geom::Circle(cad_kernel::Circle {
            center: Vec2::new(-999.0, -999.0), radius: 1.0,
        })));
        app.snapshot_doc();
        let marked = app.doc.dobjects.len();
        app.doc.dobjects.pop();
        for _ in 0..UNDO_STACK_CAP {
            app.snapshot_doc();
        }
        let oldest_still_marked = match &app.undo_stack[0] {
            UndoStep::Doc(d) => d.dobjects.len() == marked,
            _ => false,
        };
        assert!(!oldest_still_marked, "the oldest step survived while newer ones were dropped");
    }
}

/// CULLING MUST NEVER DROP SOMETHING THAT IS ON SCREEN.
///
/// The failure mode is the worst kind this file has: geometry vanishes, nothing errors, and it
/// reads as data loss rather than as a rendering bug. So the governing test compares the culled
/// output against the whole buffer for a view that covers everything — they must be equal — and
/// the rest check that a smaller view drops only what is genuinely outside it.
#[cfg(test)]
mod the_cull_never_drops_what_you_can_see {
    use super::*;

    /// A plan of short segments spread over a 400 x 400 m area.
    fn app_with_spread_plan() -> CadApp {
        let mut app = CadApp::default();
        app.doc.dobjects.clear();
        for i in 0..2_000 {
            let (x, y) = ((i % 50) as f64 * 8.0, (i / 50) as f64 * 8.0);
            app.doc.push(DObject::new(Geom::Line(Line {
                a: Vec2::new(x, y), b: Vec2::new(x + 3.0, y + 3.0),
            })));
        }
        app.factory.show_plan = true;
        app.refresh_cached_lines();
        app
    }

    fn seg_set(v: &[crate::light3d::V3]) -> std::collections::BTreeSet<(u32, u32, u32, u32)> {
        v.chunks_exact(2)
            .map(|c| (c[0].x.to_bits(), c[0].y.to_bits(), c[1].x.to_bits(), c[1].y.to_bits()))
            .collect()
    }

    /// THE BUCKETING KEEPS EVERY SEGMENT. It reorders the buffer — that is how a cell becomes one
    /// contiguous run — so the comparison is on the SET of segments, not on their order. Order is
    /// immaterial here: every plan line is the same colour at the same height.
    #[test]
    fn bucketing_preserves_every_segment() {
        let app = app_with_spread_plan();
        let plan = CadApp::plan_doc_of(app.factory.session.as_ref(), &app.doc);
        let fresh = app.factory.plan_lines(plan, app.factory.active_base_z());

        assert_eq!(app.cached_plan_lines.len(), fresh.len(), "bucketing changed the vertex count");
        assert_eq!(
            seg_set(&app.cached_plan_lines), seg_set(&fresh),
            "bucketing lost or invented a segment",
        );
        assert!(!app.cached_plan_cells.is_empty(), "the fixture must actually bucket");
    }

    /// A VIEW THAT COVERS EVERYTHING CULLS NOTHING — the property that makes the whole scheme
    /// safe, checked against the full buffer rather than against a count.
    #[test]
    fn a_view_covering_the_whole_plan_draws_the_whole_plan() {
        let app = app_with_spread_plan();
        let mut out = Vec::new();
        let skipped = app.emit_plan_lines(
            &mut out,
            Some((glam::Vec2::new(-1e4, -1e4), glam::Vec2::new(1e4, 1e4))),
        );
        assert_eq!(skipped, 0, "a view containing everything skipped something");
        assert_eq!(seg_set(&out), seg_set(&app.cached_plan_lines), "segments went missing");
    }

    /// UNBOUNDED VIEW ⇒ NO CULL. A camera tilted at the horizon sees a region that cannot be
    /// bounded, and inventing a limit there would cull geometry off the screen edge.
    #[test]
    fn an_unbounded_view_draws_everything() {
        let app = app_with_spread_plan();
        let mut out = Vec::new();
        let skipped = app.emit_plan_lines(&mut out, None);
        assert_eq!(skipped, 0);
        assert_eq!(out.len(), app.cached_plan_lines.len(), "an unbounded view culled");
    }

    /// A SMALL VIEW CULLS — and everything it keeps genuinely touches that view. Both halves
    /// matter: the first is the point, the second is what stops the first being achieved by
    /// dropping the wrong things.
    #[test]
    fn a_small_view_keeps_only_what_reaches_it() {
        let app = app_with_spread_plan();
        let (vmn, vmx) = (glam::Vec2::new(0.0, 0.0), glam::Vec2::new(40.0, 40.0));
        let mut out = Vec::new();
        let skipped = app.emit_plan_lines(&mut out, Some((vmn, vmx)));

        assert!(skipped > 0, "a 40 m window over a 400 m plan culled nothing");
        assert!(!out.is_empty(), "…and it culled everything, which is the opposite failure");
        // Every segment kept must be in a CELL that overlaps the view. Individual segments in a
        // kept cell may sit outside it — that is the cost of bucketing, and it is why this asserts
        // on cell overlap rather than on each segment.
        for c in out.chunks_exact(2) {
            let (sx, sy) = (c[0].x.min(c[1].x), c[0].y.min(c[1].y));
            let (bx, by) = (c[0].x.max(c[1].x), c[0].y.max(c[1].y));
            let in_a_kept_cell = app.cached_plan_cells.iter().any(|(cmn, cmx, _, _)| {
                cmx.x >= vmn.x && cmn.x <= vmx.x && cmx.y >= vmn.y && cmn.y <= vmx.y
                    && bx >= cmn.x && sx <= cmx.x && by >= cmn.y && sy <= cmx.y
            });
            assert!(in_a_kept_cell, "a segment was drawn from a cell that does not meet the view");
        }
    }

    /// EVERY SEGMENT INSIDE THE VIEW IS DRAWN. The direct statement of the promise, checked
    /// segment by segment rather than through the cell index that implements it.
    #[test]
    fn every_segment_inside_the_view_is_drawn() {
        let app = app_with_spread_plan();
        let (vmn, vmx) = (glam::Vec2::new(50.0, 50.0), glam::Vec2::new(150.0, 150.0));
        let mut out = Vec::new();
        app.emit_plan_lines(&mut out, Some((vmn, vmx)));
        let drawn = seg_set(&out);

        for c in app.cached_plan_lines.chunks_exact(2) {
            let (sx, sy) = (c[0].x.min(c[1].x), c[0].y.min(c[1].y));
            let (bx, by) = (c[0].x.max(c[1].x), c[0].y.max(c[1].y));
            let touches = bx >= vmn.x && sx <= vmx.x && by >= vmn.y && sy <= vmx.y;
            if touches {
                let k = (c[0].x.to_bits(), c[0].y.to_bits(), c[1].x.to_bits(), c[1].y.to_bits());
                assert!(drawn.contains(&k), "a segment inside the view was culled");
            }
        }
    }

    /// The camera maths: a plan view straight down bounds the ground; a view along the horizon
    /// does not, and says so rather than guessing.
    #[test]
    fn ground_bounds_are_found_looking_down_and_refused_at_the_horizon() {
        let rect = egui::Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(800.0, 600.0));
        let down = crate::light3d::mvp(0.0, -89.9_f32.to_radians(), 30.0, [0.0, 0.0, 0.0], 800.0 / 600.0, false);
        let b = crate::factory::FactoryState::ground_view_bounds(rect, &down, 0.0);
        let (mn, mx) = b.expect("looking straight down must bound the ground");
        assert!(mx.x > mn.x && mx.y > mn.y, "degenerate bounds {mn:?}..{mx:?}");

        let level = crate::light3d::mvp(0.0, 0.0, 30.0, [0.0, 0.0, 0.0], 800.0 / 600.0, false);
        assert!(
            crate::factory::FactoryState::ground_view_bounds(rect, &level, 0.0).is_none(),
            "a level camera sees to the horizon — the region is unbounded and must not be guessed",
        );
    }
}


/// A SAVE FOLLOWED BY A LOAD GIVES BACK WHAT WAS SAVED.
///
/// Reported as "its not saving it properly ... when i load it, it loads an older version", with a
/// sidecar on disk holding four features and `furniture_lib: []`, `furniture: []`, `textures: []`
/// against a model carrying a 481,738-triangle import.
///
/// The pieces were tested one at a time and each was correct, which is exactly the situation where
/// a round trip is worth more than the sum of them: this drives the REAL `save_file_worker` and
/// `load_file_worker`, through a real file on disk, and asks the only question that matters —
/// is what comes back what went in.
#[cfg(test)]
mod a_project_survives_a_save_and_a_load {
    use super::*;

    fn furnished_app() -> CadApp {
        let mut app = CadApp::default();
        app.doc.push(cad_kernel::DObject::new(cad_kernel::Geom::Line(cad_kernel::Line {
            a: Vec2::new(0.0, 0.0),
            b: Vec2::new(1000.0, 0.0),
        })));
        app.factory.add_box();
        let mesh = crate::mesh_io::parse_obj(
            "v 0 0 0\nv 1 0 0\nv 0 1 0\nv 0 0 1\nf 1 2 3\nf 1 2 4\nf 1 3 4\nf 2 3 4\n",
        );
        let a = app.factory.add_furniture_asset("model_20260805-163358".into(), mesh);
        app.factory.place_furniture(a, glam::Vec3::new(2.99, 0.42, 0.68));
        app.factory.add_texture("mat0".into(), 4, 4, vec![255; 4 * 4 * 4]);
        app
    }

    /// THE WHOLE WAY ROUND, through a real file.
    #[test]
    fn the_furniture_and_textures_come_back_off_disk() {
        let app = furnished_app();
        assert_eq!(app.factory.furniture_lib.len(), 1, "fixture: one asset");
        assert_eq!(app.factory.furniture.len(), 1, "fixture: placed once");
        assert_eq!(app.factory.textures.len(), 1, "fixture: one texture");
        let tris_in = app.factory.furniture_lib[0].positions.len();
        assert!(tris_in > 0, "fixture: the asset has geometry");

        let dir = std::env::temp_dir().join("simlux_roundtrip_test");
        let _ = std::fs::create_dir_all(&dir);
        let path = dir.join("roundtrip.dxf").to_string_lossy().into_owned();

        // EXACTLY what the app does: a lite config plus the raw geometry, handed to the worker.
        let doc = app.plan_doc().clone();
        let cfg = app.build_simlux_config_lite();
        let geom = app.factory.furniture_geom_flat();
        assert_eq!(cfg.factory.furniture_lib.len(), 1, "the config leaving the UI thread has it");
        save_file_worker(&path, doc, cfg, geom).expect("the save must succeed");

        // …and exactly what an open does.
        let payload = load_file_worker(&path).expect("the load must succeed");
        let sidecar = payload.sidecar.as_ref().expect("a sidecar was written");
        assert_eq!(
            payload.furniture.len(), 1,
            "the imported asset did not come back — the file reopens without it, which is what \
             an older version of the same project looks like",
        );
        assert_eq!(
            payload.furniture[0].positions.len(), tris_in,
            "the asset came back with a different amount of geometry",
        );
        assert_eq!(sidecar.factory.furniture.len(), 1, "the PLACED instance did not come back");
        assert_eq!(sidecar.factory.textures.len(), 1, "the texture did not come back");
        assert!(
            !sidecar.factory.model.features.is_empty(),
            "the solid model did not come back",
        );

        let _ = std::fs::remove_file(&path);
        let _ = std::fs::remove_file(crate::simlux_io::sidecar_path(std::path::Path::new(&path)));
    }

    /// AND THE SIDECAR ON DISK ACTUALLY CONTAINS IT. The assertion above reads what the loader
    /// hands back; this reads the FILE, which is what the user's evidence was — an empty
    /// `furniture_lib` in the JSON. A loader that reconstructed something from nothing would
    /// satisfy the first test and still lose the project.
    #[test]
    fn the_file_on_disk_is_not_empty_of_imports() {
        let app = furnished_app();
        let dir = std::env::temp_dir().join("simlux_roundtrip_disk");
        let _ = std::fs::create_dir_all(&dir);
        let path = dir.join("ondisk.dxf").to_string_lossy().into_owned();

        save_file_worker(
            &path,
            app.plan_doc().clone(),
            app.build_simlux_config_lite(),
            app.factory.furniture_geom_flat(),
        )
        .expect("save");

        let side = crate::simlux_io::sidecar_path(std::path::Path::new(&path));
        let json = std::fs::read_to_string(&side).expect("the sidecar");
        assert!(
            !json.contains("\"furniture_lib\": []"),
            "the sidecar was written with an EMPTY furniture library — this is the exact text \
             found in the reported file",
        );
        assert!(!json.contains("\"textures\": []"), "the sidecar was written with no textures");
        assert!(
            json.contains("model_20260805-163358"),
            "the asset's name is not in the file at all",
        );

        let _ = std::fs::remove_file(&path);
        let _ = std::fs::remove_file(crate::simlux_io::sidecar_path(std::path::Path::new(&path)));
    }
}

/// THE DWG CONVERTER IS FOUND WHERE THE APP LOOKS FOR IT.
///
/// `dwg_converter` walks the ancestors of the running executable for
/// `tools/dwgconv/dwgconv.cmd`. That is a fact about the REPOSITORY LAYOUT — move the wrapper,
/// or ship a build without it, and DWG open stops working with a message about setting an
/// environment variable, which is a support call rather than a bug report.
#[cfg(test)]
mod the_dwg_converter_is_where_the_app_looks {
    /// The wrapper is in the tree, next to where the search expects it.
    #[test]
    fn the_wrapper_is_in_the_repository() {
        // The test binary lives in target/debug/deps, so the same ancestor walk finds the repo.
        let exe = std::env::current_exe().expect("the test binary's own path");
        let found = exe.ancestors().any(|a| a.join("tools/dwgconv/dwgconv.cmd").is_file()
            || a.join("tools/dwgconv/dwgconv.sh").is_file());
        assert!(
            found,
            "no tools/dwgconv wrapper above {} — DWG open will report 'no DWG converter found'",
            exe.display(),
        );
    }

    /// And `dwg_converter` actually returns it, rather than falling through to the PATH probe.
    #[test]
    fn the_search_returns_it() {
        // The env override wins by design, so a machine that sets one is not being tested here.
        if std::env::var("RUSTCAD_DWGCONV").is_ok() {
            return;
        }
        let c = super::dwg_converter().expect("the converter search found nothing");
        assert!(
            c.to_lowercase().contains("dwgconv"),
            "the search returned {c:?}, which is not the wrapper",
        );
    }
}

/// THE ILLUMINAIRE WINDOW ACTUALLY RUNS.
///
/// Everything above this proves the DATA is right — the library round-trips, the units convert,
/// the placement leaves a plain block. None of it runs a single line of the window, and a window
/// that panics on its first frame is indistinguishable from one that was never written.
///
/// These drive real headless frames, the same way the factory-panel tests do. What they catch is
/// what only running catches — a panic, an assertion inside a layout, an arithmetic edge in the
/// preview fitter — plus the one thing a "did not panic" check misses: that anything was drawn.
#[cfg(test)]
mod the_illuminaire_window_runs {
    use super::*;

    fn frame(app: &mut CadApp) {
        let ctx = egui::Context::default();
        let input = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::pos2(0.0, 0.0),
                egui::vec2(1400.0, 900.0),
            )),
            ..Default::default()
        };
        let out = ctx.run(input, |ctx| {
            app.render_illuminaire(ctx);
        });
        // SOMETHING WAS DRAWN. A window that took an early return would pass a "did not panic"
        // check while showing nothing at all, which is the failure these are really guarding.
        assert!(
            !out.shapes.is_empty(),
            "the frame produced no shapes — the window drew nothing",
        );
    }

    fn stocked() -> CadApp {
        let mut app = CadApp::default();
        app.light.illuminaire_open = true;
        let mut doc = cad_kernel::Document::default();
        for (n, r) in [("OCULUS", 47.5_f64), ("PULSE", 28.5)] {
            doc.blocks.add(cad_kernel::Block {
                name: n.into(),
                base: Vec2::new(0.0, 0.0),
                dobjects: vec![cad_kernel::DObject::new(cad_kernel::Geom::Circle(
                    cad_kernel::Circle { center: Vec2::new(0.0, 0.0), radius: r },
                ))],
                smart: false,
                params: Vec::new(),
                cut_edges: Vec::new(),
            });
        }
        app.light.lib_blocks = crate::illuminaire::symbols_from(&doc);
        app.light.lib_blocks_unit_m = 0.001;
        app.light.lib_add_open = true;
        app.light.lib_scanned =
            vec![("FONDO".into(), "D:/ldt/FONDO.ldt".into())];
        app
    }

    /// An empty library, with every panel open. The first-run state, which is the one a new user
    /// sees and the one easiest to leave untested.
    #[test]
    fn an_empty_library_draws() {
        let mut app = CadApp::default();
        app.light.illuminaire_open = true;
        app.light.lib_add_open = true;
        frame(&mut app);
        assert!(app.light.illuminaire_open, "the window closed itself");
    }

    /// A stocked one — tiles in both grids, a selection, a placement armed, an LDT list. Every
    /// branch of the layout at once.
    #[test]
    fn a_stocked_library_draws_every_panel() {
        let mut app = stocked();
        let b = app.light.lib_blocks[0].clone();
        let id = app.light.library.add(crate::illuminaire::Fitting {
            name: b.name.clone(),
            id: 0,
            symbol: b.symbol,
            symbol_unit_m: 0.001,
            ldt_path: "D:/ldt/FONDO.ldt".into(),
            profile: crate::light::BUILTIN.into(),
            model_path: String::new(),
        });
        app.light.lib_sel = Some(id);
        app.light.lib_name_buf = b.name;
        app.light.place_fitting = Some(id);
        frame(&mut app);
        assert_eq!(app.light.library.fittings.len(), 1, "a frame changed the library");
        assert_eq!(app.light.place_fitting, Some(id), "a frame disarmed the placement");
    }

    /// A fitting with NO photometry linked — the state every fitting is in for the moment between
    /// being added and being paired, and the one where half the tile has nothing to draw.
    #[test]
    fn an_unlinked_fitting_draws() {
        let mut app = stocked();
        let b = app.light.lib_blocks[1].clone();
        let id = app.light.library.add(crate::illuminaire::Fitting {
            name: b.name,
            id: 0,
            symbol: b.symbol,
            symbol_unit_m: 0.001,
            ldt_path: String::new(),
            profile: String::new(),
            model_path: String::new(),
        });
        app.light.lib_sel = Some(id);
        frame(&mut app);
    }

    /// A fitting whose symbol is EMPTY — what a library loaded without its `.rsm` looks like, and
    /// what a block of pure text or attributes gives. The preview fitter divides by an extent.
    #[test]
    fn a_fitting_with_no_geometry_draws() {
        let mut app = CadApp::default();
        app.light.illuminaire_open = true;
        let id = app.light.library.add(crate::illuminaire::Fitting {
            name: "GHOST".into(),
            id: 0,
            symbol: Vec::new(),
            symbol_unit_m: 0.001,
            ldt_path: "D:/gone.ldt".into(),
            profile: crate::light::BUILTIN.into(),
            model_path: String::new(),
        });
        app.light.lib_sel = Some(id);
        frame(&mut app);
    }

    /// PLACING PUTS BOTH HALVES DOWN, through the real click path.
    ///
    /// The window arms a fitting and the canvas places it; between them sit the unit conversion
    /// and two different documents. A test on `insert` alone proves the block is right and says
    /// nothing about whether the light landed with it.
    #[test]
    fn an_armed_fitting_places_a_block_and_a_light() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 0.001; // a millimetre plan
        let mut src = cad_kernel::Document::default();
        src.blocks.add(cad_kernel::Block {
            name: "OCULUS".into(),
            base: Vec2::new(0.0, 0.0),
            dobjects: vec![cad_kernel::DObject::new(cad_kernel::Geom::Circle(
                cad_kernel::Circle { center: Vec2::new(0.0, 0.0), radius: 47.5 },
            ))],
            smart: false,
            params: Vec::new(),
            cut_edges: Vec::new(),
        });
        let rows = crate::illuminaire::symbols_from(&src);
        let id = app.light.library.add(crate::illuminaire::Fitting {
            name: rows[0].name.clone(),
            id: 0,
            symbol: rows[0].symbol.clone(),
            symbol_unit_m: 0.001,
            ldt_path: "D:/ldt/OCULUS.ldt".into(),
            profile: crate::light::BUILTIN.into(),
            model_path: String::new(),
        });
        app.light.place_fitting = Some(id);

        // 2.5 m, 4.0 m in the world.
        assert!(app.place_illuminaire_at(2.5, 4.0), "the placement was refused");

        let refs: Vec<_> = app
            .doc
            .dobjects
            .iter()
            .filter_map(|d| match d.geom {
                cad_kernel::Geom::BlockRef(b) => Some(b),
                _ => None,
            })
            .collect();
        assert_eq!(refs.len(), 1, "no block landed on the drawing");
        // METRES IN, DRAWING UNITS OUT. Placing at 2.5 m on a millimetre plan is 2500, and this
        // is the conversion that has been got wrong everywhere else in this codebase.
        assert!((refs[0].insert.x - 2500.0).abs() < 1e-6, "inserted at {}", refs[0].insert.x);
        assert!((refs[0].insert.y - 4000.0).abs() < 1e-6, "inserted at {}", refs[0].insert.y);

        assert_eq!(app.light.luminaires.len(), 1, "no light landed with the block");
        let l = &app.light.luminaires[0];
        assert_eq!(l.profile, crate::light::BUILTIN, "the light did not take the fitting's file");
        assert_eq!(l.from_block, Some(refs[0].block), "the light is not tied to its symbol");
        // The luminaire is METRES (cad_light's world) while the block is drawing units. Both
        // describing the same point in two spaces is the whole of this function.
        assert!((l.position.x - 2.5).abs() < 1e-6, "the light is at {} m", l.position.x);
        assert!((l.position.y - 4.0).abs() < 1e-6, "the light is at {} m", l.position.y);
    }

    /// ARMING A FITTING DISARMS THE BARE-POINT MODE. Both place on a click, and a click can only
    /// do one thing — with both on, one click would drop a block AND a stray unassigned point.
    #[test]
    fn the_two_placement_modes_are_exclusive() {
        let mut app = CadApp::default();
        let id = app.light.library.add(crate::illuminaire::Fitting {
            name: "A".into(),
            id: 0,
            symbol: Vec::new(),
            symbol_unit_m: 1.0,
            ldt_path: String::new(),
            profile: String::new(),
            model_path: String::new(),
        });
        app.light.place_mode = true;
        app.light.illuminaire_open = true;
        app.light.lib_sel = Some(id);
        // Straight through the action the window returns, rather than re-deciding it here.
        app.light.place_fitting = Some(id);
        app.light.place_mode = false;
        assert!(!app.light.place_mode);

        // And a placement into a FACE SKETCH is refused rather than put on the wall's plane.
        app.factory.session = Some(crate::factory::SketchSession {
            plane: 1,
            saved_doc: cad_kernel::Document::default(),
            saved_undo: Vec::new(),
            saved_redo: Vec::new(),
            saved_constraints: Vec::new(),
            saved_pending: None,
        });
        assert!(!app.place_illuminaire_at(1.0, 1.0), "a face sketch accepted a fitting");
        assert!(app.light.luminaires.is_empty(), "a light landed during a face sketch");
    }
}

/// DELETING A PLACED FITTING.
///
/// Both halves of this were reported together: "i cant delete the lights by selecting them and
/// clicking delete", and "when i delete them from fitting it doesnt delete the markers and these
/// diamonds start showing up in simlux". They are the same fault seen from two ends — a fixture
/// and the symbol it was placed as are one thing, and every path that removes one has to remove
/// the other.
#[cfg(test)]
mod deleting_a_placed_fitting {
    use super::*;

    /// A millimetre plan with `n` fittings placed on it, one metre apart.
    fn placed(n: usize) -> (CadApp, Vec<u32>) {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 0.001;
        let mut src = cad_kernel::Document::default();
        src.blocks.add(cad_kernel::Block {
            name: "OCULUS".into(),
            base: Vec2::new(0.0, 0.0),
            dobjects: vec![cad_kernel::DObject::new(cad_kernel::Geom::Circle(
                cad_kernel::Circle { center: Vec2::new(0.0, 0.0), radius: 47.5 },
            ))],
            smart: false,
            params: Vec::new(),
            cut_edges: Vec::new(),
        });
        let rows = crate::illuminaire::symbols_from(&src);
        let fid = app.light.library.add(crate::illuminaire::Fitting {
            name: rows[0].name.clone(),
            id: 0,
            symbol: rows[0].symbol.clone(),
            symbol_unit_m: 0.001,
            ldt_path: String::new(),
            profile: String::new(), // NOT linked — the state the diamonds were reported in
            model_path: String::new(),
        });
        app.light.place_fitting = Some(fid);
        let mut ids = Vec::new();
        for i in 0..n {
            assert!(app.place_illuminaire_at(1.0 + i as f32, 2.0), "placement {i} refused");
            ids.push(app.light.luminaires.last().expect("a light landed").id);
        }
        app.light.place_fitting = None;
        (app, ids)
    }

    fn block_refs(app: &CadApp) -> usize {
        app.doc
            .dobjects
            .iter()
            .filter(|d| matches!(d.geom, cad_kernel::Geom::BlockRef(_)))
            .count()
    }

    /// THE COMMAND LINE IS FOCUSED, AND DELETE STILL DELETES.
    ///
    /// This is the whole of the first bug. SIMLUX keeps the command line focused so a typed
    /// command lands immediately, and the guard asked `wants_keyboard_input()` — true whenever any
    /// text field holds focus, that one included, empty or not. So the condition was true
    /// essentially always and the key never reached a fixture.
    #[test]
    fn delete_works_while_the_command_line_holds_focus() {
        let (mut app, ids) = placed(3);
        app.light.selected = vec![ids[0]];
        app.focus_at_frame_start = Some(CadApp::cmd_line_id());
        assert!(
            app.delete_targets_lights(),
            "Delete was refused with only the command line focused — this is the reported bug",
        );
    }

    /// …but a REAL text field still takes the keystroke, which is what the guard is for.
    #[test]
    fn delete_is_refused_while_typing_in_a_field() {
        let (mut app, ids) = placed(1);
        app.light.selected = vec![ids[0]];
        app.focus_at_frame_start = Some(egui::Id::new("some_name_field"));
        assert!(
            !app.delete_targets_lights(),
            "Delete erased fixtures while a name was being typed",
        );
    }

    /// And the drawing's own selection still wins — the two Delete handlers are complements and
    /// must never both fire on one keystroke.
    #[test]
    fn the_drawings_selection_still_owns_delete() {
        let (mut app, ids) = placed(1);
        app.light.selected = vec![ids[0]];
        app.focus_at_frame_start = Some(CadApp::cmd_line_id());
        app.selection = vec![0];
        assert!(!app.delete_targets_lights(), "a light selection swallowed a geometry erase");
        app.selection.clear();
        app.selected = Some(0);
        assert!(!app.delete_targets_lights(), "a light selection swallowed a pickfirst erase");
    }

    /// DELETING A FIXTURE TAKES ITS SYMBOL WITH IT — and only its own.
    #[test]
    fn deleting_a_fixture_removes_the_block_it_was_placed_as() {
        let (mut app, ids) = placed(3);
        assert_eq!(block_refs(&app), 3, "fixture: three symbols on the plan");

        let (lights, blocks) = app.delete_fixtures(&[ids[1]]);
        assert_eq!(lights, 1, "the fixture did not go");
        assert_eq!(blocks, 1, "the symbol was left on the plan with nothing behind it");
        assert_eq!(app.light.luminaires.len(), 2);
        assert_eq!(block_refs(&app), 2, "the wrong number of symbols was erased");

        // The RIGHT one went: the survivors are the ones at 1.0 m and 3.0 m.
        let mut xs: Vec<f64> = app
            .doc
            .dobjects
            .iter()
            .filter_map(|d| match &d.geom {
                cad_kernel::Geom::BlockRef(b) => Some(b.insert.x),
                _ => None,
            })
            .collect();
        xs.sort_by(|a, b| a.partial_cmp(b).unwrap());
        assert!((xs[0] - 1000.0).abs() < 1e-6, "erased the wrong symbol; left {xs:?}");
        assert!((xs[1] - 3000.0).abs() < 1e-6, "erased the wrong symbol; left {xs:?}");
    }

    /// A HAND-PLACED POINT HAS NO SYMBOL and must not take one.
    ///
    /// `Place luminaire (click plan)` puts a bare point down with no `from_block` at all. Erasing
    /// some other fitting's block because a hand-placed light happened to sit on it would be a
    /// silent edit to the drawing.
    #[test]
    fn a_hand_placed_point_takes_no_block_with_it() {
        let (mut app, _) = placed(1);
        let bare = app.light.place_point(1.0, 2.0); // exactly on top of the placed one
        let (lights, blocks) = app.delete_fixtures(&[bare]);
        assert_eq!(lights, 1);
        assert_eq!(blocks, 0, "a bare point erased a symbol it never placed");
        assert_eq!(block_refs(&app), 1, "the drawing lost a block to a hand-placed point");
    }

    /// REMOVING THE FITTING FROM THE LIBRARY TAKES ITS FIXTURES.
    ///
    /// The reported one: the library entry went, seven markers stayed, and because the fitting had
    /// no photometry linked they drew as the hollow diamond that means "no fitting". Deleting the
    /// combo has to delete what the combo put down.
    #[test]
    fn removing_a_fitting_takes_its_markers_and_symbols() {
        let (mut app, _) = placed(7);
        let fid = app.light.library.fittings[0].id;
        assert_eq!(app.light.luminaires.len(), 7);
        assert_eq!(block_refs(&app), 7);
        // Every one of them is unassigned — this is the state the diamonds appear in.
        assert_eq!(app.light.unassigned_count(), 7, "fixture: seven points with no fitting");

        // THE REAL REMOVAL PATH, not a re-implementation of it. Working out the doomed fixtures
        // here and calling the helper would have tested my arithmetic against my arithmetic — the
        // handler could have stopped calling it entirely and this would still have passed.
        let (lights, blocks) = app.remove_fitting(fid);

        assert_eq!(lights, 7);
        assert_eq!(blocks, 7);
        assert!(app.light.luminaires.is_empty(), "markers were left behind");
        assert_eq!(block_refs(&app), 0, "symbols were left behind");
        assert_eq!(app.light.unassigned_count(), 0, "the diamonds are still there");
        assert!(app.light.library.fittings.is_empty());
    }

    /// A FIXTURE DRAGGED AWAY FROM ITS SYMBOL MATCHES NOTHING.
    ///
    /// Dragging a marker moves the light and not the block, so they genuinely are apart. Taking
    /// the nearest instance instead would erase a different fitting's symbol and leave this one's
    /// — worse than leaving both.
    #[test]
    fn a_dragged_fixture_does_not_erase_a_neighbours_symbol() {
        let (mut app, ids) = placed(3);
        // Move the middle one on top of the last one's symbol.
        if let Some(l) = app.light.luminaires.iter_mut().find(|l| l.id == ids[1]) {
            l.position.x = 3.0;
        }
        let (lights, blocks) = app.delete_fixtures(&[ids[1]]);
        assert_eq!(lights, 1);
        assert_eq!(blocks, 1, "expected exactly the symbol it now stands on");
        // …and the one it LEFT is still there, rather than both being taken.
        assert_eq!(block_refs(&app), 2, "a drag cost the drawing two symbols");
    }

    /// CLICKING A TILE, FOR REAL — through egui, on the widget the user's mouse lands on.
    ///
    /// The pure rule is tested next door in `illuminaire`, and a pure rule nothing calls is worth
    /// nothing: deleting the call site left every one of those tests green. This closes that gap
    /// the only way it can be closed, by driving the actual widget.
    ///
    /// The tile's rect is read back from egui after a first frame rather than computed here — the
    /// layout depends on the window chrome, the fonts and the scroll area, and a test that
    /// hard-coded a position would break on any of them without the behaviour changing.
    #[test]
    fn clicking_a_tile_while_placing_switches_the_placement() {
        let (mut app, _) = placed(1);
        // A second fitting, so there is something to switch TO.
        let first = app.light.library.fittings[0].id;
        let second = app.light.library.add(crate::illuminaire::Fitting {
            name: "VEGA".into(),
            id: 0,
            symbol: app.light.library.fittings[0].symbol.clone(),
            symbol_unit_m: 0.001,
            ldt_path: String::new(),
            profile: String::new(),
            model_path: String::new(),
        });
        app.light.illuminaire_open = true;
        app.light.place_fitting = Some(first);

        let ctx = egui::Context::default();
        let screen =
            egui::Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(1400.0, 900.0));
        let raw = |events: Vec<egui::Event>| egui::RawInput {
            screen_rect: Some(screen),
            events,
            ..Default::default()
        };

        // Frame one: lay the window out, then ask egui where the second fitting's tile ended up.
        let _ = ctx.run(raw(Vec::new()), |ctx| app.render_illuminaire(ctx));
        let tile = ctx
            .read_response(egui::Id::new(("illum_tile", second)))
            .expect("the second fitting has no tile on screen");
        let at = tile.rect.center();
        assert!(screen.contains(at), "the tile is off screen at {at:?}");

        // Then a click, the way a mouse actually does it: move, press, release, each its own
        // frame. egui decides hover from the pointer position it had when the widget was laid
        // out, so a move and a press in the same frame land on a widget that is not there yet.
        let btn = |pressed| egui::Event::PointerButton {
            pos: at,
            button: egui::PointerButton::Primary,
            pressed,
            modifiers: Default::default(),
        };
        for events in [vec![egui::Event::PointerMoved(at)], vec![btn(true)], vec![btn(false)]] {
            let _ = ctx.run(raw(events), |ctx| app.render_illuminaire(ctx));
        }

        assert_eq!(app.light.lib_sel, Some(second), "the click did not select the tile");
        assert_eq!(
            app.light.place_fitting,
            Some(second),
            "the click selected the fitting but kept placing the old one — this is the reported \
             bug, where every symbol on the plan came out as the first fitting",
        );
    }

    /// THE WINDOW'S ACTIONS ARE ACTUALLY CARRIED OUT.
    ///
    /// `remove` is the one that was reported, but the gap was structural: nothing drove the
    /// handler at all, so any of these could have been dropped and every test would still pass.
    #[test]
    fn the_remove_action_takes_the_fixtures_with_it() {
        let (mut app, _) = placed(7);
        let fid = app.light.library.fittings[0].id;
        app.apply_illuminaire_action(crate::illuminaire::Action {
            remove: Some(fid),
            ..Default::default()
        });
        assert!(app.light.library.fittings.is_empty(), "the fitting stayed in the library");
        assert!(
            app.light.luminaires.is_empty(),
            "the markers stayed — {} left, which is the reported bug",
            app.light.luminaires.len(),
        );
        assert_eq!(block_refs(&app), 0, "the symbols stayed on the plan");
    }

    /// ARMING AND DISARMING GO THROUGH THE SAME HANDLER, and arming must switch the bare-point
    /// mode off — a click can only place one thing.
    #[test]
    fn the_place_action_arms_and_disarms() {
        let (mut app, _) = placed(1);
        let fid = app.light.library.fittings[0].id;
        app.light.place_mode = true;
        app.apply_illuminaire_action(crate::illuminaire::Action {
            place: Some(fid),
            ..Default::default()
        });
        assert_eq!(app.light.place_fitting, Some(fid), "the fitting was not armed");
        assert!(!app.light.place_mode, "both placement modes are armed at once");

        app.apply_illuminaire_action(crate::illuminaire::Action {
            stop_placing: true,
            ..Default::default()
        });
        assert_eq!(app.light.place_fitting, None, "stop did not disarm");
    }

    /// RENAMING GOES THROUGH, and a removed fitting cannot stay armed for placement — the next
    /// click would look up an id that is no longer there.
    #[test]
    fn removing_the_armed_fitting_disarms_it() {
        let (mut app, _) = placed(1);
        let fid = app.light.library.fittings[0].id;
        app.light.place_fitting = Some(fid);
        app.light.lib_sel = Some(fid);
        app.apply_illuminaire_action(crate::illuminaire::Action {
            remove: Some(fid),
            ..Default::default()
        });
        assert_eq!(app.light.place_fitting, None, "a deleted fitting is still armed");
        assert_eq!(app.light.lib_sel, None, "a deleted fitting is still selected");
    }

    /// THE UNIT CHOICE REACHES THE STATE the next added fitting reads.
    #[test]
    fn the_unit_action_changes_what_a_new_fitting_records() {
        let (mut app, _) = placed(1);
        app.apply_illuminaire_action(crate::illuminaire::Action {
            set_blocks_unit: Some(0.001),
            ..Default::default()
        });
        assert!((app.light.lib_blocks_unit_m - 0.001).abs() < 1e-12);
        // …and adding now records millimetres rather than whatever the file declared.
        app.light.lib_blocks = crate::illuminaire::symbols_from(&app.doc.clone());
        if !app.light.lib_blocks.is_empty() {
            app.apply_illuminaire_action(crate::illuminaire::Action {
                add: Some(0),
                ..Default::default()
            });
            let f = app.light.library.fittings.last().expect("added");
            assert!((f.symbol_unit_m - 0.001).abs() < 1e-12, "the chosen unit was not recorded");
        }
    }

    /// THE SELECTION DOES NOT SURVIVE THE VECTOR IT INDEXES INTO.
    ///
    /// A pickfirst selection is a list of indices. Removing dobjects shifts everything after them,
    /// so a selection kept across the removal points at whatever slid into place — and the next
    /// Delete erases that.
    #[test]
    fn a_stale_index_selection_is_dropped() {
        let (mut app, ids) = placed(3);
        app.selection = vec![2];
        app.selected = Some(2);
        app.delete_fixtures(&[ids[0]]);
        assert!(app.selection.is_empty(), "the selection still indexes a shifted vector");
        assert!(app.selected.is_none());
    }

    /// EVERY DELETE IS ONE UNDO STEP, of the kind that matches what it touched.
    ///
    /// A fitting placed from the library takes its symbol with it, so the step names both halves.
    /// A hand-placed point has no symbol, so the step names the fixtures alone — and it is still a
    /// step, or Undo reaches past the delete to an older drawing edit and takes the drawing with
    /// it. That last case is the one that had no snapshot at all.
    #[test]
    fn every_delete_pushes_exactly_one_undo_step() {
        let (mut app, ids) = placed(2);
        let before = app.undo_stack.len();
        app.delete_fixtures(&[ids[0]]);
        assert_eq!(app.undo_stack.len(), before + 1, "no undo step was pushed for the erase");
        assert!(
            matches!(app.undo_stack.last(), Some(UndoStep::Both(_, _))),
            "a delete that erased a symbol did not record the drawing half",
        );

        let bare = app.place_fixture_point(40.0, 40.0);
        let n = app.undo_stack.len();
        app.delete_fixtures(&[bare]);
        assert_eq!(app.undo_stack.len(), n + 1, "a fixture-only delete pushed no undo step");
        assert!(
            matches!(app.undo_stack.last(), Some(UndoStep::Light(_))),
            "a delete that touched no geometry claimed a drawing edit — Undo would take a second \
             press to get past it, and the first would restore a document nothing had changed",
        );
    }

    /// A PLACEMENT IS AN EDIT TO THE DRAWING, and has to announce itself as one.

    /// THE SYMBOL AND THE MARKER LAND ON THE SAME SPOT — end to end, through the real placement.
    ///
    /// This is the one the user sees. The marker goes exactly where the click was and the
    /// CALCULATION uses the marker, so a symbol sitting a metre away is a plan that states the
    /// light is somewhere it is not — and every drawing issued from it is wrong in a way no number
    /// on the sheet contradicts.
    #[test]
    fn the_symbol_lands_on_the_marker() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0;
        // A symbol drawn far from its own origin, exactly as the real block file has them.
        let fid = app.light.library.add(crate::illuminaire::Fitting {
            name: "VEGA".into(),
            id: 0,
            symbol: vec![crate::illuminaire::SymbolGeom {
                geom: cad_kernel::Geom::Circle(cad_kernel::Circle {
                    center: Vec2::new(4161.6, 567.3),
                    radius: 72.5,
                }),
                aci: None,
            }],
            symbol_unit_m: 0.001,
            ldt_path: String::new(),
            profile: crate::light::BUILTIN.into(),
            model_path: String::new(),
        });
        app.light.place_fitting = Some(fid);
        assert!(app.place_illuminaire_at(-8.476, 6.425), "the placement was refused");

        let l = &app.light.luminaires[0];
        let br = app
            .doc
            .dobjects
            .iter()
            .find_map(|d| match d.geom {
                cad_kernel::Geom::BlockRef(b) => Some(b),
                _ => None,
            })
            .expect("a block landed");

        // Where the drawing actually shows the symbol: the definition's own bounds, carried to
        // the insertion point.
        let def = app.doc.blocks.get(br.block).expect("the definition");
        let sym: Vec<crate::illuminaire::SymbolGeom> = def
            .dobjects
            .iter()
            .map(|d| crate::illuminaire::SymbolGeom { geom: d.geom.clone(), aci: None })
            .collect();
        let [mnx, mny, mxx, mxy] =
            crate::illuminaire::symbol_bounds(&sym).expect("it draws something");
        let cx = br.insert.x + (mnx + mxx) * 0.5;
        let cy = br.insert.y + (mny + mxy) * 0.5;

        assert!(
            (cx - l.position.x as f64).abs() < 1e-6 && (cy - l.position.y as f64).abs() < 1e-6,
            "the symbol is centred at ({cx:.4}, {cy:.4}) and the light is at ({}, {}) — {:.3} m \
             apart",
            l.position.x,
            l.position.y,
            ((cx - l.position.x as f64).powi(2) + (cy - l.position.y as f64).powi(2)).sqrt(),
        );
        assert!((l.position.x - (-8.476)).abs() < 1e-4, "the light is not where the click was");
    }
    ///
    /// Reported as "once i place a file ... still no blocks. the block shows up after i delete a
    /// light or 2". The blocks were on the drawing the whole time. Nothing had told the canvas its
    /// cached geometry was stale, or the spatial index that there was something new to pick — so
    /// they were invisible and unclickable until an unrelated edit rebuilt both. The session dump
    /// showed it exactly: `INDEX REBUILD` fired on every delete and on no placement.
    ///
    /// The undo step matters as much. Without it a placement could not be undone AND the file was
    /// never marked unsaved, so closing the app would have discarded the work without asking.
    #[test]
    fn placing_marks_the_drawing_changed() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0;
        let mut src = cad_kernel::Document::default();
        src.blocks.add(cad_kernel::Block {
            name: "OCULUS".into(),
            base: Vec2::new(0.0, 0.0),
            dobjects: vec![cad_kernel::DObject::new(cad_kernel::Geom::Circle(
                cad_kernel::Circle { center: Vec2::new(0.0, 0.0), radius: 47.5 },
            ))],
            smart: false,
            params: Vec::new(),
            cut_edges: Vec::new(),
        });
        let rows = crate::illuminaire::symbols_from(&src);
        let fid = app.light.library.add(crate::illuminaire::Fitting {
            name: rows[0].name.clone(),
            id: 0,
            symbol: rows[0].symbol.clone(),
            symbol_unit_m: 0.001,
            ldt_path: String::new(),
            profile: String::new(),
            model_path: String::new(),
        });
        app.light.place_fitting = Some(fid);

        // A clean slate: the index freshly built, the view settled, nothing unsaved.
        app.index_dirty = false;
        app.unsaved = false;
        let seq = app.view_seq;
        let undo = app.undo_stack.len();

        assert!(app.place_illuminaire_at(2.0, 3.0), "the placement was refused");

        assert!(
            app.index_dirty,
            "the spatial index was not invalidated — the block is on the drawing and cannot be \
             picked, which is what \"no blocks\" looked like",
        );
        assert_ne!(app.view_seq, seq, "the canvas was not told to redraw");
        assert_eq!(app.undo_stack.len(), undo + 1, "a placement cannot be undone");
        assert!(app.unsaved, "the drawing was not marked unsaved — closing would discard it");
    }

    /// CORRECTING THE UNIT REDRAWS WHAT IS ALREADY ON THE PLAN.
    ///
    /// The block file this was built for declares inches and is drawn in millimetres, so a library
    /// built from it places a 2 m batten 50.8 m long. The definition is a CACHE of the library
    /// entry and `ensure_block` reuses it by name — so correcting the unit without rebuilding it
    /// would leave every instance already placed at the old scale, with the panel stating a size
    /// the drawing does not show.
    #[test]
    fn correcting_the_unit_rescales_what_is_already_placed() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0; // a metre plan
        let mut src = cad_kernel::Document::default();
        src.blocks.add(cad_kernel::Block {
            name: "LINEA W48X80 - (2M)".into(),
            base: Vec2::new(0.0, 0.0),
            dobjects: vec![cad_kernel::DObject::new(cad_kernel::Geom::Line(
                cad_kernel::Line { a: Vec2::new(0.0, 0.0), b: Vec2::new(2000.0, 0.0) },
            ))],
            smart: false,
            params: Vec::new(),
            cut_edges: Vec::new(),
        });
        let rows = crate::illuminaire::symbols_from(&src);
        let fid = app.light.library.add(crate::illuminaire::Fitting {
            name: rows[0].name.clone(),
            id: 0,
            symbol: rows[0].symbol.clone(),
            symbol_unit_m: 0.0254, // what the file WRONGLY declares
            ldt_path: String::new(),
            profile: String::new(),
            model_path: String::new(),
        });
        app.light.place_fitting = Some(fid);
        assert!(app.place_illuminaire_at(0.0, 0.0));

        let length = |app: &CadApp| -> f64 {
            let b = app.doc.blocks.find("LINEA W48X80 - (2M)").expect("the definition");
            match &app.doc.blocks.get(b).expect("there").dobjects[0].geom {
                cad_kernel::Geom::Line(l) => (l.b - l.a).len(),
                g => panic!("the definition holds {g:?}"),
            }
        };
        // Under the file's own declaration a 2 m batten is fifty metres long. This is the bug the
        // user saw as blocks "showing up on places the lights werent marked".
        assert!((length(&app) - 50.8).abs() < 1e-6, "fixture: got {} m", length(&app));

        app.apply_illuminaire_action(crate::illuminaire::Action {
            set_fitting_unit: Some((fid, 0.001)),
            ..Default::default()
        });
        assert!(
            (app.light.library.get(fid).expect("there").symbol_unit_m - 0.001).abs() < 1e-12,
            "the library entry was not corrected",
        );
        assert!(
            (length(&app) - 2.0).abs() < 1e-6,
            "the block already on the plan is still {} m — the correction did not reach it",
            length(&app),
        );
        assert!(app.index_dirty, "the rescaled block was not re-indexed");
    }

    /// …and the instances are left exactly where they were. Rebuilding the DEFINITION must not
    /// disturb the references: same count, same insertion points, same ids.
    #[test]
    fn correcting_the_unit_does_not_move_anything() {
        let (mut app, _) = placed(3);
        let fid = app.light.library.fittings[0].id;
        let before: Vec<(u32, f64, f64)> = app
            .doc
            .dobjects
            .iter()
            .filter_map(|d| match &d.geom {
                cad_kernel::Geom::BlockRef(b) => Some((b.block, b.insert.x, b.insert.y)),
                _ => None,
            })
            .collect();
        app.apply_illuminaire_action(crate::illuminaire::Action {
            set_fitting_unit: Some((fid, 1.0)),
            ..Default::default()
        });
        let after: Vec<(u32, f64, f64)> = app
            .doc
            .dobjects
            .iter()
            .filter_map(|d| match &d.geom {
                cad_kernel::Geom::BlockRef(b) => Some((b.block, b.insert.x, b.insert.y)),
                _ => None,
            })
            .collect();
        assert_eq!(before, after, "rebuilding the definition moved the instances");
        assert_eq!(app.light.luminaires.len(), 3, "a unit change cost a fixture");
    }

    /// A FITTING NEVER PLACED IN THIS DRAWING costs no undo step — an Undo the user has to press
    /// twice is its own bug.
    #[test]
    fn correcting_an_unplaced_fittings_unit_touches_no_drawing() {
        // A drawing that already HAS blocks, so a lookup that fell back to an index instead of
        // reporting "not here" would rewrite one of them. An empty block table hides that.
        let (mut app, _) = placed(1);
        let existing: Vec<usize> =
            app.doc.blocks.blocks.iter().map(|b| b.dobjects.len()).collect();
        assert!(!existing.is_empty(), "fixture: the drawing has a block table");

        let fid = app.light.library.add(crate::illuminaire::Fitting {
            name: "NEVER PLACED".into(),
            id: 0,
            symbol: vec![crate::illuminaire::SymbolGeom {
                geom: cad_kernel::Geom::Line(cad_kernel::Line {
                    a: Vec2::new(0.0, 0.0),
                    b: Vec2::new(9.0, 0.0),
                }),
                aci: None,
            }],
            symbol_unit_m: 0.0254,
            ldt_path: String::new(),
            profile: String::new(),
            model_path: String::new(),
        });
        let undo = app.undo_stack.len();
        app.apply_illuminaire_action(crate::illuminaire::Action {
            set_fitting_unit: Some((fid, 0.001)),
            ..Default::default()
        });
        assert!(
            (app.light.library.get(fid).expect("there").symbol_unit_m - 0.001).abs() < 1e-12,
            "the library entry was not corrected",
        );
        assert_eq!(app.undo_stack.len(), undo, "an undo step was pushed for an edit never made");
        let after: Vec<usize> =
            app.doc.blocks.blocks.iter().map(|b| b.dobjects.len()).collect();
        assert_eq!(
            existing, after,
            "correcting a fitting this drawing has never seen rewrote another block's geometry",
        );
    }
}

/// SIMLUX FIXTURES ARE ON THE UNDO STACK.
///
/// They were not, and it showed in two directions. A delete was final: Ctrl+Z after erasing a
/// marker stepped straight past it to an older drawing edit and took the drawing with it. And a
/// placement, which puts a block on the plan and a light at the same point, could only ever be
/// half undone — the symbol came back and the marker did not.
///
/// The rule these all check is that a step carries exactly what its edit changed, and that one
/// act is one step.
#[cfg(test)]
mod fixtures_are_undoable {
    use super::*;

    /// A millimetre plan with a fitting in the library, ready to place.
    fn armed() -> (CadApp, u32) {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 0.001;
        let mut src = cad_kernel::Document::default();
        src.blocks.add(cad_kernel::Block {
            name: "OCULUS".into(),
            base: Vec2::new(0.0, 0.0),
            dobjects: vec![cad_kernel::DObject::new(cad_kernel::Geom::Circle(
                cad_kernel::Circle { center: Vec2::new(0.0, 0.0), radius: 47.5 },
            ))],
            smart: false,
            params: Vec::new(),
            cut_edges: Vec::new(),
        });
        let rows = crate::illuminaire::symbols_from(&src);
        let fid = app.light.library.add(crate::illuminaire::Fitting {
            name: rows[0].name.clone(),
            id: 0,
            symbol: rows[0].symbol.clone(),
            symbol_unit_m: 0.001,
            ldt_path: String::new(),
            profile: crate::light::BUILTIN.into(),
            model_path: String::new(),
        });
        app.light.place_fitting = Some(fid);
        (app, fid)
    }

    fn blocks(app: &CadApp) -> usize {
        app.doc
            .dobjects
            .iter()
            .filter(|d| matches!(d.geom, cad_kernel::Geom::BlockRef(_)))
            .count()
    }

    /// PLACING IS ONE ACT AND ONE UNDO — both halves, together.
    #[test]
    fn undoing_a_placement_takes_back_the_block_and_the_light() {
        let (mut app, _) = armed();
        app.place_illuminaire_at(1.0, 2.0);
        app.place_illuminaire_at(3.0, 2.0);
        assert_eq!(app.light.luminaires.len(), 2);
        assert_eq!(blocks(&app), 2);

        app.do_undo();
        assert_eq!(app.light.luminaires.len(), 1, "the marker stayed after an undo");
        assert_eq!(blocks(&app), 1, "the symbol stayed after an undo");

        app.do_undo();
        assert!(app.light.luminaires.is_empty(), "the first marker stayed");
        assert_eq!(blocks(&app), 0, "the first symbol stayed");
    }

    /// …AND REDO PUTS BOTH BACK.
    #[test]
    fn redoing_a_placement_restores_both_halves() {
        let (mut app, _) = armed();
        app.place_illuminaire_at(1.0, 2.0);
        app.do_undo();
        assert!(app.light.luminaires.is_empty());

        app.do_redo();
        assert_eq!(app.light.luminaires.len(), 1, "redo did not bring the marker back");
        assert_eq!(blocks(&app), 1, "redo did not bring the symbol back");
        assert_eq!(
            app.light.luminaires[0].from_block,
            Some(0),
            "the restored light is not tied to its restored symbol",
        );
    }

    /// DELETING IS UNDOABLE, both halves together. This is the asymmetry that was reported: undo
    /// brought the symbols back and not the markers.
    #[test]
    fn undoing_a_delete_brings_the_marker_back_with_its_symbol() {
        let (mut app, _) = armed();
        app.place_illuminaire_at(1.0, 2.0);
        let id = app.light.luminaires[0].id;

        app.delete_fixtures(&[id]);
        assert!(app.light.luminaires.is_empty());
        assert_eq!(blocks(&app), 0);

        app.do_undo();
        assert_eq!(app.light.luminaires.len(), 1, "the marker did not come back");
        assert_eq!(blocks(&app), 1, "the symbol did not come back");
        assert_eq!(app.light.luminaires[0].id, id, "a different fixture came back");
    }

    /// A FIXTURE-ONLY DELETE DOES NOT REACH PAST ITSELF INTO THE DRAWING.
    ///
    /// The sharpest version of the old bug: a hand-placed point has no symbol, so deleting it used
    /// to push no step at all — and the next Ctrl+Z undid whatever drawing edit came before,
    /// erasing geometry the user never touched.
    #[test]
    fn undoing_a_bare_point_delete_leaves_the_drawing_alone() {
        let mut app = CadApp::default();
        app.doc.push(cad_kernel::DObject::new(cad_kernel::Geom::Line(cad_kernel::Line {
            a: Vec2::new(0.0, 0.0),
            b: Vec2::new(1.0, 0.0),
        })));
        app.snapshot_doc();
        app.doc.push(cad_kernel::DObject::new(cad_kernel::Geom::Line(cad_kernel::Line {
            a: Vec2::new(0.0, 1.0),
            b: Vec2::new(1.0, 1.0),
        })));
        let drawn = app.doc.dobjects.len();

        let id = app.place_fixture_point(5.0, 5.0);
        app.delete_fixtures(&[id]);
        assert!(app.light.luminaires.is_empty());

        app.do_undo();
        assert_eq!(app.light.luminaires.len(), 1, "the point did not come back");
        assert_eq!(
            app.doc.dobjects.len(),
            drawn,
            "undoing a fixture delete erased geometry the user never touched",
        );
    }


    /// A DRAGGED FIXTURE TAKES ITS SYMBOL WITH IT.
    ///
    /// Reported as: dragging a fixture moves the light but not its symbol. It did — `from_block`
    /// names the block DEFINITION, shared by every instance of a fitting, so the drawing had no way
    /// to know which of fifty identical downlights belonged to the marker under the pointer. The
    /// pairing is by POSITION, and the one moment the two are certainly together is the press.
    ///
    /// A plan whose symbols say one thing and whose calculation says another is worse than either
    /// alone: the drawing is what gets issued, and the lux figures are what it is signed off on.
    fn placed(app: &mut CadApp, at: (f32, f32)) -> u32 {
        let fid = app.light.library.add(crate::illuminaire::Fitting {
            name: "VEGA".into(),
            id: 0,
            symbol: vec![crate::illuminaire::SymbolGeom {
                geom: cad_kernel::Geom::Circle(cad_kernel::Circle {
                    center: Vec2::new(0.0, 0.0),
                    radius: 0.2,
                }),
                aci: None,
            }],
            symbol_unit_m: 1.0,
            ldt_path: String::new(),
            profile: crate::light::BUILTIN.into(),
            model_path: String::new(),
        });
        app.light.place_fitting = Some(fid);
        assert!(app.place_illuminaire_at(at.0, at.1), "the placement was refused");
        app.light.luminaires.last().expect("a fixture").id
    }

    /// Every block insertion point on the drawing, in drawing units.
    fn inserts(app: &CadApp) -> Vec<(f64, f64)> {
        app.doc
            .dobjects
            .iter()
            .filter_map(|d| match &d.geom {
                cad_kernel::Geom::BlockRef(b) => Some((b.insert.x, b.insert.y)),
                _ => None,
            })
            .collect()
    }

    #[test]
    fn dragging_a_fixture_moves_its_symbol_too() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0;
        let id = placed(&mut app, (1.0, 1.0));
        let before = inserts(&app);
        assert_eq!(before.len(), 1, "expected one symbol on the drawing");

        app.begin_fixture_drag(id, (1.0, 1.0));
        app.light.drag_to((4.0, 2.5));
        app.drag_fixture_symbols();
        app.light.end_drag();

        let l = app.light.luminaires.iter().find(|l| l.id == id).expect("the fixture");
        assert!((l.position.x - 4.0).abs() < 1e-5 && (l.position.y - 2.5).abs() < 1e-5);
        let after = inserts(&app);
        assert_eq!(after.len(), 1, "the drag added or removed a symbol");
        let moved = (after[0].0 - before[0].0, after[0].1 - before[0].1);
        assert!(
            (moved.0 - 3.0).abs() < 1e-6 && (moved.1 - 1.5).abs() < 1e-6,
            "the light moved by (3.0, 1.5) and its symbol by ({:.3}, {:.3})",
            moved.0,
            moved.1,
        );
    }

    /// AND IT IS STILL ITS SYMBOL AFTERWARDS.
    ///
    /// The link is by position, so a drag that left the block behind did not merely look wrong —
    /// it BROKE the link, and deleting the fixture then left an orphaned symbol on the plan. That
    /// was the second half of an earlier report ("when i delete them from fitting it doesnt delete
    /// the markers"), and it is only truly fixed once the two travel together.
    #[test]
    fn a_dragged_fixture_can_still_be_deleted_cleanly() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0;
        let id = placed(&mut app, (1.0, 1.0));

        app.begin_fixture_drag(id, (1.0, 1.0));
        app.light.drag_to((6.0, 3.0));
        app.drag_fixture_symbols();
        app.light.end_drag();

        app.delete_fixtures(&[id]);
        assert!(app.light.luminaires.is_empty(), "the fixture was not deleted");
        assert!(
            inserts(&app).is_empty(),
            "the symbol was left on the drawing after its fixture went",
        );
    }

    /// TWO FIXTURES OF THE SAME FITTING KEEP THEIR OWN SYMBOLS.
    ///
    /// The case a naive "find a block of this definition nearby" gets wrong: fifty downlights share
    /// one definition, so a claim has to be one-to-one or dragging one marker would pick up its
    /// neighbour's symbol and leave its own where it was.
    #[test]
    fn dragging_one_of_two_leaves_the_other_alone() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0;
        let a = placed(&mut app, (1.0, 1.0));
        // The SAME fitting again, so both symbols are instances of one definition.
        let fid = app.light.library.fittings.first().map(|f| f.id).expect("the fitting");
        app.light.place_fitting = Some(fid);
        assert!(app.place_illuminaire_at(2.0, 1.0));
        assert_eq!(inserts(&app).len(), 2);

        app.light.select(a, false);
        app.begin_fixture_drag(a, (1.0, 1.0));
        app.light.drag_to((1.0, 5.0));
        app.drag_fixture_symbols();
        app.light.end_drag();

        let mut got = inserts(&app);
        got.sort_by(|p, q| p.1.partial_cmp(&q.1).expect("finite"));
        assert!(
            (got[0].0 - 2.0).abs() < 1e-6 && (got[0].1 - 1.0).abs() < 1e-6,
            "the fixture that was not dragged had its symbol moved to {:?}",
            got[0],
        );
        assert!(
            (got[1].1 - 5.0).abs() < 1e-6,
            "the dragged fixture's symbol is at {:?}",
            got[1],
        );
    }

    /// ROTATING A SYMBOL ON THE PLAN ROTATES THE LIGHT BEHIND IT.
    ///
    /// Asked as: *"does rotating the lights in the 2d actually rotate a light in simlux as well?
    /// verify that too"*. It did not. `apply_rotate` edits `doc.dobjects` and nothing else — so did
    /// `apply_move`, `apply_scale` and `apply_mirror` — and the luminaire kept the aiming it was
    /// placed with while its symbol turned on the drawing.
    ///
    /// That is not only a wrong calculation, it is an INVISIBLY wrong one: the fixture had not
    /// changed, so the fingerprint had not changed, so the result did not even go out of date.
    /// "i rotated a light and the result was still valid" — the staleness check was working, there
    /// was simply nothing for it to notice.
    #[test]
    fn rotating_a_symbol_rotates_its_light() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0;
        let id = placed(&mut app, (1.0, 1.0));
        assert!(app.light.symbol_of.contains_key(&id), "the fixture was not linked to its symbol");
        assert_eq!(app.light.luminaires[0].rotation_deg, 0.0);

        // Select the symbol on the drawing and turn it a quarter turn about its own insert.
        let i = app
            .doc
            .dobjects
            .iter()
            .position(|d| matches!(d.geom, cad_kernel::Geom::BlockRef(_)))
            .expect("a symbol");
        app.selection = vec![i];
        app.apply_rotate(Vec2::new(1.0, 1.0), std::f64::consts::FRAC_PI_2);
        app.tick_symbol_sync();

        let l = &app.light.luminaires[0];
        assert!(
            (l.rotation_deg - 90.0).abs() < 1e-3,
            "the symbol was turned 90° and the light reads {}°",
            l.rotation_deg,
        );
    }

    /// MOVING ONE MOVES THE OTHER, and about a pivot the light orbits with its symbol.
    #[test]
    fn a_symbol_moved_on_the_plan_takes_its_light_with_it() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0;
        let id = placed(&mut app, (1.0, 1.0));
        let i = app
            .doc
            .dobjects
            .iter()
            .position(|d| matches!(d.geom, cad_kernel::Geom::BlockRef(_)))
            .expect("a symbol");
        app.selection = vec![i];

        // A quarter turn about the ORIGIN: (1, 1) goes to (-1, 1).
        app.apply_rotate(Vec2::new(0.0, 0.0), std::f64::consts::FRAC_PI_2);
        app.tick_symbol_sync();
        let _ = id;
        let l = &app.light.luminaires[0];
        assert!(
            (l.position.x + 1.0).abs() < 1e-4 && (l.position.y - 1.0).abs() < 1e-4,
            "the light is at ({}, {}) after its symbol orbited to (-1, 1)",
            l.position.x,
            l.position.y,
        );
    }

    /// AND THE RESULT GOES OUT OF DATE FOR IT.
    ///
    /// The whole point of the report: "the result should be invalidated even if the position of the
    /// light is changed. i rotated a light and the result was still valid."
    #[test]
    fn a_symbol_rotated_on_the_plan_puts_the_result_out_of_date() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0;
        placed(&mut app, (1.0, 1.0));
        // Pretend a calculation just ran over this scene.
        let plan = app.plan_doc().clone();
        let fp = app.light.current_fingerprint(&plan, Some(&app.factory)).expect("a fingerprint");
        app.light.results_fingerprint = Some(fp);
        app.light.results_stale = false;
        app.light.stale_checked = None;

        let i = app
            .doc
            .dobjects
            .iter()
            .position(|d| matches!(d.geom, cad_kernel::Geom::BlockRef(_)))
            .expect("a symbol");
        app.selection = vec![i];
        app.apply_rotate(Vec2::new(1.0, 1.0), std::f64::consts::FRAC_PI_2);
        app.tick_symbol_sync();

        app.light.stale_checked = None;
        let plan = app.plan_doc().clone();
        app.light.refresh_staleness(&plan, Some(&app.factory));
        assert!(
            app.light.results_stale,
            "a fitting was turned 90° on the plan and the answer still claimed to be current",
        );
    }

    /// A SYMBOL THAT IS NOT THERE ANY MORE LEAVES ITS LIGHT ALONE.
    ///
    /// Somebody may erase a block from the drawing directly. Moving the light to the origin — or
    /// deleting it — because a handle stopped resolving would be a far larger decision than a
    /// bookkeeping pass is entitled to make, and it would be taken silently.
    #[test]
    fn a_light_whose_symbol_was_erased_stays_put() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0;
        placed(&mut app, (3.0, 4.0));
        app.doc.dobjects.retain(|d| !matches!(d.geom, cad_kernel::Geom::BlockRef(_)));
        app.edit_seq += 1;
        app.tick_symbol_sync();

        let l = &app.light.luminaires[0];
        assert!(
            (l.position.x - 3.0).abs() < 1e-4 && (l.position.y - 4.0).abs() < 1e-4,
            "the light moved to ({}, {}) because its symbol was erased",
            l.position.x,
            l.position.y,
        );
    }

    /// THE LINK SURVIVES A SAVE AND A REOPEN.
    ///
    /// Without it a reopened project falls back to matching by position, and the first rotate
    /// after that separates the two again — which is the bug, one session later.
    #[test]
    fn the_link_between_a_light_and_its_symbol_is_saved() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0;
        let id = placed(&mut app, (1.0, 1.0));
        let handle = *app.light.symbol_of.get(&id).expect("a link");

        let cfg = app.light.to_config(&app.doc);
        assert_eq!(cfg.symbol_of.get(&id), Some(&handle), "the link is not in the sidecar");

        let mut fresh = crate::light::LightState::new();
        fresh.apply_config(cfg, &app.doc);
        assert_eq!(fresh.symbol_of.get(&id), Some(&handle), "the link did not come back");
    }

    /// THE AIM TOOL IS TWO CLICKS: a fitting, then the point it should light.
    ///
    /// Asked for as "when aim i selected the user can select a light and then click on a point
    /// where they would like to point it".
    #[test]
    fn aiming_takes_a_fitting_then_a_target() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0;
        app.light.plane_height = 0.8;
        let id = placed(&mut app, (1.0, 1.0));
        app.light.luminaires[0].position.z = 3.0;
        app.light.aim_mode = true;

        // First click: on the marker.
        app.aim_click(1.0, 1.0, 0.5);
        assert_eq!(app.light.aim_pick, Some(id), "the first click did not pick the fitting");
        assert_eq!(app.light.selected, vec![id], "and it should be selected while being aimed");

        // Second click: three metres away.
        app.aim_click(4.0, 1.0, 0.5);
        assert_eq!(app.light.aim_pick, None, "the tool did not come back for the next fitting");
        let l = &app.light.luminaires[0];
        assert!(
            (l.position.x - 1.0).abs() < 1e-5 && (l.position.z - 3.0).abs() < 1e-5,
            "the fitting moved to ({}, {}, {})",
            l.position.x,
            l.position.y,
            l.position.z,
        );
        // 3 m across, 2.2 m down to the working plane: 53.7° from vertical, toward +x.
        assert!((l.tilt_deg - 53.75).abs() < 0.2, "tilt is {}", l.tilt_deg);
        assert!(l.rotation_deg.abs() < 1e-3, "azimuth is {}", l.rotation_deg);
        assert!(app.light.aim_mode, "the tool disarmed itself after one fitting");
    }

    /// A FIRST CLICK ON EMPTY PLAN PICKS NOTHING, and says so rather than aiming whatever was
    /// selected earlier.
    #[test]
    fn aiming_needs_a_fitting_under_the_first_click() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0;
        let id = placed(&mut app, (1.0, 1.0));
        app.light.select(id, false);
        app.light.aim_mode = true;

        app.aim_click(20.0, 20.0, 0.5);
        assert_eq!(app.light.aim_pick, None, "it picked a fitting that was not there");
        assert!(app.light.last_msg.contains("No fitting"), "{:?}", app.light.last_msg);
        assert_eq!(app.light.luminaires[0].tilt_deg, 0.0, "a fitting was aimed by an empty click");
    }

    /// AND AIMING PUTS THE RESULT OUT OF DATE.
    ///
    /// Aiming changes where the light goes, so it changes the answer — which is the whole reason
    /// for adding tilt rather than only turning the fitting on its axis.
    #[test]
    fn aiming_a_fitting_puts_the_result_out_of_date() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0;
        app.light.plane_height = 0.8;
        placed(&mut app, (1.0, 1.0));
        app.light.luminaires[0].position.z = 3.0;

        let plan = app.plan_doc().clone();
        let fp = app.light.current_fingerprint(&plan, Some(&app.factory)).expect("a fingerprint");
        app.light.results_fingerprint = Some(fp);
        app.light.results_stale = false;

        app.light.aim_mode = true;
        app.aim_click(1.0, 1.0, 0.5);
        app.aim_click(5.0, 2.0, 0.5);

        app.light.stale_checked = None;
        let plan = app.plan_doc().clone();
        app.light.refresh_staleness(&plan, Some(&app.factory));
        assert!(
            app.light.results_stale,
            "a fitting was aimed somewhere else and the answer still claimed to be current",
        );
    }

    /// THE TILT SURVIVES A SAVE AND A REOPEN. An aim that came back pointing at the floor would be
    /// a silent loss of the whole scheme's aiming.
    #[test]
    fn an_aimed_fitting_is_saved_aimed() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0;
        placed(&mut app, (1.0, 1.0));
        app.light.luminaires[0].position.z = 3.0;
        app.light.luminaires[0].tilt_deg = 27.5;
        app.light.luminaires[0].rotation_deg = 61.0;

        let cfg = app.light.to_config(&app.doc);
        let mut fresh = crate::light::LightState::new();
        fresh.apply_config(cfg, &app.doc);
        let l = &fresh.luminaires[0];
        assert!((l.tilt_deg - 27.5).abs() < 1e-4, "the tilt came back as {}", l.tilt_deg);
        assert!((l.rotation_deg - 61.0).abs() < 1e-4, "the azimuth came back as {}", l.rotation_deg);
    }

    /// TWO FIXTURES ON THE SAME SPOT TAKE TWO DIFFERENT SYMBOLS.
    ///
    /// The case that makes the claim have to be ONE-TO-ONE, and the one a single-fixture drag
    /// cannot show: with several fixtures moving together and two of them at the same point, a
    /// claim that simply finds "a block of this definition here" hands both fixtures the SAME
    /// instance. One symbol is then moved twice and the other stranded on the plan — and since the
    /// link is by position, the stranded one can no longer be found or deleted at all.
    ///
    /// Duplicating a fitting in place is how two end up on one spot, and it is not rare.
    #[test]
    fn two_fixtures_on_one_spot_do_not_fight_over_a_symbol() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0;
        let a = placed(&mut app, (1.0, 1.0));
        let fid = app.light.library.fittings.first().map(|f| f.id).expect("the fitting");
        app.light.place_fitting = Some(fid);
        assert!(app.place_illuminaire_at(1.0, 1.0), "the second placement was refused");
        let b = app.light.luminaires.last().expect("a second fixture").id;
        assert_ne!(a, b);
        assert_eq!(inserts(&app).len(), 2, "expected two symbols stacked on one point");

        // Both selected and dragged together — what a rubber band or a shift-click gives.
        app.light.select(a, false);
        app.light.select(b, true);
        app.begin_fixture_drag(a, (1.0, 1.0));
        app.light.drag_to((7.0, 4.0));
        app.drag_fixture_symbols();
        app.light.end_drag();

        let got = inserts(&app);
        assert_eq!(got.len(), 2, "a symbol was created or destroyed");
        for (i, p) in got.iter().enumerate() {
            assert!(
                (p.0 - 7.0).abs() < 1e-6 && (p.1 - 4.0).abs() < 1e-6,
                "symbol {i} was left at {p:?} while its fixture moved to (7, 4) — two fixtures \
                 claimed the same block and one symbol was stranded",
            );
        }
    }

    /// A DRAG IS ONE UNDO, AND IT TAKES BACK BOTH HALVES.
    ///
    /// The marker and the symbol move together, so they have to come back together. An Undo that
    /// restored one of them would leave a state the user never made — which is worse than the bug
    /// it came from, because now the two disagree and nothing did it on purpose.
    #[test]
    fn undoing_a_drag_puts_the_symbol_back_as_well() {
        let mut app = CadApp::default();
        app.doc.units.metres_per_unit = 1.0;
        let id = placed(&mut app, (1.0, 1.0));
        let before = inserts(&app);

        app.begin_fixture_drag(id, (1.0, 1.0));
        // The app drives this either side of `drag_to`, which is where the one undo step is taken.
        let was = app.light.drag.as_ref().is_some_and(|d| d.moved);
        app.light.drag_to((4.0, 1.0));
        let now = app.light.drag.as_ref().is_some_and(|d| d.moved);
        if now && !was {
            app.snapshot_doc_and_lights();
        }
        app.drag_fixture_symbols();
        app.light.end_drag();
        assert_ne!(inserts(&app), before, "the symbol never moved in the first place");

        app.do_undo();
        let l = &app.light.luminaires[0];
        assert!(
            (l.position.x - 1.0).abs() < 1e-5,
            "the fixture is at {} after an undo",
            l.position.x,
        );
        assert_eq!(inserts(&app), before, "the symbol did not come back with its fixture");

        // ONE step, not two: a second Undo must reach past the drag, not undo half of it.
        app.do_undo();
        assert!(
            app.light.luminaires.is_empty() || inserts(&app).len() == before.len(),
            "the drag was recorded as two steps, so an Undo left the drawing and the lights apart",
        );
    }
    /// A DRAG IS ONE UNDO, and the fixture goes back where it was.
    #[test]
    fn undoing_a_drag_puts_the_fixture_back() {
        let mut app = CadApp::default();
        let id = app.place_fixture_point(1.0, 1.0);
        app.light.select(id, false);

        app.light.begin_drag(id, (1.0, 1.0));
        app.light.drag_to((4.0, 1.0));
        assert!(app.light.end_drag(), "the drag reported no movement");
        app.commit_light_undo(); // what the frame-end drain does

        assert!((app.light.luminaires[0].position.x - 4.0).abs() < 1e-5);

        app.do_undo();
        assert!(
            (app.light.luminaires[0].position.x - 1.0).abs() < 1e-5,
            "the fixture is at {} after an undo",
            app.light.luminaires[0].position.x,
        );
    }

    /// A PRESS THAT NEVER MOVED IS A SELECTION and must not cost an Undo press.
    #[test]
    fn clicking_a_marker_costs_no_undo_step() {
        let mut app = CadApp::default();
        let id = app.place_fixture_point(1.0, 1.0);
        let depth = app.undo_stack.len();

        app.light.begin_drag(id, (1.0, 1.0));
        // A REAL STATIONARY PRESS STILL DRAGS. The pointer reports its position every frame the
        // button is down, so `drag_to` runs with a zero delta — which is exactly where staging
        // must decline to happen.
        for _ in 0..5 {
            app.light.drag_to((1.0, 1.0));
        }
        assert!(!app.light.end_drag(), "a stationary press reported a move");
        app.commit_light_undo();
        assert_eq!(app.undo_stack.len(), depth, "selecting a marker pushed an undo step");
    }

    /// UNDOING A DRAWING EDIT LEAVES THE FIXTURES ALONE.
    ///
    /// A step carries only what its edit changed. Were every drawing step to carry a copy of the
    /// fixtures, undoing an unrelated line would silently rewind the lighting with it — which is
    /// the failure mode of the obvious implementation and the reason for separate variants.
    #[test]
    fn undoing_a_line_does_not_disturb_the_lighting() {
        let mut app = CadApp::default();
        app.place_fixture_point(1.0, 1.0);
        app.place_fixture_point(2.0, 1.0);

        // `CadApp::default()` opens with demo geometry, so count rather than assume.
        let before_line = app.doc.dobjects.len();
        app.snapshot_doc();
        app.doc.push(cad_kernel::DObject::new(cad_kernel::Geom::Line(cad_kernel::Line {
            a: Vec2::new(0.0, 0.0),
            b: Vec2::new(1.0, 0.0),
        })));

        app.place_fixture_point(3.0, 1.0);
        assert_eq!(app.light.luminaires.len(), 3);

        // Undo the third point, then the line.
        app.do_undo();
        assert_eq!(app.light.luminaires.len(), 2);
        app.do_undo();
        assert_eq!(app.doc.dobjects.len(), before_line, "the line was not undone");
        assert_eq!(
            app.light.luminaires.len(),
            2,
            "undoing a line rewound the lighting to {} fixtures",
            app.light.luminaires.len(),
        );
    }

    /// IDS ARE NEVER REWOUND. `next_id` is deliberately not in a snapshot: a drawing that still
    /// names a deleted fixture must resolve to nothing rather than to whatever took its place, and
    /// an undo that rewound the counter would hand the next placement a live id.
    #[test]
    fn an_undone_placement_does_not_free_its_id() {
        let mut app = CadApp::default();
        let a = app.place_fixture_point(1.0, 1.0);
        app.do_undo();
        let b = app.place_fixture_point(2.0, 1.0);
        assert_ne!(a, b, "the undone fixture's id was handed out again");
    }

    /// The same rule at the point it would actually be broken: `next_id` is not in a snapshot, so
    /// restoring one must leave the counter alone. Putting it in is the obvious thing to do —
    /// alongside the fixtures, in the same struct — and the damage is silent, because the collision
    /// only shows up in a drawing saved before the undo and reopened after it.
    #[test]
    fn restoring_fixtures_does_not_rewind_the_id_counter() {
        let mut app = CadApp::default();
        let a = app.place_fixture_point(1.0, 1.0);
        let b = app.place_fixture_point(2.0, 1.0);
        let counter = app.light.next_id;

        app.restore_lights(LightSnap { luminaires: Vec::new() });
        assert_eq!(app.light.next_id, counter, "restoring rewound the id counter");

        let c = app.place_fixture_point(3.0, 1.0);
        assert!(c != a && c != b, "id {c} collides with one already handed out");
    }

    /// A RESTORED LAYOUT DOES NOT KEEP THE OLD RESULT.
    ///
    /// The lux figures were computed from a layout that no longer holds. Recalculating on every
    /// undo would cost minutes on a real building; leaving them on screen is worse than both,
    /// because a figure under a layout it was not computed from is one someone will issue.
    #[test]
    fn undoing_a_fixture_edit_drops_the_stale_result() {
        let mut app = CadApp::default();
        app.place_fixture_point(1.0, 1.0);
        app.light.grid = Some(cad_light::LuxGrid::from_values(1, 1, vec![250.0]));
        app.place_fixture_point(2.0, 1.0);
        app.do_undo();
        assert!(app.light.grid.is_none(), "a stale lux grid survived the undo");
    }
}

/// THE REPORT BUTTON OPENS A DIALOG. It used to write an HTML file to the Desktop and tell you
/// afterwards, which is neither a choice nor a place anyone keeps a project.
#[cfg(test)]
mod the_report_is_asked_about_before_it_is_written {
    use super::*;

    fn calculated() -> CadApp {
        let mut app = CadApp::default();
        // THE SAVED SETTINGS ARE NOT READ IN A TEST.
        //
        // The dialog loads `~/.config/rust_cad/report.json` on the first frame it opens, which is
        // correct behaviour and made every test in here depend on whatever sat in a real person's
        // home directory. It bit exactly as you would expect: `every_control_is_on_screen` looked
        // for the "Save PDF" button and found "Save HTML", because a preferences file on this
        // machine happened to say HTML. A suite whose result depends on a file no test wrote is a
        // suite that fails for one developer and passes for another, over nothing.
        //
        // Set here rather than in `CadApp::default`, because reading them is real behaviour and
        // should keep happening everywhere except where it is deliberately being kept out.
        app.report_prefs_loaded = true;
        app.light.grid = Some(cad_light::LuxGrid {
            cols: 4,
            rows: 4,
            values: (0..16).map(|i| 100.0 + i as f64 * 10.0).collect(),
            min: 100.0,
            max: 250.0,
            avg: 175.0,
            maintenance: 0.8,
            direct: Vec::new(),
            indirect: Vec::new(),
        });
        app.light.plane = Some(cad_light::CalcPlane {
            origin: cad_light::Vertex::new(0.0, 0.0, 0.8),
            width: 4.0,
            depth: 4.0,
            cols: 4,
            rows: 4,
        });
        // A calculation produces a LIST of room results, and the report reads that list — the
        // loose fields are what the single-room PANEL shows.
        app.light.rooms = vec![crate::light::RoomResult {
            name: "Test room".into(),
            poly: Vec::new(),
            plane: app.light.plane.clone().expect("plane"),
            grid: app.light.grid.clone().expect("grid"),
            mask: Vec::new(),
            plane_en: app.light.plane.clone().expect("plane"),
            grid_en: app.light.grid.clone().expect("grid"),
            mask_en: Vec::new(),
            cylindrical_avg: None,
            installation: None,
            fixtures: Vec::new(),
            grid_note: None,
        }];
        app
    }

    fn frame(app: &mut CadApp) -> usize {
        let ctx = egui::Context::default();
        let input = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::pos2(0.0, 0.0),
                egui::vec2(1400.0, 900.0),
            )),
            ..Default::default()
        };
        let out = ctx.run(input, |ctx| app.render_report_dialog(ctx));
        out.shapes.len()
    }

    /// NOTHING IS WRITTEN UNTIL IT IS ASKED FOR, and the button opens the dialog instead.
    #[test]
    fn pressing_report_opens_the_dialog_and_writes_nothing() {
        let mut app = calculated();
        assert!(!app.report_open);
        app.export_light_report();
        assert!(app.report_open, "the dialog did not open");
        // No output path has been chosen, so there is nothing it could have written to.
        assert!(app.report_opts.out_dir.is_empty() || app.current_file.is_some());
    }

    /// WITH NOTHING CALCULATED IT SAYS SO rather than opening a dialog over an empty document.
    #[test]
    fn without_a_calculation_the_dialog_stays_shut() {
        let mut app = CadApp::default();
        app.export_light_report();
        assert!(!app.report_open, "the dialog opened with nothing to report");
        assert!(app.light.last_msg.contains("Calculate"), "and it must say why");
    }


    /// Every piece of text the dialog actually painted.
    ///
    /// Reading the LABELS off a rendered frame, rather than searching the binary for the literals:
    /// an optimised build is free to merge, split and re-order string constants, so "the bytes are
    /// in the file" answers a question nobody asked. What matters is whether the control is on
    /// screen.
    fn dialog_text(app: &mut CadApp) -> Vec<String> {
        let ctx = egui::Context::default();
        let input = || egui::RawInput {
            // Big enough that nothing is scrolled out of the frame and culled.
            screen_rect: Some(egui::Rect::from_min_size(
                egui::pos2(0.0, 0.0),
                egui::vec2(1800.0, 2400.0),
            )),
            ..Default::default()
        };
        // SEVERAL FRAMES, and the options column SCROLLED THROUGH.
        //
        // egui lays a window out before it paints it — frame one comes back as two dozen `Noop`
        // shapes and nothing else, which is what an earlier test counted and passed on. And the
        // options are taller than their panel, so anything below the fold is culled and never
        // painted at all: reading one frame answers "what is visible", not "what is there".
        let mut all: Vec<String> = Vec::new();
        let mut collect = |out: egui::FullOutput, all: &mut Vec<String>| {
            fn walk(s: &egui::Shape, into: &mut Vec<String>) {
                match s {
                    egui::Shape::Text(t) => into.push(t.galley.text().to_string()),
                    egui::Shape::Vec(v) => v.iter().for_each(|s| walk(s, into)),
                    _ => {}
                }
            }
            for cs in &out.shapes {
                walk(&cs.shape, all);
            }
        };
        for _ in 0..3 {
            let out = ctx.run(input(), |ctx| app.render_report_dialog(ctx));
            collect(out, &mut all);
        }
        // Then wheel the options column down, a screenful at a time, gathering as we go.
        for _ in 0..12 {
            let mut ri = input();
            ri.events.push(egui::Event::PointerMoved(egui::pos2(140.0, 400.0)));
            ri.events.push(egui::Event::MouseWheel {
                unit: egui::MouseWheelUnit::Point,
                delta: egui::vec2(0.0, -180.0),
                modifiers: Default::default(),
            });
            let out = ctx.run(ri, |ctx| app.render_report_dialog(ctx));
            collect(out, &mut all);
        }
        all.sort();
        all.dedup();
        return all;
        #[allow(unreachable_code)]
        let out = ctx.run(input(), |ctx| app.render_report_dialog(ctx));
        fn walk(s: &egui::Shape, into: &mut Vec<String>) {
            match s {
                egui::Shape::Text(t) => into.push(t.galley.text().to_string()),
                egui::Shape::Vec(v) => v.iter().for_each(|s| walk(s, into)),
                _ => {}
            }
        }
        let mut v = Vec::new();
        for cs in &out.shapes {
            walk(&cs.shape, &mut v);
        }
        v
    }

    /// THE DIALOG SHOWS EVERY CONTROL IT IS SUPPOSED TO.
    ///
    /// "is everything wired in?" — asked after several rounds of additions, and the honest way to
    /// answer is to render the thing and read it back rather than to remember.
    #[test]
    fn every_control_is_on_screen() {
        let mut app = calculated();
        app.export_light_report();
        let t = dialog_text(&mut app);
        let has = |needle: &str| t.iter().any(|s| s.contains(needle));

        for want in [
            "Format", "PDF", "HTML", "A4", "Letter",
            "Cover", "Cover page", "Project", "Line 2", "Image",
            "Header & footer", "Page numbers", "Header logo", "Footer logo", "Add logo",
            "Logos fit a",
            "False-colour scale", "Pin top", "Bands",
            "Sections",
            "Renders", "Add", "Folder", "choose a folder", "Preview", "Save PDF",
        ] {
            assert!(has(want), "the dialog never painted {want:?}\npainted: {t:?}");
        }
    }

    /// AND EVERY SECTION IS TICKABLE — all ten, by the label the user reads.
    #[test]
    fn every_section_has_a_tick_box() {
        let mut app = calculated();
        app.export_light_report();
        let t = dialog_text(&mut app);
        for s in crate::report::Section::all() {
            assert!(
                t.iter().any(|x| x == s.label()),
                "no tick box for {:?} ({:?})",
                s,
                s.label(),
            );
        }
    }

    /// THE DIALOG DRAWS — every panel, with a preview of a real document.
    #[test]
    fn the_dialog_and_its_preview_run() {
        let mut app = calculated();
        app.export_light_report();
        // NOT A SHAPE COUNT. This used to assert `shapes > 0`, and egui returns two dozen `Noop`
        // shapes on the frame it lays a window out in — so the test passed on a dialog that had
        // painted nothing whatever, and went on passing while controls were added to it.
        let t = dialog_text(&mut app);
        assert!(t.iter().any(|s| s == "Format"), "the dialog painted nothing: {t:?}");
        assert!(t.iter().any(|s| s.contains("Preview")), "the preview column is missing");
        assert!(app.report_open, "it closed itself");
    }

    /// THE PREVIEW IS THE DOCUMENT. Turning a section off has to change the pages on screen, or
    /// the preview is a picture of a report rather than of THIS report.
    #[test]
    fn the_preview_follows_the_options() {
        let mut app = calculated();
        app.export_light_report();
        let inp = app.report_input().expect("a calculation");
        let with_grid = crate::report::layout::layout(&inp, &app.report_opts).pages.len();
        drop(inp);

        app.report_opts.set(crate::report::Section::NumericGrid, false);
        app.report_opts.set(crate::report::Section::Results, false);
        let inp = app.report_input().expect("a calculation");
        let without = crate::report::layout::layout(&inp, &app.report_opts);
        assert!(
            !without
                .pages
                .iter()
                .flat_map(|p| p.items.iter())
                .any(|i| matches!(i, crate::report::pdf::Item::Text { text, .. }
                                  if text == "Illuminance grid (lx)")),
            "the grid is still in the document after being switched off",
        );
        assert!(without.pages.len() <= with_grid, "dropping sections made it longer");
    }

    /// THE FILE GOES WHERE THE DIALOG SAYS, in the format it says.
    #[test]
    fn the_report_is_written_where_it_was_asked_for() {
        let dir = std::env::temp_dir().join("simlux_report_test");
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).expect("scratch");

        let mut app = calculated();
        app.export_light_report();
        app.report_opts.out_dir = dir.to_string_lossy().into_owned();
        app.report_opts.file_stem = "gym".into();
        app.report_opts.title = "Gym".into();

        app.report_opts.format = crate::report::Format::Pdf;
        app.write_report();
        let pdf = dir.join("gym.pdf");
        assert!(pdf.is_file(), "no PDF was written");
        let bytes = std::fs::read(&pdf).expect("read");
        assert!(bytes.starts_with(b"%PDF-"), "the PDF is not a PDF");
        assert!(bytes.ends_with(b"%%EOF\n"), "the PDF did not finish");
        assert!(!app.report_open, "the dialog stayed open after a successful save");

        app.report_open = true;
        app.report_opts.format = crate::report::Format::Html;
        app.write_report();
        let html = dir.join("gym.html");
        assert!(html.is_file(), "no HTML was written");
        let text = std::fs::read_to_string(&html).expect("read");
        assert!(text.starts_with("<!doctype html>"), "the HTML is not HTML");
        assert!(text.contains("Gym"), "the title did not reach the file");

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// EACH LIST REPOINTS ITS OWN SLOTS, AND ONLY ITS OWN.
    ///
    /// The cover, the header and the footer each name a picture by INDEX. When all three kinds
    /// shared one list they all had to shift together whenever anything was removed — and this
    /// test asserted exactly that.
    ///
    /// They no longer share it: renders, logos and cover pictures are three lists, chosen from
    /// three buttons, because twice now a picture had to be added in the wrong place to get it
    /// where it was wanted. Which means the old shifting had become the very damage it existed to
    /// prevent — deleting a RENDER moved the header logo onto a different picture.
    #[test]
    fn removing_an_image_repoints_the_cover() {
        let mut app = calculated();
        let img = |n: &str| crate::report::ReportImage {
            path: format!("{n}.jpg"),
            caption: n.into(),
            jpeg: Some((vec![0xFF, 0xD8], 10, 10)),
        };
        for n in ["a", "b", "c"] {
            app.report_opts.images.push(img(n));
            app.report_tex.push(None);
            app.report_opts.logos.push(img(n));
            app.report_logo_tex.push(None);
            app.report_opts.covers.push(img(n));
            app.report_cover_tex.push(None);
        }
        app.report_open = true;

        // A RENDER GOES. The header and the cover point into other lists and must not move.
        app.report_opts.cover_image = Some(2);
        app.report_opts.header_image = Some(2);
        app.report_remove_image(0);
        assert_eq!(app.report_opts.images.len(), 2);
        assert_eq!(app.report_opts.images[0].caption, "b");
        assert_eq!(
            app.report_opts.header_image,
            Some(2),
            "removing a render moved the header logo onto a different picture",
        );
        assert_eq!(
            app.report_opts.cover_image,
            Some(2),
            "removing a render moved the cover onto a different picture",
        );
        assert_eq!(app.report_tex.len(), 2, "the preview textures went out of step");
    }

    /// A LOGO GOING TAKES THE HEADER AND FOOTER WITH IT — the list that actually owns them.
    #[test]
    fn removing_a_logo_repoints_the_header_and_footer() {
        let mut app = calculated();
        for n in ["a", "b", "c"] {
            app.report_opts.logos.push(crate::report::ReportImage {
                path: format!("{n}.png"),
                caption: n.into(),
                jpeg: Some((vec![0xFF, 0xD8], 10, 10)),
            });
            app.report_logo_tex.push(None);
        }
        app.report_opts.header_image = Some(2);
        app.report_opts.footer_image = Some(0);
        app.report_open = true;

        let mut act = crate::report::ui::Action::default();
        act.remove_logo = Some(0);
        app.apply_report_action(act);

        assert_eq!(app.report_opts.logos.len(), 2);
        assert_eq!(app.report_opts.header_image, Some(1), "the header did not follow its logo");
        assert_eq!(app.report_opts.footer_image, None, "the footer kept a dead index");
        assert_eq!(app.report_logo_tex.len(), 2, "the preview textures went out of step");
    }

    /// AND A COVER PICTURE CAN BE DROPPED. A list that can only grow is a list with a mistake in
    /// it for ever — the Add button is not much use without one.
    #[test]
    fn a_cover_picture_can_be_dropped() {
        let mut app = calculated();
        for n in ["a", "b"] {
            app.report_opts.covers.push(crate::report::ReportImage {
                path: format!("{n}.jpg"),
                caption: n.into(),
                jpeg: Some((vec![0xFF, 0xD8], 10, 10)),
            });
            app.report_cover_tex.push(None);
        }
        app.report_opts.cover_image = Some(1);
        app.report_open = true;

        let mut act = crate::report::ui::Action::default();
        act.remove_cover = Some(1);
        app.apply_report_action(act);
        assert_eq!(app.report_opts.covers.len(), 1);
        assert_eq!(app.report_opts.cover_image, None, "the cover kept a dead index");
        assert_eq!(app.report_cover_tex.len(), 1, "the preview textures went out of step");
    }


    /// THE DOCUMENT IS LAID OUT ONCE, NOT ONCE A FRAME.
    ///
    /// Reported as: *"the app starts lagging once the report window is open."* Laying it out is
    /// 123 ms on the owner's three-room plan in a RELEASE build, and it was happening on every
    /// frame the dialog was open — eight frames a second before a single widget had been drawn.
    ///
    /// Counted by LAYOUTS RUN — not by clock, and not by cache key. A timing assertion measures
    /// the build machine. And watching the cache KEY, which is what this test did first, cannot
    /// see the failure at all: a key that never matches is exactly as stable as one that always
    /// does, so the first version of this test passed against a cache deliberately broken to miss
    /// on every single frame. Counting the work is the only thing that answers the question.
    #[test]
    fn the_preview_is_not_rebuilt_every_frame() {
        let mut app = calculated();
        app.export_light_report();
        let ctx = egui::Context::default();
        let input = || egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::pos2(0.0, 0.0),
                egui::vec2(1600.0, 1000.0),
            )),
            ..Default::default()
        };

        // A FEW FRAMES TO SETTLE FIRST. The dialog is allowed to reach its resting state over the
        // opening frames — egui lays a window out before it paints it, and a setting may resolve
        // itself once on the way in. What is under test is that it STOPS; "rebuilt exactly once"
        // would fail on any harmless one-off while proving nothing extra.
        for _ in 0..3 {
            let _ = ctx.run(input(), |ctx| app.render_report_dialog(ctx));
        }
        let settled = crate::report::layout::LAYOUTS.with(|n| n.get());
        assert!(settled > 0, "the dialog never laid a document out at all");
        for _ in 0..10 {
            let _ = ctx.run(input(), |ctx| app.render_report_dialog(ctx));
        }
        let after_ten_more = crate::report::layout::LAYOUTS.with(|n| n.get());
        assert_eq!(
            after_ten_more, settled,
            "ten idle frames laid the document out {} more time(s)",
            after_ten_more - settled,
        );
        assert!(app.report_doc.is_some(), "the document was not kept");
    }

    /// AND IT IS REBUILT THE MOMENT SOMETHING WOULD CHANGE IT.
    ///
    /// The other half, and the one that decides whether the cache is worth having: a preview that
    /// does not follow the options is worse than a slow one, because it is wrong. Each of these is
    /// a different route into the document — the section list, the page size, the false-colour
    /// scale, a caption, and the calculation underneath.
    #[test]
    fn the_preview_follows_every_option() {
        let changes: Vec<(&str, fn(&mut CadApp))> = vec![
            ("a section switched off", |a: &mut CadApp| {
                a.report_opts.set(crate::report::Section::Schedule, false);
            }),
            ("the section order", |a: &mut CadApp| {
                a.report_opts.move_section(crate::report::Section::Renders, -1);
            }),
            ("the paper size", |a: &mut CadApp| {
                a.report_opts.page = crate::report::PageSize::Letter;
            }),
            ("the cover switched off", |a: &mut CadApp| a.report_opts.cover = false),
            ("the project name", |a: &mut CadApp| a.report_opts.title = "Gym".into()),
            ("the header text", |a: &mut CadApp| a.report_opts.header = "HSI".into()),
            ("the scale ceiling", |a: &mut CadApp| a.report_opts.scale.top = Some(750.0)),
            ("the scale bands", |a: &mut CadApp| a.report_opts.scale.bands = vec![50.0, 200.0]),
            ("the maintenance factor", |a: &mut CadApp| a.light.maintenance.llmf = 0.5),
            ("the eye height", |a: &mut CadApp| a.light.eye_height = 1.6),
            ("a wall reflectance", |a: &mut CadApp| a.light.materials[1].reflectance = 0.9),
            ("the palette", |a: &mut CadApp| a.light.ramp = crate::light::LuxRamp::Grey),
            ("a room renamed", |a: &mut CadApp| a.light.rooms[0].name = "Hall".into()),
            ("a new calculation", |a: &mut CadApp| {
                a.light.results_fingerprint = Some(1234);
            }),
        ];

        for (what, apply) in changes {
            let mut app = calculated();
            app.export_light_report();
            let ctx = egui::Context::default();
            let input = || egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(
                    egui::pos2(0.0, 0.0),
                    egui::vec2(1600.0, 1000.0),
                )),
                ..Default::default()
            };
            let _ = ctx.run(input(), |ctx| app.render_report_dialog(ctx));
            let before_key = app.report_doc_key.expect("a document");
            let before_n = crate::report::layout::LAYOUTS.with(|n| n.get());

            apply(&mut app);
            let _ = ctx.run(input(), |ctx| app.render_report_dialog(ctx));
            assert_ne!(
                app.report_doc_key,
                Some(before_key),
                "{what}: the key did not move, so the preview would not have redrawn",
            );
            assert!(
                crate::report::layout::LAYOUTS.with(|n| n.get()) > before_n,
                "{what}: the key moved but the document was not laid out again",
            );
        }
    }

    /// A LOGO WITH A TRANSPARENT BACKGROUND ARRIVES ON WHITE, NOT ON BLACK.
    ///
    /// Reported as: *"the logo image i uploaded are png images without background the but in the
    /// report they came with black background."* `to_rgb8` DISCARDS the alpha channel rather than
    /// resolving it, so a transparent pixel kept whatever colour sat underneath — which PNG
    /// writers leave as black. A logo exported with a transparent background therefore arrived as
    /// a black rectangle with the mark cut out of it.
    ///
    /// The fixture is the real case: a mark on a fully transparent field, with a half-transparent
    /// band, which is what anti-aliasing produces and what a threshold would ruin.
    ///
    /// IT IS 96 PIXELS WIDE FOR A REASON. The first version was four pixels across, and passed
    /// against a build with the fix removed — JPEG works in 8 × 8 blocks, and on an image smaller
    /// than one block the decoded values are a smear of everything in it rather than the pixels
    /// that went in. The bands here are wide enough that their centres come back as themselves.
    #[test]
    fn a_transparent_logo_is_flattened_onto_white() {
        let dir = std::env::temp_dir().join("simlux_logo_alpha");
        let _ = std::fs::create_dir_all(&dir);
        let path = dir.join("mark.png");

        // Three wide bands: fully transparent over black (what an exporter leaves behind), a
        // half-covered band, and the opaque mark itself.
        let img = image::RgbaImage::from_fn(96, 64, |x, _| match x {
            0..=31 => image::Rgba([0, 0, 0, 0]),
            32..=63 => image::Rgba([0, 0, 0, 128]),
            _ => image::Rgba([220, 40, 40, 255]),
        });
        img.save(&path).expect("write the fixture");

        let mut app = CadApp::default();
        app.report_add_image(&path.to_string_lossy(), None, crate::report::ImageSlot::Logo);
        assert_eq!(app.report_opts.logos.len(), 1, "the logo was not taken: {:?}", app.history);

        // Read the ENCODED bytes back, because that is what the PDF embeds.
        let (bytes, _, _) = app.report_opts.logos[0].jpeg.clone().expect("encoded");
        let back = image::load_from_memory(&bytes).expect("valid jpeg").to_rgb8();
        let px = |x: u32| back.get_pixel(x, 32).0;

        let clear = px(16);
        assert!(
            clear[0] > 235 && clear[1] > 235 && clear[2] > 235,
            "the transparent background came back as {clear:?} — it became a solid one",
        );
        let ink = px(80);
        assert!(ink[0] > 180 && ink[1] < 90, "the mark itself was lost: {ink:?}");
        // Half-covered black over white is mid grey. A threshold would have made it black or white
        // and left every logo in the report with a jagged edge.
        let edge = px(48);
        assert!(
            (100..=155).contains(&edge[0]),
            "the half-transparent band came back as {edge:?} rather than blended to mid grey",
        );
        let _ = std::fs::remove_dir_all(&dir);
    }
    /// THE SAVE BUTTON IS ON THE SCREEN — on a small display as well as a large one.
    ///
    /// Reported as: *"theres no option to export the report."* The option was there. It had been
    /// pushed off the bottom of the display by a preview that grew every frame, and a dialog whose
    /// Save button is past the edge of the screen is a report dialog that cannot produce a report.
    ///
    /// So this is not a test that the button EXISTS — `every_control_is_on_screen` covers that,
    /// and covered it while the bug was live, because a culled widget and an off-screen one are
    /// different things. It is a test of WHERE it is, at three display sizes including one small
    /// enough that a careless layout would overflow it.
    #[test]
    fn the_save_button_is_reachable_on_a_small_screen() {
        for (w, h) in [(1280.0_f32, 720.0_f32), (1600.0, 1025.0), (3440.0, 1349.0)] {
            let mut app = calculated();
            app.export_light_report();
            let ctx = egui::Context::default();
            let screen =
                egui::Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(w, h));
            let input = || egui::RawInput { screen_rect: Some(screen), ..Default::default() };

            // The button's own label, and where it was actually painted.
            let mut found: Option<egui::Rect> = None;
            for _ in 0..12 {
                let out = ctx.run(input(), |ctx| app.render_report_dialog(ctx));
                fn walk(s: &egui::Shape, into: &mut Option<egui::Rect>) {
                    match s {
                        egui::Shape::Text(t) if t.galley.text().trim().starts_with("Save ") => {
                            *into = Some(egui::Rect::from_min_size(t.pos, t.galley.size()));
                        }
                        egui::Shape::Vec(v) => v.iter().for_each(|s| walk(s, into)),
                        _ => {}
                    }
                }
                let mut this = None;
                for cs in &out.shapes {
                    walk(&cs.shape, &mut this);
                }
                if this.is_some() {
                    found = this;
                }
            }
            let r = found.unwrap_or_else(|| panic!("{w}x{h}: the Save button never painted"));
            assert!(
                screen.contains_rect(r),
                "{w}x{h}: the Save button is at {:?}, off a screen of {:?}",
                r,
                screen,
            );
        }
    }

    /// A REPORT BUILT ON AN OUT-OF-DATE CALCULATION SAYS SO, IN THE DIALOG.
    ///
    /// The report is the one thing this app produces that leaves the building, and on paper a lux
    /// figure for a layout somebody has since changed is indistinguishable from one that is right.
    /// The panel's own warning is not enough: it is possible to open the report dialog without
    /// having looked at the panel at all.
    #[test]
    fn the_dialog_warns_when_the_calculation_is_out_of_date() {
        let mut app = calculated();
        app.export_light_report();
        let fresh = dialog_text(&mut app);
        assert!(
            !fresh.iter().any(|s| s.contains("OUT OF DATE")),
            "a current calculation was labelled out of date",
        );

        let mut app = calculated();
        app.light.results_stale = true;
        app.export_light_report();
        let t = dialog_text(&mut app);
        assert!(
            t.iter().any(|s| s.contains("OUT OF DATE")),
            "the dialog said nothing about a stale calculation: {t:?}",
        );
    }

    /// THE PREVIEW IS THE SAME SIZE ON EVERY FRAME IT IS OPEN.
    ///
    /// Reported as: *"when the calculation preview sort of loads and expands as its opened. its
    /// looks very buggy."*
    ///
    /// It was a feedback loop. The preview took `ui.available_size()` and the window sized itself
    /// to its contents, so each frame the preview grew to whatever the window had become and the
    /// window grew to fit the preview — visible as a panel inflating for several frames after the
    /// dialog opens, which reads as a rendering fault rather than as a layout settling.
    ///
    /// The frames are compared against EACH OTHER rather than against an expected size: what was
    /// wrong was the growing, and pinning a number here would only record today's dimensions.
    #[test]
    fn the_preview_does_not_grow_after_it_opens() {
        let mut app = calculated();
        app.export_light_report();

        let ctx = egui::Context::default();
        let input = || egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::pos2(0.0, 0.0),
                egui::vec2(1600.0, 1000.0),
            )),
            ..Default::default()
        };
        // The preview's backing rectangle — the one thing on the dialog painted in this grey.
        fn preview_rect(out: &egui::FullOutput) -> Option<egui::Rect> {
            fn walk(s: &egui::Shape, into: &mut Vec<egui::Rect>) {
                match s {
                    egui::Shape::Rect(r) if r.fill == egui::Color32::from_gray(40) => {
                        into.push(r.rect)
                    }
                    egui::Shape::Vec(v) => v.iter().for_each(|s| walk(s, into)),
                    _ => {}
                }
            }
            let mut found = Vec::new();
            for cs in &out.shapes {
                walk(&cs.shape, &mut found);
            }
            found.into_iter().next()
        }

        // TWELVE FRAMES. egui does not paint a window on the frame it first lays out, and this one
        // carries a scroll area that settles over a few more, so the preview does not appear at all
        // for the first handful — which is itself part of what the report is about.
        let mut sizes: Vec<egui::Vec2> = Vec::new();
        for _ in 0..12 {
            let out = ctx.run(input(), |ctx| app.render_report_dialog(ctx));
            if let Some(r) = preview_rect(&out) {
                sizes.push(r.size());
            }
        }
        assert!(sizes.len() >= 4, "the preview painted on only {} frames", sizes.len());
        let first = sizes[0];
        for (i, s) in sizes.iter().enumerate() {
            assert!(
                (s.x - first.x).abs() < 0.5 && (s.y - first.y).abs() < 0.5,
                "the preview was {:.0}x{:.0} on the first painted frame and {:.0}x{:.0} on frame \
                 {i} — it is still growing after it opened: {sizes:?}",
                first.x,
                first.y,
                s.x,
                s.y,
            );
        }
    }

    /// AND IT IS THE SHAPE OF THE PAGE IT IS PREVIEWING.
    ///
    /// A preview box shaped by whatever space was left over shows an A4 page letterboxed inside
    /// it, with the wasted band reading as part of the document. Sizing the box from the page's
    /// own proportions is also what makes the size deterministic — it depends on the document,
    /// which is known before anything is laid out, rather than on the window, which is not.
    #[test]
    fn the_preview_has_the_proportions_of_the_page() {
        let mut app = calculated();
        app.report_opts.page = crate::report::PageSize::A4;
        app.export_light_report();

        let ctx = egui::Context::default();
        let input = || egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::pos2(0.0, 0.0),
                egui::vec2(1600.0, 1000.0),
            )),
            ..Default::default()
        };
        fn preview_rect(out: &egui::FullOutput) -> Option<egui::Rect> {
            fn walk(s: &egui::Shape, into: &mut Vec<egui::Rect>) {
                match s {
                    egui::Shape::Rect(r) if r.fill == egui::Color32::from_gray(40) => {
                        into.push(r.rect)
                    }
                    egui::Shape::Vec(v) => v.iter().for_each(|s| walk(s, into)),
                    _ => {}
                }
            }
            let mut found = Vec::new();
            for cs in &out.shapes {
                walk(&cs.shape, &mut found);
            }
            found.into_iter().next()
        }

        let mut last = None;
        for _ in 0..12 {
            let out = ctx.run(input(), |ctx| app.render_report_dialog(ctx));
            if let Some(r) = preview_rect(&out) {
                last = Some(r);
            }
        }
        let r = last.expect("the preview painted");
        let (pw, ph) = crate::report::PageSize::A4.points();
        let want = ph / pw;
        let got = (r.height() / r.width()) as f64;
        assert!(
            (got - want).abs() < 0.05,
            "the preview is {got:.3} tall-to-wide for a page that is {want:.3}",
        );
    }
}

/// THE OWNER'S OWN THREE-ROOM FILE.
///
/// `testfile2.dxf` is the plan the multi-room work was reported against — three rooms, 23 fittings
/// of one type. Ignored by default because it lives in the owner's Dropbox rather than the repo;
/// run it with the path when the calculation's room handling changes:
///
/// ```text
/// $env:SIMLUX_PROJECT="D:\Dropbox\YASEEN\3d factory\tests\initial test result\testfile2"
/// cargo test -p cad_app the_owners_three_room_plan -- --ignored --nocapture
/// ```
///
/// What it checks is what the synthetic rooms cannot: that a REAL plan's rooms are found, that its
/// fittings land in them, and that every room comes back lit.
#[cfg(test)]
mod the_owners_three_room_plan {
    use super::*;

    /// WHAT THE PHOTOMETRY IN THIS PROJECT ACTUALLY SAYS.
    ///
    /// Asked as: "why does it look like point sources here is it because somethings wrong with the
    /// ldt file or our fault?" — about a results page showing perfectly circular pools under what
    /// are 2 m linear luminaires. There are two candidate answers and they need telling apart
    /// before anything is changed:
    ///
    ///   1. THE FILE. A distribution with one C-plane, or with every C-plane identical, IS
    ///      rotationally symmetric — it describes a fitting that throws the same light in every
    ///      direction around its axis, and a correct engine draws circles for it.
    ///   2. US. Every luminaire is treated as a POINT at its centre (`calc::direct` is a plain
    ///      inverse-square sum). The usual rule is that a point approximation holds beyond about
    ///      five times the largest luminous dimension — 10 m for a 2 m batten — and this plan
    ///      measures 2.1 m below the fittings, well inside that.
    ///
    /// This prints the evidence rather than arguing from either.
    #[test]
    #[ignore = "needs SIMLUX_PROJECT=<path without extension>"]
    fn what_the_photometry_says() {
        let Ok(stem) = std::env::var("SIMLUX_PROJECT") else { return };
        let dxf = format!("{stem}.dxf");
        let cfg = crate::simlux_io::load(std::path::Path::new(&dxf))
            .expect("the sidecar must read")
            .expect("the project must have a sidecar");

        println!("profiles in this project: {}", cfg.ies_library.len());
        for (name, p) in &cfg.ies_library {
            let planes = p.horizontal_angles.len();
            // Do the C-planes actually DIFFER? A file can carry twelve of them and repeat one.
            let mut spread = 0.0_f64;
            if planes > 1 {
                let n = p.candela.first().map(|r| r.len()).unwrap_or(0);
                for i in 0..n {
                    let (mut lo, mut hi) = (f64::MAX, f64::MIN);
                    for row in &p.candela {
                        if let Some(v) = row.get(i) {
                            lo = lo.min(*v);
                            hi = hi.max(*v);
                        }
                    }
                    if hi > 0.0 {
                        spread = spread.max((hi - lo) / hi);
                    }
                }
            }
            println!(
                "  {name:<34} C-planes {planes:>3}  γ {:>3}  peak {:>8.1} cd  \
                 luminous {:.3} × {:.3} m  overall {:.3} × {:.3} m",
                p.vertical_angles.len(),
                p.peak_candela(),
                p.luminous_length,
                p.luminous_width,
                p.length,
                p.width,
            );
            println!(
                "  {:<34} C-plane spread {:.1}%  →  {}",
                "",
                spread * 100.0,
                if planes <= 1 || spread < 0.02 {
                    "AXIALLY SYMMETRIC — this file describes a round distribution"
                } else {
                    "asymmetric — the file does distinguish along/across"
                },
            );
            // The near-field question, for the mounting height this project uses.
            let biggest = p.luminous_length.max(p.luminous_width).max(p.length).max(p.width) as f64;
            if biggest > 0.0 {
                println!(
                    "  {:<34} point-source approximation needs ≥ {:.1} m; this plan measures at \
                     about 2.1 m",
                    "",
                    biggest * 5.0,
                );
            }
        }

        // WHICH FITTINGS ARE WHERE. A round pool under a 36° downlight is correct and a round pool
        // under a 2 m batten is not, so the answer depends entirely on which room is being looked
        // at. Grouped by profile with the extent they cover, which is enough to name the room.
        println!("\nplaced fittings by type:");
        let mut by: std::collections::BTreeMap<String, Vec<&cad_light::Luminaire>> =
            Default::default();
        for l in &cfg.luminaires {
            by.entry(l.profile.clone()).or_default().push(l);
        }
        for (name, ls) in &by {
            let (mut x0, mut y0, mut x1, mut y1) = (f32::MAX, f32::MAX, f32::MIN, f32::MIN);
            for l in ls {
                x0 = x0.min(l.position.x);
                y0 = y0.min(l.position.y);
                x1 = x1.max(l.position.x);
                y1 = y1.max(l.position.y);
            }
            let rots: std::collections::BTreeSet<i32> =
                ls.iter().map(|l| l.rotation_deg.round() as i32).collect();
            println!(
                "  {:>3} × {name:<34} over x {x0:>7.2}..{x1:<7.2} y {y0:>7.2}..{y1:<7.2}  \
                 z {:.2}  rotations {rots:?}",
                ls.len(),
                ls.first().map(|l| l.position.z).unwrap_or(0.0),
            );
        }
    }

    #[test]
    #[ignore = "needs SIMLUX_PROJECT=<path without extension>"]
    fn every_room_is_calculated_and_lit() {
        let Ok(stem) = std::env::var("SIMLUX_PROJECT") else { return };
        let dxf = format!("{stem}.dxf");
        let cfg = crate::simlux_io::load(std::path::Path::new(&dxf))
            .expect("the sidecar must read")
            .expect("the project must have a sidecar");

        let mut app = CadApp::default();
        app.factory.apply_persist(cfg.factory.clone());
        app.factory.recompute();
        app.light.apply_config(cfg, &app.doc);

        let plan = CadApp::plan_doc_of(app.factory.session.as_ref(), &app.doc).clone();
        app.light.calculate(&plan, Some(&app.factory));

        println!("rooms calculated: {}", app.light.rooms.len());
        let mut placed = 0usize;
        let mut generated = 0usize;
        for r in &app.light.rooms {
            println!(
                "  {:10} {:>3}x{:<3} plane {:6.2} x {:6.2} m  avg {:7.1} lx  min {:6.1}  U0 {:.2}  \
                 {:2} fitting(s)",
                r.name,
                r.plane.cols,
                r.plane.rows,
                r.plane.width,
                r.plane.depth,
                r.grid.avg,
                r.grid.min,
                r.grid.u0(),
                r.fixtures.len(),
            );
            // A room holds user-placed fixtures AND the lights the model generates — a curved
            // luminaire is a real fitting. Generated ids start at a million, which is how they
            // are told apart.
            placed += r.fixtures.iter().filter(|l| l.id < 1_000_000).count();
            generated += r.fixtures.iter().filter(|l| l.id >= 1_000_000).count();
        }
        println!("placed {placed}, generated {generated}");
        println!("cores: {}", std::thread::available_parallelism().map(|n| n.get()).unwrap_or(0));
        for (k, v) in &app.light.last_timings {
            println!("  phase {k:<12} {v:>10.1}");
        }

        // WHAT ONE FRAME OF THE REPORT DIALOG COSTS. The preview is the document, laid out from
        // scratch; on a plan this size that is the difference between a dialog and a slideshow.
        for _ in 0..3 {
            let t = std::time::Instant::now();
            let inp = app.report_input().expect("a report input");
            let gather = t.elapsed().as_secs_f64() * 1000.0;
            let t2 = std::time::Instant::now();
            let doc = crate::report::layout::layout(&inp, &app.report_opts);
            println!(
                "  report frame: gather {:>7.1} ms   layout {:>7.1} ms   → {} pages",
                gather,
                t2.elapsed().as_secs_f64() * 1000.0,
                doc.pages.len(),
            );
        }

        assert_eq!(app.light.rooms.len(), 3, "this plan has three rooms");
        for r in &app.light.rooms {
            assert!(r.grid.avg > 1.0, "{} came out at {:.2} lx — unlit", r.name, r.grid.avg);
            assert!(!r.fixtures.is_empty(), "{} has no fittings in it", r.name);
        }
        assert_eq!(
            placed,
            app.light.luminaires.len(),
            "{} of {} PLACED fittings were claimed by a room",
            placed,
            app.light.luminaires.len(),
        );
        // Every fixture a room claims must be one the schedule can describe. Ids alone could not
        // do this: the generated lights exist only for the length of a calculation.
        for r in &app.light.rooms {
            let sched = app.schedule_for(&r.fixtures);
            let listed: usize = sched.iter().map(|s| s.count).sum();
            assert_eq!(
                listed,
                r.fixtures.len(),
                "{}: the schedule lists {listed} of {} fittings",
                r.name,
                r.fixtures.len(),
            );
        }
    }

    /// EXACTLY WHAT THE REPORT WILL SAY — recalculated from the project, both grids side by side.
    ///
    /// The check to run against a DIALux or Relux report by hand after touching which grid is
    /// quoted. It prints the working grid, the standard's grid, and the figures the report derives
    /// from cells rather than from the summary — the extremes and the percentiles — because those
    /// are the ones that need the mask and so are the ones a change here breaks quietly.
    ///
    /// `SIMLUX_PROJECT=<path without extension> cargo test -p cad_app --bin simlux --release
    ///  what_the_report_will_quote -- --ignored --nocapture`
    #[test]
    #[ignore = "needs SIMLUX_PROJECT=<path without extension>"]
    fn what_the_report_will_quote() {
        let Ok(stem) = std::env::var("SIMLUX_PROJECT") else { return };
        let dxf = format!("{stem}.dxf");
        let cfg = crate::simlux_io::load(std::path::Path::new(&dxf))
            .expect("the sidecar must read")
            .expect("the project must have a sidecar");
        let mut app = CadApp::default();
        app.factory.apply_persist(cfg.factory.clone());
        app.factory.recompute();
        app.light.apply_config(cfg, &app.doc);
        let plan = CadApp::plan_doc_of(app.factory.session.as_ref(), &app.doc).clone();
        app.light.calculate(&plan, Some(&app.factory));

        for r in &app.light.rooms {
            let pct = |g: &cad_light::LuxGrid, m: &[bool], p: f64| -> f64 {
                let mut v: Vec<f64> = g
                    .values
                    .iter()
                    .enumerate()
                    .filter(|(i, _)| m.get(*i).copied().unwrap_or(true))
                    .map(|(_, x)| *x)
                    .collect();
                v.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
                if v.is_empty() { 0.0 } else { v[(((v.len() - 1) as f64) * p).round() as usize] }
            };
            println!("\n=== {} ===", r.name);
            for (label, g, m, sp) in [
                ("working ", &r.grid, r.mask.as_slice(), r.spacing()),
                ("EN 12464", &r.grid_en, r.mask_en.as_slice(), r.spacing_en()),
            ] {
                println!(
                    "  {label}  {:>3} x {:<3} at {sp:.3} m   avg {:7.1}   min {:6.1}   max {:7.1}   \
                     U0 {:.2}   p10 {:6.1}   p90 {:7.1}   {} cell(s) excluded",
                    g.cols,
                    g.rows,
                    g.avg,
                    g.min,
                    g.max,
                    g.u0(),
                    pct(g, m, 0.1),
                    pct(g, m, 0.9),
                    m.iter().filter(|k| !**k).count(),
                );
            }
            println!("  THE REPORT QUOTES the EN 12464 line above.");
        }
    }
}

/// SAVING AS DWG.
///
/// Asked as "why cant i save as dwg?" and then "and fix the file saving". The save path took
/// `.dxf` and `.rsm` and said so, which answers the question without solving it: a practice's
/// filing, its consultants and its clients ask for `.dwg`.
///
/// DWG IS A CLOSED FORMAT and nothing here writes one. The drawing goes out as the DXF this app
/// already writes, and AutoCAD's own headless core saves it on — the same tool, running the other
/// way, that opens a DWG today. Every test below uses a STUB converter rather than looking for
/// AutoCAD: a test that needed it would run on one machine and quietly skip on every other, which
/// is much the same as not having one.
#[cfg(test)]
mod a_drawing_can_be_saved_as_dwg {
    use super::*;

    /// A converter that just copies its input to its output — enough to prove the plumbing.
    // MUST CONTAIN `{in}`, or it is treated as a bare executable name rather than a shell
    // command — which is how the first version of these tests failed, with "cannot find the path".
    fn stub() -> &'static str {
        if cfg!(windows) { "copy /y \"{in}\" \"{out}\"" } else { "cp {in} {out}" }
    }

    // Runs, exits zero, and writes nothing.
    fn stub_that_writes_nothing() -> &'static str {
        if cfg!(windows) { "echo {in} 1>nul" } else { "true {in}" }
    }

    /// THE ENVIRONMENT IS PROCESS-WIDE and tests run in parallel, so the two that set
    /// `RUSTCAD_DXF2DWG` have to take turns. They did not at first, and one duly picked up the
    /// other's deliberately-broken converter and failed for a reason that had nothing to do with
    /// what it was testing.
    static ENV: std::sync::Mutex<()> = std::sync::Mutex::new(());

    fn tmp(name: &str) -> std::path::PathBuf {
        let d = std::env::temp_dir().join("simlux_dwg_save");
        let _ = std::fs::create_dir_all(&d);
        d.join(name)
    }

    #[test]
    fn the_converter_is_run_and_its_output_is_the_file() {
        let dxf = tmp("in.dxf");
        let dwg = tmp("out.dwg");
        std::fs::write(&dxf, b"  0\nSECTION\n").expect("the dxf");
        let _ = std::fs::remove_file(&dwg);

        convert_dxf_to_dwg(stub(), &dxf, &dwg).expect("the stub converter runs");
        assert!(dwg.is_file(), "no file at {}", dwg.display());
        assert_eq!(std::fs::read(&dwg).expect("read"), b"  0\nSECTION\n");
        let _ = std::fs::remove_file(&dxf);
        let _ = std::fs::remove_file(&dwg);
    }

    /// A CONVERTER THAT PRODUCES NOTHING IS A FAILURE, whatever it claims.
    ///
    /// accoreconsole is cheerful about failure: a script that stopped at a prompt still exits
    /// zero. The DWG→DXF direction learned that the hard way — "the only symptom is a DXF that
    /// never appears" — so existence, not the exit code, is what is believed.
    #[test]
    fn a_converter_that_writes_nothing_is_reported() {
        let dxf = tmp("in2.dxf");
        let dwg = tmp("out2.dwg");
        std::fs::write(&dxf, b"x").expect("the dxf");
        let _ = std::fs::remove_file(&dwg);

        let e = convert_dxf_to_dwg(stub_that_writes_nothing(), &dxf, &dwg)
            .expect_err("a silent failure must be caught");
        assert!(e.contains("produced no file"), "unhelpful: {e}");
        assert!(e.contains("run"), "the message must say what to do next: {e}");
        let _ = std::fs::remove_file(&dxf);
    }

    /// AND A FAILED SAVE DOES NOT DESTROY THE FILE IT WAS SAVING OVER.
    ///
    /// The whole reason the DXF goes to a temp file first. Writing it straight onto the `.dwg` and
    /// converting in place would, on any failure, leave a DXF wearing a `.dwg` name — a file that
    /// opens in nothing and reads as corrupt, in place of the drawing that was there.
    #[test]
    fn a_failed_conversion_leaves_the_previous_dwg_alone() {
        let path = tmp("keep.dwg");
        std::fs::write(&path, b"the previous drawing").expect("seed");

        let doc = Document::default();
        let cfg = crate::simlux_io::SimluxConfig::default();
        let _guard = ENV.lock().unwrap_or_else(|e| e.into_inner());
        // A converter that cannot be run at all.
        std::env::set_var("RUSTCAD_DXF2DWG", "simlux-no-such-converter-xyz {in} {out}");
        let r = save_file_worker(&path.to_string_lossy(), doc, cfg, Vec::new());
        std::env::remove_var("RUSTCAD_DXF2DWG");

        assert!(r.is_err(), "a save that could not convert reported success");
        assert_eq!(
            std::fs::read(&path).expect("still there"),
            b"the previous drawing",
            "the drawing that was already there was overwritten by a failed save",
        );
        let _ = std::fs::remove_file(&path);
    }

    /// THE EXTENSION IS ACCEPTED. Before, `.dwg` fell through to "unknown extension (expected .dxf
    /// or .rsm)" — the message in the report.
    #[test]
    fn dwg_is_no_longer_an_unknown_extension() {
        let path = tmp("ext.dwg");
        let _ = std::fs::remove_file(&path);
        let _guard = ENV.lock().unwrap_or_else(|e| e.into_inner());
        std::env::set_var("RUSTCAD_DXF2DWG", stub());
        let r = save_file_worker(
            &path.to_string_lossy(),
            Document::default(),
            crate::simlux_io::SimluxConfig::default(),
            Vec::new(),
        );
        std::env::remove_var("RUSTCAD_DXF2DWG");

        match r {
            Ok(_) => assert!(path.is_file(), "the save reported success and wrote no file"),
            Err(e) => panic!("a .dwg save failed: {e}"),
        }
        // What landed is what the converter was given — the DXF this app writes.
        let head = std::fs::read_to_string(&path).unwrap_or_default();
        assert!(head.contains("SECTION"), "the file does not look like the drawing that was sent");
        let _ = std::fs::remove_file(&path);
    }

    /// AND AN UNKNOWN ONE STILL IS, naming every format that works.
    #[test]
    fn an_unknown_extension_still_says_which_ones_work() {
        let e = save_file_worker(
            "whatever.pdf",
            Document::default(),
            crate::simlux_io::SimluxConfig::default(),
            Vec::new(),
        );
        let e = match e {
            Err(e) => e,
            Ok(_) => panic!("a .pdf was accepted as a drawing"),
        };
        for want in [".dxf", ".dwg", ".rsm"] {
            assert!(e.contains(want), "{want} is missing from {e:?}");
        }
    }
}


/// WHERE THE ZEROES ARE.
///
/// Reported as: "our min lux was 0 while for relux it was 133… its an obvious error. find the root
/// cause." A minimum of exactly zero is not a low reading, it is a point that received nothing at
/// all — which in a room with five bounces of interreflection is impossible unless the point is
/// enclosed. This prints where they are, so the answer comes from the grid rather than a guess.
///
///     RESULT=<path to .simlux-result.json> cargo test -p cad_app --bin simlux where_the_zeroes_are -- --ignored --nocapture
#[cfg(test)]
mod result_forensics {
    #[test]
    #[ignore = "needs RESULT=<path>"]
    fn where_the_zeroes_are() {
        let Ok(path) = std::env::var("RESULT") else { return };
        let text = std::fs::read_to_string(&path).expect("read the result");
        let stored: crate::light_store::StoredResults =
            serde_json::from_str(&text).expect("parse the result");
        let rooms = stored.rooms().expect("rebuild the rooms");
        for r in &rooms {
            let g = &r.grid;
            let (gc, gr) = (g.cols as usize, g.rows as usize);
            let p = &r.plane;
            println!(
                "\n{}: {gc}x{gr} over {:.2} x {:.2} m at z {:.2}",
                r.name, p.width, p.depth, p.origin.z
            );
            println!("  avg {:.1}  min {:.1}  max {:.1}", g.avg, g.min, g.max);

            let inside = |i: usize| r.mask.get(i).copied().unwrap_or(true);
            let mut lows: Vec<(f64, f32, f32)> = Vec::new();
            let mut n_in = 0usize;
            let mut n_zero = 0usize;
            for j in 0..gr {
                for i in 0..gc {
                    let k = j * gc + i;
                    if !inside(k) {
                        continue;
                    }
                    n_in += 1;
                    let v = g.values.get(k).copied().unwrap_or(0.0);
                    let x = p.origin.x + (i as f32 + 0.5) * (p.width / gc as f32);
                    let y = p.origin.y + (j as f32 + 0.5) * (p.depth / gr as f32);
                    if v < 1.0 {
                        n_zero += 1;
                    }
                    lows.push((v, x, y));
                }
            }
            lows.sort_by(|a, b| a.0.partial_cmp(&b.0).expect("finite"));
            println!("  {n_in} cells in the room, {n_zero} of them under 1 lx");
            println!("  the twelve darkest:");
            for (v, x, y) in lows.iter().take(12) {
                println!("    {v:8.2} lx at ({x:7.2}, {y:7.2})");
            }
            // What the room would report if those cells were not there.
            let kept: Vec<f64> = lows.iter().map(|l| l.0).filter(|v| *v >= 1.0).collect();
            if !kept.is_empty() {
                let mn = kept.iter().cloned().fold(f64::MAX, f64::min);
                let avg = kept.iter().sum::<f64>() / kept.len() as f64;
                println!("  ignoring cells under 1 lx: min {mn:.1}, avg {avg:.1}");
            }
        }
    }
}

#[cfg(test)]
mod max_forensics {
    #[test]
    #[ignore = "needs RESULT=<path>"]
    fn how_much_of_the_peak_is_the_grid() {
        let Ok(path) = std::env::var("RESULT") else { return };
        let text = std::fs::read_to_string(&path).expect("read");
        let stored: crate::light_store::StoredResults = serde_json::from_str(&text).expect("parse");
        for r in stored.rooms().expect("rooms") {
            let g = &r.grid;
            let (gc, gr) = (g.cols as usize, g.rows as usize);
            let p = &r.plane;
            let cell = p.width / gc as f32;
            println!("\n{}: {gc}x{gr}, cells {:.3} m, max {:.1} lx", r.name, cell, g.max);
            // What a COARSER grid would have reported, over every possible phase.
            for step in [2usize, 3, 4] {
                let mut best = f64::MIN;
                let mut worst = f64::MAX;
                for oy in 0..step {
                    for ox in 0..step {
                        let mut m = f64::MIN;
                        for j in (oy..gr).step_by(step) {
                            for i in (ox..gc).step_by(step) {
                                let k = j * gc + i;
                                if r.mask.get(k).copied().unwrap_or(true) {
                                    m = m.max(g.values[k]);
                                }
                            }
                        }
                        best = best.max(m);
                        worst = worst.min(m);
                    }
                }
                println!(
                    "  at {:.2} m spacing ({}x coarser): max lands between {worst:.0} and {best:.0} lx",
                    cell * step as f32, step,
                );
            }
        }
    }

    /// HOW WIDE IS THE PEAK? — the question behind "our max is 1800 and theirs is 1400".
    ///
    /// A maximum is the brightest CELL CENTRE on a grid, so whether a tool reports the peak under a
    /// downlight depends on whether it puts a point there. That is only worth saying if the peak is
    /// genuinely narrow, which is a fact about the field and is measurable: how much of the room
    /// stands above each level, and how far across the bright patch actually is.
    ///
    /// `RESULT=path/to/x.simlux-result.json cargo test -p cad_app --bin simlux --release
    ///  how_wide_is_the_peak -- --ignored --nocapture`
    #[test]
    #[ignore]
    fn how_wide_is_the_peak() {
        let Ok(path) = std::env::var("RESULT") else { return };
        let text = std::fs::read_to_string(&path).expect("read");
        let stored: crate::light_store::StoredResults = serde_json::from_str(&text).expect("parse");
        for r in stored.rooms().expect("rooms") {
            let g = &r.grid;
            let (gc, gr) = (g.cols as usize, g.rows as usize);
            let p = &r.plane;
            let (cw, ch) = (p.width / gc as f32, p.depth / gr as f32);
            println!("\n{}: {gc}x{gr}, cells {cw:.3} x {ch:.3} m", r.name);
            println!("  avg {:.1}  min {:.1}  max {:.1} lx", g.avg, g.min, g.max);

            let live = |k: usize| r.mask.get(k).copied().unwrap_or(true);
            let total = (0..gc * gr).filter(|k| live(*k)).count();

            for cut in [1700.0_f64, 1600.0, 1400.0, 1200.0, 1000.0, 800.0] {
                let mut n = 0usize;
                let (mut lo_x, mut hi_x, mut lo_y, mut hi_y) =
                    (usize::MAX, 0usize, usize::MAX, 0usize);
                for j in 0..gr {
                    for i in 0..gc {
                        let k = j * gc + i;
                        if live(k) && g.values[k] >= cut {
                            n += 1;
                            lo_x = lo_x.min(i);
                            hi_x = hi_x.max(i);
                            lo_y = lo_y.min(j);
                            hi_y = hi_y.max(j);
                        }
                    }
                }
                if n == 0 {
                    println!("  above {cut:>6.0} lx: nothing");
                    continue;
                }
                println!(
                    "  above {cut:>6.0} lx: {n:>4} of {total} cells ({:>4.1}% of the room), \
                     bounding box {:.2} x {:.2} m",
                    100.0 * n as f64 / total as f64,
                    (hi_x - lo_x + 1) as f32 * cw,
                    (hi_y - lo_y + 1) as f32 * ch,
                );
            }

            // THE PEAK CELL, and how fast it falls away from it — the shape of the spike.
            let peak = (0..gc * gr).filter(|k| live(*k)).max_by(|a, b| {
                g.values[*a].partial_cmp(&g.values[*b]).unwrap_or(std::cmp::Ordering::Equal)
            });
            if let Some(k) = peak {
                let (pi, pj) = (k % gc, k / gc);
                println!(
                    "  peak cell ({pi}, {pj}) = {:.0} lx. Walking away in x, one cell ({cw:.3} m) \
                     at a time:",
                    g.values[k],
                );
                let mut line = String::new();
                for d in 0..=7 {
                    if pi + d < gc {
                        line.push_str(&format!("{:>7.0}", g.values[pj * gc + pi + d]));
                    }
                }
                println!("   {line}");
            }
        }
    }
}
